package dev.dutchy.runelite.gear;

import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;

/** Keeps the setups an owner's list shows: an account sees its own plus the shared ones, the shared list sees shared only. */
public final class AccountFilter {

    private AccountFilter() {
    }

    public static List<GearSection> apply(List<GearSection> sections, Owner viewed) {
        Objects.requireNonNull(sections, "sections");
        Objects.requireNonNull(viewed, "viewed");
        return sections.stream()
                .map(section -> section.withSetups(section.setups().stream()
                        .filter(setup -> shows(viewed, setup.owner()))
                        .collect(Collectors.toList())))
                .collect(Collectors.toList());
    }

    public static boolean shows(Owner viewed, Owner owner) {
        return owner.isShared() || owner.equals(viewed);
    }
}

package dev.dutchy.runelite.gear;

import dev.dutchy.runelite.gear.content.CellKind;
import dev.dutchy.runelite.gear.content.LayoutCell;
import dev.dutchy.runelite.gear.content.SetupVariant;
import dev.dutchy.runelite.gear.layout.EquipmentBlock;
import dev.dutchy.runelite.gear.layout.GridBlock;
import dev.dutchy.runelite.gear.layout.Layout;
import dev.dutchy.runelite.gear.layout.LayoutBlock;
import lombok.Value;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

/** Every equipment set or inventory in the book that could be copied into a cell of the given kind. */
public final class CellSources {

    private CellSources() {
    }

    /** One copyable part of a setup, already shaped as the cell it would become. */
    @Value
    public static class Source {
        String setupName;
        String partName;
        LayoutCell cell;

        public Source(String setupName, String partName, LayoutCell cell) {
            this.setupName = Objects.requireNonNull(setupName, "setupName");
            this.partName = Objects.requireNonNull(partName, "partName");
            this.cell = Objects.requireNonNull(cell, "cell");
        }

        public String label() {
            return setupName + " · " + partName;
        }
    }

    public static List<Source> of(List<GearSection> sections, CellKind kind, SetupId exclude) {
        Objects.requireNonNull(sections, "sections");
        Objects.requireNonNull(kind, "kind");
        List<Source> sources = new ArrayList<>();
        for (GearSection section : sections) {
            for (GearSetup setup : section.setups()) {
                if (setup.id().equals(exclude)) {
                    continue;
                }
                for (SetupVariant variant : setup.variants()) {
                    String setupName = setup.hasVariants() ? setup.name() + " (" + variant.name() + ")" : setup.name();
                    for (LayoutBlock block : Layout.of(variant.content()).blocks()) {
                        partOf(block, kind).ifPresent(cell -> sources.add(new Source(setupName, block.title(), cell)));
                    }
                }
            }
        }
        return List.copyOf(sources);
    }

    private static Optional<LayoutCell> partOf(LayoutBlock block, CellKind kind) {
        if (block.isEmpty()) {
            return Optional.empty();
        }
        return block.accept(new LayoutBlock.Visitor<>() {
            @Override
            public Optional<LayoutCell> equipment(EquipmentBlock equipment) {
                return kind == CellKind.EQUIPMENT ? Optional.of(LayoutCell.equipment(equipment.equipment())) : Optional.empty();
            }

            @Override
            public Optional<LayoutCell> grid(GridBlock grid) {
                return kind == CellKind.INVENTORY ? Optional.of(LayoutCell.inventory(grid.grid())) : Optional.empty();
            }
        });
    }
}

package dev.dutchy.runelite.gear;

/** A colour a setup can be labelled with; orange is reserved for the active highlight. */
public enum ColourLabel {
    NONE(0x000000),
    RED(0xD9534F),
    GREEN(0x5CB85C),
    BLUE(0x4AA3FF),
    PURPLE(0xA46BE0),
    TEAL(0x3BBFB0),
    YELLOW(0xE6D14A),
    PINK(0xE07BB3),
    GREY(0x9A9A9A);

    private final int rgb;

    ColourLabel(int rgb) {
        this.rgb = rgb;
    }

    public int rgb() {
        return rgb;
    }

    public boolean isNone() {
        return this == NONE;
    }
}

package dev.dutchy.runelite.gear;

/**
 * The thread the book is written on. Production writes on Swing's event dispatch thread; tests run
 * on whichever thread they are already on.
 */
@FunctionalInterface
public interface Dispatch {

    /** Whether the calling thread is the write thread. */
    boolean isCurrent();

    /** Treats every thread as the write thread, for tests. */
    static Dispatch inline() {
        return () -> true;
    }
}

package dev.dutchy.runelite.gear;

import lombok.AccessLevel;
import lombok.Getter;
import lombok.Value;

import java.util.List;
import java.util.Objects;
import java.util.Optional;

/** A named run of setups; a section may sit one level under another, read through {@link #parent()}. */
@Value
public class GearSection {
    SectionId id;
    String name;
    List<GearSetup> setups;
    @Getter(AccessLevel.NONE)
    SectionId parentId;

    public static final int MAX_NAME_LENGTH = 48;

    public GearSection(SectionId id, String name, List<GearSetup> setups) {
        this(id, name, setups, null);
    }

    public GearSection(SectionId id, String name, List<GearSetup> setups, SectionId parentId) {
        Objects.requireNonNull(id, "id");
        Objects.requireNonNull(setups, "setups");
        if (id.equals(parentId)) {
            throw new IllegalArgumentException("A section cannot be its own parent");
        }
        this.id = id;
        this.name = requireValidName(name);
        this.setups = List.copyOf(setups);
        this.parentId = parentId;
    }

    public static GearSection named(String name) {
        return new GearSection(SectionId.random(), name, List.of());
    }

    public Optional<SectionId> parent() {
        return Optional.ofNullable(parentId);
    }

    public boolean isChild() {
        return parentId != null;
    }

    public boolean isChildOf(SectionId candidate) {
        return candidate.equals(parentId);
    }

    public GearSection withName(String newName) {
        return new GearSection(id, newName, setups, parentId);
    }

    public GearSection withSetups(List<GearSetup> newSetups) {
        return new GearSection(id, name, newSetups, parentId);
    }

    public GearSection withParent(SectionId newParent) {
        return new GearSection(id, name, setups, Objects.requireNonNull(newParent, "newParent"));
    }

    public GearSection withoutParent() {
        return new GearSection(id, name, setups, null);
    }

    public boolean isEmpty() {
        return setups.isEmpty();
    }

    public int size() {
        return setups.size();
    }

    public static String requireValidName(String name) {
        Objects.requireNonNull(name, "name");
        String trimmed = name.strip();
        if (trimmed.isEmpty()) {
            throw new IllegalArgumentException("Section name must not be blank");
        }
        if (trimmed.length() > MAX_NAME_LENGTH) {
            throw new IllegalArgumentException("Section name must be at most " + MAX_NAME_LENGTH + " characters");
        }
        return trimmed;
    }

    public static boolean isValidName(String name) {
        if (name == null) {
            return false;
        }
        String trimmed = name.strip();
        return !trimmed.isEmpty() && trimmed.length() <= MAX_NAME_LENGTH;
    }
}

package dev.dutchy.runelite.gear;

import dev.dutchy.runelite.gear.content.*;
import dev.dutchy.runelite.libs.ui.item.ItemId;
import lombok.Value;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.function.UnaryOperator;

/**
 * A setup: one or more variants of the same layout type, one of them selected by id so the selection
 * survives reordering. {@code iconId} may be null, meaning a lettered tile; read it through {@link #icon()}.
 */
@Value
public class GearSetup {
    SetupId id;
    String name;
    ItemId iconId;
    List<SetupVariant> variants;
    VariantId selected;
    Owner owner;
    SetupMeta meta;

    public static final int MAX_NAME_LENGTH = 48;
    public static final int MAX_VARIANTS = 8;

    public GearSetup(SetupId id, String name, ItemId iconId, SetupContent content, Owner owner, SetupMeta meta) {
        this(id, name, iconId, List.of(SetupVariant.of(Objects.requireNonNull(content, "content"))), 0, owner, meta);
    }

    /** Selects by position, for callers holding an index such as storage and the bank tabs. */
    public GearSetup(SetupId id, String name, ItemId iconId, List<SetupVariant> variants, int selectedIndex, Owner owner, SetupMeta meta) {
        this(id, name, iconId, variants, idAt(variants, selectedIndex), owner, meta);
    }

    public GearSetup(SetupId id, String name, ItemId iconId, List<SetupVariant> variants, VariantId selected, Owner owner, SetupMeta meta) {
        Objects.requireNonNull(id, "id");
        Objects.requireNonNull(variants, "variants");
        Objects.requireNonNull(owner, "owner");
        Objects.requireNonNull(meta, "meta");
        Objects.requireNonNull(selected, "selected");
        requireValidVariants(variants);
        if (variants.stream().noneMatch(variant -> variant.hasId(selected))) {
            throw new IllegalArgumentException("No variant " + selected + " in this setup");
        }
        this.id = id;
        this.name = requireValidName(name);
        this.iconId = iconId;
        this.variants = List.copyOf(variants);
        this.selected = selected;
        this.owner = owner;
        this.meta = meta;
    }

    private static VariantId idAt(List<SetupVariant> variants, int index) {
        Objects.requireNonNull(variants, "variants");
        if (index < 0 || index >= variants.size()) {
            throw new IllegalArgumentException("No variant " + index + " among " + variants.size());
        }
        return variants.get(index).id();
    }

    public static GearSetup named(String name) {
        return new GearSetup(SetupId.random(), name, null, GearContent.empty(), Owner.shared(), SetupMeta.none());
    }

    public static GearSetup of(String name, ItemId icon) {
        return named(name).withIcon(icon);
    }

    public Optional<ItemId> icon() {
        return Optional.ofNullable(iconId);
    }

    /** The selected variant's contents. */
    public SetupContent content() {
        return variant().content();
    }

    /** The selected variant. */
    public SetupVariant variant() {
        return variants.get(selectedIndex());
    }

    /** Where the selected variant sits, for views and the bank tabs. */
    public int selectedIndex() {
        return indexOf(selected);
    }

    public Optional<SetupVariant> variantAt(int index) {
        return index >= 0 && index < variants.size() ? Optional.of(variants.get(index)) : Optional.empty();
    }

    public Optional<SetupVariant> variant(VariantId variantId) {
        return variants.stream().filter(variant -> variant.hasId(variantId)).findFirst();
    }

    /** The id of the variant at the position, empty when there is none there. */
    public Optional<VariantId> variantIdAt(int index) {
        return variantAt(index).map(SetupVariant::id);
    }

    /** Where the variant sits, or -1 when this setup does not hold it. */
    public int positionOf(VariantId variantId) {
        for (int i = 0; i < variants.size(); i++) {
            if (variants.get(i).hasId(variantId)) {
                return i;
            }
        }
        return -1;
    }

    private int indexOf(VariantId variantId) {
        int at = positionOf(variantId);
        if (at < 0) {
            throw new IllegalArgumentException("No variant " + variantId + " in this setup");
        }
        return at;
    }

    public boolean hasVariants() {
        return variants.size() > 1;
    }

    public boolean hasVariantNamed(String variantName) {
        return variants.stream().anyMatch(variant -> variant.isNamed(variantName));
    }

    public GearSetup withName(String newName) {
        return new GearSetup(id, newName, iconId, variants, selected, owner, meta);
    }

    public GearSetup withIcon(ItemId newIcon) {
        return new GearSetup(id, name, Objects.requireNonNull(newIcon, "newIcon"), variants, selected, owner, meta);
    }

    public GearSetup withoutIcon() {
        return new GearSetup(id, name, null, variants, selected, owner, meta);
    }

    /** Takes the other setup's icon, or lack of one. */
    public GearSetup withIconOf(GearSetup other) {
        return new GearSetup(id, name, other.iconId, variants, selected, owner, meta);
    }

    /** Replaces the selected variant's contents. */
    public GearSetup withContent(SetupContent newContent) {
        return withVariantContent(selected, newContent);
    }

    /** Replaces one variant's contents. */
    public GearSetup withVariantContent(VariantId variantId, SetupContent newContent) {
        SetupVariant found = variant(variantId).orElseThrow(() -> new IllegalArgumentException("No variant " + variantId));
        return withVariant(variantId, found.withContent(newContent));
    }

    public GearSetup withVariants(List<SetupVariant> newVariants, int newSelected) {
        return new GearSetup(id, name, iconId, newVariants, newSelected, owner, meta);
    }

    public GearSetup withVariants(List<SetupVariant> newVariants, VariantId newSelected) {
        return new GearSetup(id, name, iconId, newVariants, newSelected, owner, meta);
    }

    public GearSetup withSelectedVariant(VariantId variantId) {
        return new GearSetup(id, name, iconId, variants, variantId, owner, meta);
    }

    public GearSetup withSelectedVariant(int index) {
        return withSelectedVariant(idAt(variants, index));
    }

    /** Replaces one variant in place. A replacement under a new id keeps the selection if it had it. */
    public GearSetup withVariant(VariantId variantId, SetupVariant variant) {
        Objects.requireNonNull(variant, "variant");
        int at = indexOf(variantId);
        List<SetupVariant> updated = new ArrayList<>(variants);
        updated.set(at, variant);
        return withVariants(updated, variantId.equals(selected) ? variant.id() : selected);
    }

    public GearSetup withVariant(int index, SetupVariant variant) {
        return withVariant(idAt(variants, index), variant);
    }

    /** Adds the variant after the last; the selection stays where it was. */
    public GearSetup withAddedVariant(SetupVariant variant) {
        return withVariantInserted(variants.size(), variant);
    }

    /** Puts the variant at the position; the ones after it move down and the selection is untouched. */
    public GearSetup withVariantInserted(int index, SetupVariant variant) {
        List<SetupVariant> updated = new ArrayList<>(variants);
        updated.add(index, Objects.requireNonNull(variant, "variant"));
        return withVariants(updated, selected);
    }

    /** Moves a variant to another position; the selection is untouched. */
    public GearSetup withVariantMoved(int from, int to) {
        if (to < 0 || to >= variants.size()) {
            throw new IllegalArgumentException("No position " + to + " among " + variants.size() + " variants");
        }
        List<SetupVariant> updated = new ArrayList<>(variants);
        updated.add(to, updated.remove(from));
        return withVariants(updated, selected);
    }

    public GearSetup withoutVariant(int index) {
        return withoutVariant(idAt(variants, index));
    }

    /** Drops the variant; dropping the selected one selects the nearest remaining to its left. */
    public GearSetup withoutVariant(VariantId variantId) {
        if (variants.size() == 1) {
            throw new IllegalStateException("A setup keeps at least one variant");
        }
        int index = indexOf(variantId);
        List<SetupVariant> updated = new ArrayList<>(variants);
        updated.remove(index);
        VariantId stays = variantId.equals(selected)
                ? updated.get(Math.max(0, Math.min(index, updated.size() - 1))).id()
                : selected;
        return withVariants(updated, stays);
    }

    /** The same setup under another id, as when a stored one is read back. */
    public GearSetup withId(SetupId newId) {
        return new GearSetup(newId, name, iconId, variants, selected, owner, meta);
    }

    public GearSetup withOwner(Owner newOwner) {
        return new GearSetup(id, name, iconId, variants, selected, newOwner, meta);
    }

    public GearSetup withMeta(SetupMeta newMeta) {
        return new GearSetup(id, name, iconId, variants, selected, owner, newMeta);
    }

    public GearSetup withMeta(UnaryOperator<SetupMeta> change) {
        return withMeta(Objects.requireNonNull(change, "change").apply(meta));
    }

    /** A fresh copy under a new id, unpinned and without a hotkey, so nothing collides with the original. */
    public GearSetup copyNamed(String newName) {
        return new GearSetup(SetupId.random(), newName, iconId, variants, selected, owner,
                meta.withPinned(false).withHotkey(Hotkey.NONE));
    }

    public SetupType type() {
        return variants.get(0).type();
    }

    public boolean hasIcon() {
        return iconId != null;
    }

    public boolean isPinned() {
        return meta.pinned();
    }

    public static String requireValidName(String name) {
        Objects.requireNonNull(name, "name");
        String trimmed = name.strip();
        if (trimmed.isEmpty()) {
            throw new IllegalArgumentException("Setup name must not be blank");
        }
        if (trimmed.length() > MAX_NAME_LENGTH) {
            throw new IllegalArgumentException("Setup name must be at most " + MAX_NAME_LENGTH + " characters");
        }
        return trimmed;
    }

    public static boolean isValidName(String name) {
        if (name == null) {
            return false;
        }
        String trimmed = name.strip();
        return !trimmed.isEmpty() && trimmed.length() <= MAX_NAME_LENGTH;
    }

    private static void requireValidVariants(List<SetupVariant> variants) {
        if (variants.isEmpty()) {
            throw new IllegalArgumentException("A setup needs at least one variant");
        }
        if (variants.size() > MAX_VARIANTS) {
            throw new IllegalArgumentException("At most " + MAX_VARIANTS + " variants, got " + variants.size());
        }
        SetupType type = variants.get(0).type();
        for (int i = 0; i < variants.size(); i++) {
            SetupVariant variant = variants.get(i);
            if (variant.type() != type) {
                throw new IllegalArgumentException("Every variant must be a " + type.displayName());
            }
            for (int j = 0; j < i; j++) {
                if (variants.get(j).isNamed(variant.name())) {
                    throw new IllegalArgumentException("Two variants are named " + variant.name());
                }
                if (variants.get(j).hasId(variant.id())) {
                    throw new IllegalArgumentException("Two variants share the id " + variant.id());
                }
            }
        }
    }
}

package dev.dutchy.runelite.gear;

import dev.dutchy.runelite.gear.content.SetupContent;
import dev.dutchy.runelite.gear.content.VariantId;

import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.UnaryOperator;
import java.util.stream.Collectors;

/**
 * Always holds at least one section. Written on the dispatch thread, which every mutator asserts;
 * reads are served from an immutable snapshot and are safe from any thread.
 */
public final class GearSetupBook {

    public static final String DEFAULT_SECTION_NAME = "Setups";

    private final List<GearSection> sections = new ArrayList<>();
    private final List<GearSetupBookListener> listeners = new CopyOnWriteArrayList<>();
    private final Dispatch dispatch;

    private volatile List<GearSection> published;

    public GearSetupBook() {
        this(DEFAULT_SECTION_NAME, Dispatch.inline());
    }

    public GearSetupBook(String firstSectionName) {
        this(firstSectionName, Dispatch.inline());
    }

    public GearSetupBook(Dispatch dispatch) {
        this(DEFAULT_SECTION_NAME, dispatch);
    }

    public GearSetupBook(String firstSectionName, Dispatch dispatch) {
        this.dispatch = Objects.requireNonNull(dispatch, "dispatch");
        sections.add(GearSection.named(firstSectionName));
        published = List.copyOf(sections);
    }

    public List<GearSection> sections() {
        return published;
    }

    /** Swaps in a whole new set of sections, for example one read from storage. */
    public void replaceSections(List<GearSection> newSections) {
        requireDispatch();
        Objects.requireNonNull(newSections, "newSections");
        if (newSections.isEmpty()) {
            throw new IllegalArgumentException("A book needs at least one section");
        }
        sections.clear();
        sections.addAll(SectionTree.normalised(newSections));
        fireChanged();
    }

    public int sectionCount() {
        return published.size();
    }

    public int setupCount() {
        return published.stream().mapToInt(GearSection::size).sum();
    }

    public boolean isEmpty() {
        return setupCount() == 0;
    }

    public Optional<GearSection> section(SectionId id) {
        Objects.requireNonNull(id, "id");
        return published.stream().filter(section -> section.id().equals(id)).findFirst();
    }

    public Optional<GearSetup> setup(SetupId id) {
        Objects.requireNonNull(id, "id");
        return published.stream()
                .flatMap(section -> section.setups().stream())
                .filter(setup -> setup.id().equals(id))
                .findFirst();
    }

    public Optional<GearSection> sectionOf(SetupId id) {
        Objects.requireNonNull(id, "id");
        return published.stream()
                .filter(section -> section.setups().stream().anyMatch(setup -> setup.id().equals(id)))
                .findFirst();
    }

    public GearSection addSection(String name) {
        requireDispatch();
        GearSection section = GearSection.named(name);
        sections.add(section);
        fireChanged();
        return section;
    }

    public void renameSection(SectionId id, String newName) {
        requireDispatch();
        int index = indexOfSection(id);
        sections.set(index, sections.get(index).withName(newName));
        fireChanged();
    }

    /** Also removes the setups the section holds; removing a parent lifts its children to the top level in its place. */
    public void removeSection(SectionId id) {
        requireDispatch();
        int index = indexOfSection(id);
        if (sections.size() == 1) {
            throw new IllegalStateException("Cannot remove the last section");
        }
        sections.remove(index);
        for (int i = 0; i < sections.size(); i++) {
            if (sections.get(i).isChildOf(id)) {
                sections.set(i, sections.get(i).withoutParent());
            }
        }
        fireChanged();
    }

    /** A new empty section one level under {@code parentId}, placed after its existing children. */
    public GearSection addSubSection(SectionId parentId, String name) {
        requireDispatch();
        GearSection parent = requireTopLevel(parentId);
        GearSection child = new GearSection(SectionId.random(), name, List.of(), parent.id());
        sections.add(endOfFamily(parent.id()), child);
        fireChanged();
        return child;
    }

    /** A new empty peer of {@code anchorId}: a sibling for a child, a top-level section otherwise. */
    public GearSection insertSectionBefore(SectionId anchorId, String name) {
        requireDispatch();
        GearSection anchor = SectionTree.find(sections, anchorId);
        GearSection section = new GearSection(SectionId.random(), name, List.of(), anchor.parent().orElse(null));
        sections.add(indexOfSection(anchorId), section);
        fireChanged();
        return section;
    }

    public GearSection insertSectionAfter(SectionId anchorId, String name) {
        requireDispatch();
        GearSection anchor = SectionTree.find(sections, anchorId);
        GearSection section = new GearSection(SectionId.random(), name, List.of(), anchor.parent().orElse(null));
        sections.add(anchor.isChild() ? indexOfSection(anchorId) + 1 : endOfFamily(anchorId), section);
        fireChanged();
        return section;
    }

    /** Moves a childless top-level section under another top-level section, after its existing children. */
    public void nestSection(SectionId id, SectionId parentId) {
        requireDispatch();
        GearSection subject = SectionTree.find(sections, id);
        GearSection parent = requireTopLevel(parentId);
        if (subject.id().equals(parent.id())) {
            throw new IllegalArgumentException("A section cannot be nested under itself");
        }
        if (SectionTree.hasChildren(sections, id)) {
            throw new IllegalArgumentException("A section with sub-sections cannot be nested");
        }
        sections.remove(indexOfSection(id));
        sections.add(endOfFamily(parent.id()), subject.withParent(parent.id()));
        fireChanged();
    }

    /** Lifts a child out to the top level, right after the family it came from. */
    public void unnestSection(SectionId id) {
        requireDispatch();
        GearSection subject = SectionTree.find(sections, id);
        if (!subject.isChild()) {
            return;
        }
        SectionId parent = subject.parent().orElseThrow();
        sections.remove(indexOfSection(id));
        sections.add(endOfFamily(parent), subject.withoutParent());
        fireChanged();
    }

    private GearSection requireTopLevel(SectionId id) {
        GearSection section = SectionTree.find(sections, id);
        if (section.isChild()) {
            throw new IllegalArgumentException("Sections nest one level deep only");
        }
        return section;
    }

    /** The index just past a top-level section and its children. */
    private int endOfFamily(SectionId topLevelId) {
        int end = indexOfSection(topLevelId) + 1;
        while (end < sections.size() && sections.get(end).isChildOf(topLevelId)) {
            end++;
        }
        return end;
    }

    public GearSetup addSetup(SectionId sectionId, String name) {
        return addSetup(sectionId, GearSetup.named(name));
    }

    /** Adds a fully formed setup; its id must be new to the book. */
    public GearSetup addSetup(SectionId sectionId, GearSetup setup) {
        requireDispatch();
        Objects.requireNonNull(setup, "setup");
        if (setup(setup.id()).isPresent()) {
            throw new IllegalArgumentException("A setup with id " + setup.id() + " already exists");
        }
        int index = indexOfSection(sectionId);
        GearSection section = sections.get(index);
        List<GearSetup> updated = new ArrayList<>(section.setups());
        updated.add(setup);
        sections.set(index, section.withSetups(updated));
        fireChanged();
        return setup;
    }

    public GearSetup addSetup(String name) {
        requireDispatch();
        return addSetup(sections.get(0).id(), name);
    }

    /** Applies a change to one setup; nothing fires when the result is identical. Returns the setup afterwards. */
    public GearSetup change(SetupId id, UnaryOperator<GearSetup> change) {
        requireDispatch();
        Objects.requireNonNull(change, "change");
        GearSection section = sectionOf(id).orElseThrow(() -> unknownSetup(id));
        int sectionIndex = indexOfSection(section.id());
        List<GearSetup> updated = new ArrayList<>(section.setups());
        int setupIndex = indexOfSetup(updated, id);
        GearSetup before = updated.get(setupIndex);
        GearSetup after = Objects.requireNonNull(change.apply(before), "changed setup");
        if (!after.id().equals(id)) {
            throw new IllegalArgumentException("A change must keep the setup id");
        }
        if (after.equals(before)) {
            return before;
        }
        updated.set(setupIndex, after);
        sections.set(sectionIndex, section.withSetups(updated));
        fireChanged();
        return after;
    }

    public void setOwner(SetupId id, Owner owner) {
        Objects.requireNonNull(owner, "owner");
        change(id, setup -> setup.withOwner(owner));
    }

    public void changeMeta(SetupId id, UnaryOperator<SetupMeta> metaChange) {
        Objects.requireNonNull(metaChange, "metaChange");
        change(id, setup -> setup.withMeta(metaChange));
    }

    /** Inserts a copy right after the original, named so it does not clash within the section. */
    public GearSetup duplicateSetup(SetupId id) {
        requireDispatch();
        GearSection section = sectionOf(id).orElseThrow(() -> unknownSetup(id));
        int sectionIndex = indexOfSection(section.id());
        List<GearSetup> updated = new ArrayList<>(section.setups());
        int setupIndex = indexOfSetup(updated, id);
        GearSetup original = updated.get(setupIndex);
        GearSetup copy = original.copyNamed(SetupNames.copyOf(original.name(),
                updated.stream().map(GearSetup::name).collect(Collectors.toList())));
        updated.add(setupIndex + 1, copy);
        sections.set(sectionIndex, section.withSetups(updated));
        fireChanged();
        return copy;
    }

    public GearSection insertSection(int index, String name) {
        requireDispatch();
        GearSection section = GearSection.named(name);
        sections.add(Math.max(0, Math.min(sections.size(), index)), section);
        List<GearSection> normalised = SectionTree.normalised(sections);
        sections.clear();
        sections.addAll(normalised);
        fireChanged();
        return section;
    }

    /** Reorders one section's setups; the new order becomes the manual order. */
    public void sortSection(SectionId id, Comparator<GearSetup> order) {
        requireDispatch();
        Objects.requireNonNull(order, "order");
        int index = indexOfSection(id);
        GearSection section = sections.get(index);
        List<GearSetup> sorted = new ArrayList<>(section.setups());
        sorted.sort(order);
        if (sorted.equals(section.setups())) {
            return;
        }
        sections.set(index, section.withSetups(sorted));
        fireChanged();
    }

    /** Pinned setups in book order. */
    public List<GearSetup> pinnedSetups() {
        return published.stream()
                .flatMap(section -> section.setups().stream())
                .filter(GearSetup::isPinned)
                .collect(Collectors.toList());
    }


    /** Removes the sections and setups in one change. Recreates a default section if none remain. */
    public void deleteAll(Collection<SectionId> sectionIds, Collection<SetupId> setupIds) {
        requireDispatch();
        Objects.requireNonNull(sectionIds, "sectionIds");
        Objects.requireNonNull(setupIds, "setupIds");
        Set<SectionId> doomedSections = Set.copyOf(sectionIds);
        Set<SetupId> doomedSetups = Set.copyOf(setupIds);
        if (doomedSections.isEmpty() && doomedSetups.isEmpty()) {
            return;
        }
        List<GearSection> kept = new ArrayList<>();
        for (GearSection section : sections) {
            if (doomedSections.contains(section.id())) {
                continue;
            }
            List<GearSetup> survivors = section.setups().stream()
                    .filter(setup -> !doomedSetups.contains(setup.id()))
                    .collect(Collectors.toList());
            kept.add(survivors.size() == section.size() ? section : section.withSetups(survivors));
        }
        sections.clear();
        sections.addAll(SectionTree.normalised(kept));
        if (sections.isEmpty()) {
            sections.add(GearSection.named(DEFAULT_SECTION_NAME));
        }
        fireChanged();
    }

    /** Replaces the selected variant's contents. */
    public void updateSetupContent(SetupId id, SetupContent content) {
        updateVariantContent(id, setup(id).orElseThrow(() -> unknownSetup(id)).selected(), content);
    }

    /** Replaces one variant's contents. */
    public void updateVariantContent(SetupId id, VariantId variant, SetupContent content) {
        requireDispatch();
        Objects.requireNonNull(content, "content");
        GearSection section = sectionOf(id).orElseThrow(() -> unknownSetup(id));
        int sectionIndex = indexOfSection(section.id());
        List<GearSetup> updated = new ArrayList<>(section.setups());
        int setupIndex = indexOfSetup(updated, id);
        updated.set(setupIndex, updated.get(setupIndex).withVariantContent(variant, content));
        sections.set(sectionIndex, section.withSetups(updated));
        fireChanged();
    }

    public void removeSetup(SetupId id) {
        requireDispatch();
        GearSection section = sectionOf(id).orElseThrow(() -> unknownSetup(id));
        int sectionIndex = indexOfSection(section.id());
        List<GearSetup> updated = new ArrayList<>(section.setups());
        updated.remove(indexOfSetup(updated, id));
        sections.set(sectionIndex, section.withSetups(updated));
        fireChanged();
    }

    /** Reorders among peers: siblings for a child, top-level sections otherwise, each moving with its children. targetIndex applies after removal and is clamped. */
    public boolean moveSection(SectionId id, int targetIndex) {
        requireDispatch();
        GearSection moved = SectionTree.find(sections, id);
        List<GearSection> peers = new ArrayList<>(SectionTree.peersOf(sections, id));
        int from = indexOfSection(peers, id);
        peers.remove(from);
        int clamped = Math.max(0, Math.min(peers.size(), targetIndex));
        if (clamped == from) {
            return false;
        }
        peers.add(clamped, moved);
        applyPeerOrder(moved, peers);
        fireChanged();
        return true;
    }

    public boolean moveSectionUp(SectionId id) {
        requireDispatch();
        int index = indexOfSection(SectionTree.peersOf(sections, id), id);
        return index > 0 && moveSection(id, index - 1);
    }

    public boolean moveSectionDown(SectionId id) {
        requireDispatch();
        List<GearSection> peers = SectionTree.peersOf(sections, id);
        int index = indexOfSection(peers, id);
        return index < peers.size() - 1 && moveSection(id, index + 1);
    }

    private void applyPeerOrder(GearSection subject, List<GearSection> peers) {
        List<GearSection> result = new ArrayList<>();
        if (subject.isChild()) {
            SectionId parent = subject.parent().orElseThrow();
            for (GearSection section : sections) {
                if (section.isChildOf(parent)) {
                    continue;
                }
                result.add(section);
                if (section.id().equals(parent)) {
                    result.addAll(peers);
                }
            }
        } else {
            for (GearSection top : peers) {
                result.addAll(SectionTree.familyOf(sections, top.id()));
            }
        }
        sections.clear();
        sections.addAll(result);
    }

    private static int indexOfSection(List<GearSection> list, SectionId id) {
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i).id().equals(id)) {
                return i;
            }
        }
        throw new IllegalArgumentException("Unknown section " + id);
    }

    public int sectionIndex(SectionId id) {
        Objects.requireNonNull(id, "id");
        return indexOfSection(published, id);
    }

    /** targetIndex applies after the setup is removed from its current position, and is clamped. */
    public boolean moveSetup(SetupId id, SectionId targetSectionId, int targetIndex) {
        requireDispatch();
        GearSection source = sectionOf(id).orElseThrow(() -> unknownSetup(id));
        int targetSectionIndex = indexOfSection(targetSectionId);
        int sourceSectionIndex = indexOfSection(source.id());

        List<GearSetup> sourceSetups = new ArrayList<>(source.setups());
        int sourceIndex = indexOfSetup(sourceSetups, id);
        GearSetup moved = sourceSetups.remove(sourceIndex);

        if (sourceSectionIndex == targetSectionIndex) {
            int clamped = Math.max(0, Math.min(sourceSetups.size(), targetIndex));
            if (clamped == sourceIndex) {
                return false;
            }
            sourceSetups.add(clamped, moved);
            sections.set(sourceSectionIndex, source.withSetups(sourceSetups));
        } else {
            GearSection target = sections.get(targetSectionIndex);
            List<GearSetup> targetSetups = new ArrayList<>(target.setups());
            targetSetups.add(Math.max(0, Math.min(targetSetups.size(), targetIndex)), moved);
            sections.set(sourceSectionIndex, source.withSetups(sourceSetups));
            sections.set(targetSectionIndex, target.withSetups(targetSetups));
        }
        fireChanged();
        return true;
    }

    public void addChangeListener(GearSetupBookListener listener) {
        listeners.add(Objects.requireNonNull(listener, "listener"));
    }

    public void removeChangeListener(GearSetupBookListener listener) {
        listeners.remove(listener);
    }

    private void fireChanged() {
        published = List.copyOf(sections);
        for (GearSetupBookListener listener : listeners) {
            listener.onBookChanged(this);
        }
    }

    private void requireDispatch() {
        if (!dispatch.isCurrent()) {
            throw new IllegalStateException("The book must be changed on the dispatch thread");
        }
    }

    private int indexOfSection(SectionId id) {
        Objects.requireNonNull(id, "id");
        for (int i = 0; i < sections.size(); i++) {
            if (sections.get(i).id().equals(id)) {
                return i;
            }
        }
        throw new IllegalArgumentException("Unknown section " + id);
    }

    private static int indexOfSetup(List<GearSetup> setups, SetupId id) {
        for (int i = 0; i < setups.size(); i++) {
            if (setups.get(i).id().equals(id)) {
                return i;
            }
        }
        throw unknownSetup(id);
    }

    private static IllegalArgumentException unknownSetup(SetupId id) {
        return new IllegalArgumentException("Unknown setup " + id);
    }
}

