package dev.dutchy.runelite.gear.account;

import dev.dutchy.runelite.libs.ui.swing.EdtDispatch;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.CopyOnWriteArrayList;

/** Follows RuneLite's RuneScape profile, which changes on login and when switching characters. */
@Singleton
public final class RuneLiteAccount implements CurrentAccount {

    private final Client client;
    private final ConfigManager configManager;
    private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

    private volatile String key;
    private volatile String displayName;

    @Inject
    public RuneLiteAccount(Client client, ConfigManager configManager) {
        this.client = Objects.requireNonNull(client, "client");
        this.configManager = Objects.requireNonNull(configManager, "configManager");
    }

    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event) {
        refresh();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGGED_IN || event.getGameState() == GameState.LOGIN_SCREEN
                || event.getGameState() == GameState.HOPPING) {
            refresh();
        }
    }

    /** The profile key and player name land a few ticks after login, so keep looking until both are known. */
    @Subscribe
    public void onGameTick(GameTick event) {
        if (client.getGameState() == GameState.LOGGED_IN && (key == null || displayName == null)) {
            refresh();
        }
    }

    @Override
    public Optional<String> key() {
        return Optional.ofNullable(key);
    }

    @Override
    public Optional<String> displayName() {
        return Optional.ofNullable(displayName);
    }

    @Override
    public void addListener(Runnable listener) {
        listeners.add(Objects.requireNonNull(listener, "listener"));
    }

    /** Re-reads who is logged in; must run on the client thread. */
    public void refresh() {
        String newKey = client.getGameState() == GameState.LOGGED_IN ? configManager.getRSProfileKey() : null;
        Player player = newKey == null ? null : client.getLocalPlayer();
        String newName = player == null ? null : player.getName();
        if (Objects.equals(newKey, key) && Objects.equals(newName, displayName)) {
            return;
        }
        key = newKey;
        displayName = newName;
        EdtDispatch.onEdt(() -> listeners.forEach(Runnable::run));
    }
}

package dev.dutchy.runelite.gear.activation;

import dev.dutchy.runelite.gear.GearSetup;
import dev.dutchy.runelite.gear.bank.BankTitle;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.*;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Objects;
import java.util.Optional;

/** A short in-game notice of which setup and variant just became active, so the sidebar can stay closed. */
public final class ActivationToast extends OverlayPanel {

    static final Duration SHOW_FOR = Duration.ofSeconds(2);
    private static final Color TITLE = new Color(220, 138, 0);

    private final SetupActivator activator;
    private final Clock clock;

    private volatile Instant until = Instant.MIN;
    private volatile String title = "";
    private volatile String detail = "";

    @Inject
    public ActivationToast(SetupActivator activator, Clock clock) {
        this.activator = Objects.requireNonNull(activator, "activator");
        this.clock = Objects.requireNonNull(clock, "clock");
        setPosition(OverlayPosition.TOP_CENTER);
        setPriority(PRIORITY_HIGH);
    }

    /** Shows the current state of the activator for a moment. */
    public void announce() {
        Optional<GearSetup> current = activator.current();
        title = current.map(BankTitle::describe).orElse("Bank layout off");
        detail = current.flatMap(setup -> activator.position()).map(pos -> pos[0] + " of " + pos[1]).orElse("");
        until = clock.instant().plus(SHOW_FOR);
    }

    public boolean isShowing() {
        return clock.instant().isBefore(until);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!isShowing()) {
            return null;
        }
        panelComponent.getChildren().add(TitleComponent.builder().text(title).color(TITLE).build());
        if (!detail.isEmpty()) {
            panelComponent.getChildren().add(LineComponent.builder().left(detail).build());
        }
        return super.render(graphics);
    }
}

package dev.dutchy.runelite.gear.activation;

import dev.dutchy.runelite.gear.GearSetup;
import dev.dutchy.runelite.gear.GearSetupBook;
import dev.dutchy.runelite.gear.GearSetupBookListener;
import dev.dutchy.runelite.gear.SetupId;
import dev.dutchy.runelite.gear.bank.*;

import javax.inject.Inject;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.stream.Collectors;

/**
 * The one place a setup or its variant is switched in the bank, whether from a tile, a hotkey, or a menu.
 * While a setup is active the bank follows it: any change to what the bank would show redraws, deleting it clears.
 * Every call changes the book, so callers on the client thread hand over to the EDT first.
 */
public final class SetupActivator implements GearSetupBookListener {

    private final GearSetupBook book;
    private final ActiveSetup active;
    private final BankLayoutPlanner planner;
    private final BankLayoutApplier bank;
    private final BankTagState tags;
    private final List<Runnable> listeners = new CopyOnWriteArrayList<>();
    private BankLayout shown;

    @Inject
    public SetupActivator(GearSetupBook book, ActiveSetup active, BankLayoutPlanner planner, BankLayoutApplier bank, BankTagState tags) {
        this.book = Objects.requireNonNull(book, "book");
        this.active = Objects.requireNonNull(active, "active");
        this.planner = Objects.requireNonNull(planner, "planner");
        this.bank = Objects.requireNonNull(bank, "bank");
        this.tags = Objects.requireNonNull(tags, "tags");
        book.addChangeListener(this);
    }

    @Override
    public void onBookChanged(GearSetupBook changed) {
        Optional<SetupId> id = active.current();
        if (id.isEmpty()) {
            return;
        }
        Optional<GearSetup> setup = book.setup(id.get());
        if (setup.isEmpty()) {
            clear();
        } else if (!layoutFor(setup.get()).equals(shown)) {
            apply(setup.get());
        }
    }

    /** Told after every switch a player asked for: a setup on or off, or another variant. Edits do not count. */
    public void addListener(Runnable listener) {
        listeners.add(Objects.requireNonNull(listener, "listener"));
    }

    public void removeListener(Runnable listener) {
        listeners.remove(Objects.requireNonNull(listener, "listener"));
    }

    /** Turns the setup on, or off when it already is. Returns what is active afterwards. */
    public Optional<GearSetup> toggle(SetupId id) {
        Objects.requireNonNull(id, "id");
        Optional<GearSetup> setup = book.setup(id);
        if (setup.isEmpty()) {
            return current();
        }
        if (active.toggle(id).isPresent()) {
            apply(setup.get());
        } else {
            takeDown();
        }
        switched();
        return current();
    }

    /** Makes the variant the active setup's chosen one; the bank follows through the book. */
    public Optional<GearSetup> selectVariant(int index) {
        Optional<GearSetup> setup = current().filter(found -> found.variantAt(index).isPresent());
        setup.ifPresent(found -> {
            book.change(found.id(), current -> current.withSelectedVariant(index));
            switched();
        });
        return current();
    }

    /** Steps to the active setup's next variant, wrapping around. */
    public Optional<GearSetup> nextVariant() {
        return stepVariant(1);
    }

    public Optional<GearSetup> previousVariant() {
        return stepVariant(-1);
    }

    private Optional<GearSetup> stepVariant(int direction) {
        Optional<GearSetup> setup = current().filter(GearSetup::hasVariants);
        if (setup.isEmpty()) {
            return current();
        }
        return selectVariant(Math.floorMod(setup.get().selectedIndex() + direction, setup.get().variants().size()));
    }

    /** Shows the setup even if it is already active, for example after its items changed. */
    public void show(SetupId id) {
        Objects.requireNonNull(id, "id");
        book.setup(id).ifPresent(setup -> {
            if (!active.isActive(id)) {
                active.toggle(id);
            }
            apply(setup);
            switched();
        });
    }

    public void clear() {
        if (active.current().isPresent()) {
            active.clear();
            takeDown();
            switched();
        }
    }

    private void switched() {
        listeners.forEach(Runnable::run);
    }

    private void apply(GearSetup setup) {
        if (tags.isTagOpen()) {
            tags.closeTag();
        }
        shown = layoutFor(setup);
        bank.apply(shown);
    }

    private BankLayout layoutFor(GearSetup setup) {
        return planner.plan(setup.content()).withVariants(VariantTabs.of(setup));
    }

    private void takeDown() {
        shown = null;
        bank.clear();
    }

    public Optional<GearSetup> current() {
        return active.current().flatMap(book::setup);
    }

    /** Steps to the next setup in book order, wrapping around; starts at the first when none is active. */
    public Optional<GearSetup> next() {
        return step(1);
    }

    public Optional<GearSetup> previous() {
        return step(-1);
    }

    private Optional<GearSetup> step(int direction) {
        List<GearSetup> all = book.sections().stream().flatMap(section -> section.setups().stream()).collect(Collectors.toList());
        if (all.isEmpty()) {
            return Optional.empty();
        }
        int index = active.current().map(id -> indexOf(all, id)).orElse(-1);
        int target = index < 0
                ? (direction > 0 ? 0 : all.size() - 1)
                : Math.floorMod(index + direction, all.size());
        show(all.get(target).id());
        return current();
    }

    private static int indexOf(List<GearSetup> all, SetupId id) {
        for (int i = 0; i < all.size(); i++) {
            if (all.get(i).id().equals(id)) {
                return i;
            }
        }
        return -1;
    }

    /** Position in book order, for messages such as "3 of 7". */
    public Optional<int[]> position() {
        List<GearSetup> all = book.sections().stream().flatMap(section -> section.setups().stream()).collect(Collectors.toList());
        return active.current().map(id -> indexOf(all, id)).filter(index -> index >= 0)
                .map(index -> new int[] {index + 1, all.size()});
    }
}

package dev.dutchy.runelite.gear.activation;

import dev.dutchy.runelite.gear.GearSetup;
import dev.dutchy.runelite.gear.GearSetupBook;
import dev.dutchy.runelite.gear.Hotkey;
import dev.dutchy.runelite.gear.config.GearComposerConfig;
import dev.dutchy.runelite.libs.ui.swing.EdtDispatch;
import net.runelite.client.config.Keybind;
import net.runelite.client.input.KeyListener;

import javax.inject.Inject;
import java.awt.event.KeyEvent;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Collectors;

/** Turns key presses on the game canvas into setup switches. Registered with RuneLite's key manager. */
public final class SetupHotkeys implements KeyListener {

    private final GearSetupBook book;
    private final SetupActivator activator;
    private final GearComposerConfig config;

    @Inject
    public SetupHotkeys(GearSetupBook book, SetupActivator activator, GearComposerConfig config) {
        this.book = Objects.requireNonNull(book, "book");
        this.activator = Objects.requireNonNull(activator, "activator");
        this.config = Objects.requireNonNull(config, "config");
    }

    @Override
    public void keyPressed(KeyEvent event) {
        Optional<Runnable> action = actionFor(event);
        if (action.isPresent()) {
            event.consume();
            EdtDispatch.onEdt(action.get());
        }
    }

    /** What the key would do, if anything; exposed so tests need no key manager. */
    public Optional<Runnable> actionFor(KeyEvent event) {
        Objects.requireNonNull(event, "event");
        if (matches(config.nextSetupHotkey(), event)) {
            return Optional.of(activator::next);
        }
        if (matches(config.previousSetupHotkey(), event)) {
            return Optional.of(activator::previous);
        }
        if (matches(config.clearLayoutHotkey(), event)) {
            return Optional.of(activator::clear);
        }
        if (matches(config.nextVariantHotkey(), event)) {
            return Optional.of(activator::nextVariant);
        }
        if (matches(config.previousVariantHotkey(), event)) {
            return Optional.of(activator::previousVariant);
        }
        for (GearSetup setup : book.sections().stream().flatMap(section -> section.setups().stream()).collect(Collectors.toList())) {
            if (setup.meta().hotkey().matches(event)) {
                return Optional.of(() -> activator.toggle(setup.id()));
            }
        }
        return Optional.empty();
    }

    /** Compares by key code rather than RuneLite's extended code, which synthetic events lack. */
    private static boolean matches(Keybind keybind, KeyEvent event) {
        if (keybind == null || keybind == Keybind.NOT_SET || keybind.getKeyCode() == KeyEvent.VK_UNDEFINED) {
            return false;
        }
        return new Hotkey(keybind.getKeyCode(), keybind.getModifiers()).matches(event);
    }

    @Override
    public void keyTyped(KeyEvent event) {
    }

    @Override
    public void keyReleased(KeyEvent event) {
    }
}

package dev.dutchy.runelite.gear.bank;

import dev.dutchy.runelite.gear.SetupId;

import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * Which setup the bank is currently showing, if any. Safe to use from any thread: the bank close
 * handler clears it from the client thread while the panel and hotkeys toggle it from the EDT.
 */
public final class ActiveSetup {

    private final List<Runnable> listeners = new CopyOnWriteArrayList<>();
    private final Object lock = new Object();

    private SetupId active;

    public Optional<SetupId> current() {
        synchronized (lock) {
            return Optional.ofNullable(active);
        }
    }

    public boolean isActive(SetupId id) {
        Objects.requireNonNull(id, "id");
        synchronized (lock) {
            return id.equals(active);
        }
    }

    /** Turns the setup on, or off again when it is already the active one. Returns the new state. */
    public Optional<SetupId> toggle(SetupId id) {
        Objects.requireNonNull(id, "id");
        Optional<SetupId> now;
        synchronized (lock) {
            active = id.equals(active) ? null : id;
            now = Optional.ofNullable(active);
        }
        notifyListeners();
        return now;
    }

    public void clear() {
        synchronized (lock) {
            if (active == null) {
                return;
            }
            active = null;
        }
        notifyListeners();
    }

    /** Listeners run right after every change, outside the lock; read {@link #current()} for the new state. */
    public void addListener(Runnable listener) {
        listeners.add(Objects.requireNonNull(listener, "listener"));
    }

    private void notifyListeners() {
        listeners.forEach(Runnable::run);
    }
}

