    boolean isBankOpen();

    /** A screen that is never open and never redraws, for before one is wired up. */
    static BankScreen none() {
        return new BankScreen() {
            @Override
            public void rebuild() {
            }

            @Override
            public boolean isBankOpen() {
                return false;
            }
        };
    }
}

