import net.runelite.api.Client;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Objects;

/**
 * How many items each numbered bank tab holds, read when the game changes one rather than when
 * something asks. The slot overlay needs these for every item it draws, so reading nine varbits per
 * item per frame is work worth doing once.
 */
@Singleton
public final class BankTabSizes {

    private static final int[] VARBITS = {
            VarbitID.BANK_TAB_1, VarbitID.BANK_TAB_2, VarbitID.BANK_TAB_3, VarbitID.BANK_TAB_4, VarbitID.BANK_TAB_5,
            VarbitID.BANK_TAB_6, VarbitID.BANK_TAB_7, VarbitID.BANK_TAB_8, VarbitID.BANK_TAB_9};
    private static final int[] UNREAD = new int[VARBITS.length];

    private final Client client;

    private volatile int[] counts = UNREAD;

    @Inject
    public BankTabSizes(Client client) {
        this.client = Objects.requireNonNull(client, "client");
    }

    /** Re-reads every tab size; client thread only. */
    public void refresh() {
        int[] read = new int[VARBITS.length];
        for (int index = 0; index < VARBITS.length; index++) {
            read[index] = client.getVarbitValue(VARBITS[index]);
        }
        counts = read;
    }

    /** The sizes as last read, tab 1 first. Callers must only read it. */
    public int[] counts() {
        return counts;
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        for (int varbit : VARBITS) {
            if (event.getVarbitId() == varbit) {
                refresh();
                return;
            }
        }
    }
}

package dev.dutchy.runelite.gear.bank;

import dev.dutchy.runelite.gear.activation.SetupActivator;
import net.runelite.api.Client;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import java.util.Objects;

/** Clicking a bank tab is the way back to a normal bank: it turns the shown setup off. */
public final class BankTabWatch {

    private static final int UNKNOWN = -1;

    private final Client client;
    private final SetupActivator activator;
    private int lastTab = UNKNOWN;

    @Inject
    public BankTabWatch(Client client, SetupActivator activator) {
        this.client = Objects.requireNonNull(client, "client");
        this.activator = Objects.requireNonNull(activator, "activator");
    }

    /** Reads the current tab; client thread only. */
    public void refresh() {
        lastTab = client.getVarbitValue(VarbitID.BANK_CURRENTTAB);
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        if (event.getVarbitId() != VarbitID.BANK_CURRENTTAB) {
            return;
        }
        int tab = event.getValue();
        boolean changed = lastTab != UNKNOWN && tab != lastTab;
        lastTab = tab;
        if (changed && activator.current().isPresent()) {
            activator.clear();
        }
    }
}

package dev.dutchy.runelite.gear.bank;

import java.util.Objects;

/** Which numbered tab a bank slot sits in, given how many items each tab holds. */
public final class BankTabs {

    public static final int TAB_COUNT = 9;
    public static final int MAIN_TAB = 0;

    private BankTabs() {
    }

    /**
     * The bank stores tabs one after another, tab 1 first, with the unfiled main tab after the last
     * numbered tab. Returns 1 to 9 for a numbered tab and {@link #MAIN_TAB} otherwise.
     */
    public static int tabOf(int bankIndex, int[] tabCounts) {
        Objects.requireNonNull(tabCounts, "tabCounts");
        if (bankIndex < 0) {
            throw new IllegalArgumentException("Bank index must be non-negative, got " + bankIndex);
        }
        int start = 0;
        for (int tab = 0; tab < Math.min(tabCounts.length, TAB_COUNT); tab++) {
            int end = start + Math.max(0, tabCounts[tab]);
            if (bankIndex < end) {
                return tab + 1;
            }
            start = end;
        }
        return MAIN_TAB;
    }
}

