package dev.dutchy.runelite.gear.bank;

import dev.dutchy.runelite.libs.ui.item.ItemId;

/** Where a player's choice of which family member a slot draws is sent. */
@FunctionalInterface
public interface SlotChooser {

    /** Draws the given stack in the slot from now on, until the layout is taken down. */
    void show(int slotIndex, ItemId id);
}

package dev.dutchy.runelite.gear.bank;

import lombok.Value;

import java.util.Objects;

/**
 * One widget child's finished appearance. {@code bankIndex} is the slot its withdraws must act on,
 * and {@code templateChild} the child whose look a twin copies; both are -1 when they do not apply,
 * as is {@code quantity} when the game's own count should stand. An empty {@code name} leaves the
 * name the child already has, which is how an item the player holds keeps its own menu text.
 */
@Value
public class SlotFace {

    public enum Kind {
        /** The child the game itself drew this item at, moved into place. */
        OWNED,
        /** A further copy of an item the player holds. */
        TWIN,
        /** An item the bank cannot supply, drawn ghosted and without a menu. */
        PLACEHOLDER
    }

    public static final int NONE = -1;

    Kind kind;
    BankSlotPlan plan;
    String name;
    int bankIndex;
    int templateChild;
    int x;
    int y;
    int opacity;
    int quantity;
    boolean hideQuantity;

    public SlotFace(Kind kind, BankSlotPlan plan, String name, int bankIndex, int templateChild,
                    int x, int y, int opacity, int quantity, boolean hideQuantity) {
        this.kind = Objects.requireNonNull(kind, "kind");
        this.plan = Objects.requireNonNull(plan, "plan");
        this.name = Objects.requireNonNull(name, "name");
        if (kind == Kind.TWIN && templateChild == NONE) {
            throw new IllegalArgumentException("A twin needs a template to copy");
        }
        this.bankIndex = bankIndex;
        this.templateChild = templateChild;
        this.x = x;
        this.y = y;
        this.opacity = opacity;
        this.quantity = quantity;
        this.hideQuantity = hideQuantity;
    }

    public boolean isPlaceholder() {
        return kind == Kind.PLACEHOLDER;
    }

    public boolean hasQuantity() {
        return quantity != NONE;
    }

    public boolean hasName() {
        return !name.isEmpty();
    }

    /** The same face dimmed, for an item a live search does not match. */
    public SlotFace dimmed(int dimOpacity) {
        return new SlotFace(kind, plan, name, bankIndex, templateChild, x, y, dimOpacity, quantity, hideQuantity);
    }
}

package dev.dutchy.runelite.gear.bank;

import java.util.*;

/**
 * The slots a bank build may reuse, and who gets which. An item the player holds keeps the slot that
 * already shows it, so the game still withdraws from the right place; any other slot can be borrowed
 * once, for a placeholder or a second copy. Slots are tracked by identity, never by equality, and
 * claimed slots are offered before spares so a borrow cannot take one the layout still needs.
 */
final class SlotPool<T> {

    private final Map<Integer, T> byItem = new HashMap<>();
    private final Deque<T> order = new ArrayDeque<>();
    private final Set<T> used = Collections.newSetFromMap(new IdentityHashMap<>());

    /** Offers a slot that currently shows the item. The first slot offered per item is its template. */
    void add(int itemId, T slot) {
        Objects.requireNonNull(slot, "slot");
        byItem.putIfAbsent(itemId, slot);
        order.add(slot);
    }

    /** The slot already showing the item, the first time it is asked for. */
    Optional<T> claim(int itemId) {
        T slot = byItem.get(itemId);
        return slot != null && used.add(slot) ? Optional.of(slot) : Optional.empty();
    }

    /** The slot showing the item, claimed or not, to copy an appearance from. */
    Optional<T> template(int itemId) {
        return Optional.ofNullable(byItem.get(itemId));
    }

    /** Any slot not yet handed out. */
    Optional<T> spare() {
        T slot;
        while ((slot = order.poll()) != null) {
            if (used.add(slot)) {
                return Optional.of(slot);
            }
        }
        return Optional.empty();
    }
}

package dev.dutchy.runelite.gear.bank;

import dev.dutchy.runelite.gear.content.ItemMatch;
import dev.dutchy.runelite.gear.content.SetupItem;
import dev.dutchy.runelite.gear.items.ItemCharges;
import dev.dutchy.runelite.gear.items.ItemNotes;
import dev.dutchy.runelite.gear.items.ItemVariants;
import dev.dutchy.runelite.libs.ui.item.ItemId;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;

/**
 * Picks the concrete stacks the bank can offer a setup item: the item's family in the order its
 * match rule prefers, then each alternative's family. The first candidate the bank holds anything
 * of supplies the slot, and every held member of that family counts towards it.
 */
@Singleton
public final class SlotResolver {

    private final ItemVariants variants;
    private final ItemNotes notes;
    private final ItemCharges charges;

    @Inject
    public SlotResolver(ItemVariants variants, ItemNotes notes, ItemCharges charges) {
        this.variants = Objects.requireNonNull(variants, "variants");
        this.notes = Objects.requireNonNull(notes, "notes");
        this.charges = Objects.requireNonNull(charges, "charges");
    }

    public SlotResolver(ItemVariants variants, ItemNotes notes) {
        this(variants, notes, ItemCharges.none());
    }

    public SlotResolver(ItemVariants variants) {
        this(variants, ItemNotes.none());
    }

    public Optional<ItemId> resolve(SetupItem item, BankContents bank) {
        return supply(item, bank).shown().map(SlotSupply.Stack::id);
    }

    /** What the bank holds for the item: the held members of the first candidate family that has any. */
    public SlotSupply supply(SetupItem item, BankContents bank) {
        Objects.requireNonNull(item, "item");
        Objects.requireNonNull(bank, "bank");
        for (List<ItemId> family : families(item)) {
            List<SlotSupply.Stack> held = new ArrayList<>();
            for (ItemId member : family) {
                int count = bank.count(member);
                if (count > 0) {
                    held.add(new SlotSupply.Stack(member, count));
                }
            }
            if (!held.isEmpty()) {
                return new SlotSupply(held);
            }
        }
        return SlotSupply.NONE;
    }

    /** Every id that would satisfy the item, most preferred first. */
    public List<ItemId> acceptable(SetupItem item) {
        List<ItemId> acceptable = new ArrayList<>();
        families(item).forEach(family -> family.forEach(member -> addOnce(acceptable, member)));
        return List.copyOf(acceptable);
    }

    /** The item's family and then each alternative's, every family in the order the match rule prefers. */
    private List<List<ItemId>> families(SetupItem item) {
        Objects.requireNonNull(item, "item");
        List<List<ItemId>> families = new ArrayList<>();
        List<ItemId> seen = new ArrayList<>();
        for (ItemId listed : item.candidates()) {
            ItemId candidate = notes.unnotedOf(listed).orElse(listed);
            List<ItemId> family = new ArrayList<>();
            for (ItemId member : ordered(candidate, item.match())) {
                if (!seen.contains(member)) {
                    seen.add(member);
                    family.add(member);
                }
            }
            if (!family.isEmpty()) {
                families.add(family);
            }
        }
        return families;
    }

    private List<ItemId> ordered(ItemId candidate, ItemMatch match) {
        if (!match.acceptsVariants()) {
            return List.of(candidate);
        }
        List<ItemId> family = new ArrayList<>(variants.familyOf(candidate));
        switch (match) {
            case EMPTIEST_FIRST:
                family.sort(Comparator.comparingInt(this::chargesOrMax));
                return family;
            case PREFER_THIS:
                family.sort(Comparator.comparingInt(this::chargesOrMin).reversed());
                family.remove(candidate);
                family.add(0, candidate);
                return family;
            default:
                family.sort(Comparator.comparingInt(this::chargesOrMin).reversed());
                return family;
        }
    }

    /** Members with no count sort last when the fullest go first. */
    private int chargesOrMin(ItemId id) {
        return charges.chargesOf(id).orElse(Integer.MIN_VALUE);
    }

    /** Members with no count sort last when the emptiest go first. */
    private int chargesOrMax(ItemId id) {
        return charges.chargesOf(id).orElse(Integer.MAX_VALUE);
    }

    private static void addOnce(List<ItemId> into, ItemId id) {
        if (!into.contains(id)) {
            into.add(id);
        }
    }
}

package dev.dutchy.runelite.gear.bank;

import dev.dutchy.runelite.libs.ui.item.ItemId;
import lombok.Value;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

/**
 * The stacks the bank holds that satisfy one slot, in the order the slot prefers them: the first is
 * drawn, the rest are the other doses or charges the player could switch to.
 */
@Value
public class SlotSupply {

    /** One held stack of one family member. */
    @Value
    public static class Stack {
        ItemId id;
        int count;

        public Stack(ItemId id, int count) {
            this.id = Objects.requireNonNull(id, "id");
            if (count < 1) {
                throw new IllegalArgumentException("A held stack has at least one, got " + count);
            }
            this.count = count;
        }
    }

    public static final SlotSupply NONE = new SlotSupply(List.of());

    List<Stack> stacks;

    public SlotSupply(List<Stack> stacks) {
        this.stacks = List.copyOf(Objects.requireNonNull(stacks, "stacks"));
    }

    public static SlotSupply of(Stack... stacks) {
        return new SlotSupply(List.of(stacks));
    }

    public boolean isEmpty() {
        return stacks.isEmpty();
    }

    /** The stack drawn in the slot. */
    public Optional<Stack> shown() {
        return stacks.stream().findFirst();
    }

    public int shownCount() {
        return shown().map(Stack::count).orElse(0);
    }

    /** Every stack across the family. */
    public int total() {
        return stacks.stream().mapToInt(Stack::count).sum();
    }

    /** The stacks the player could switch the slot to. */
    public List<Stack> others() {
        return stacks.size() <= 1 ? List.of() : stacks.subList(1, stacks.size());
    }

    public boolean hasOthers() {
        return stacks.size() > 1;
    }

    /** The same supply with the given stack drawn; unchanged when the bank does not hold it. */
    public SlotSupply showing(ItemId id) {
        Objects.requireNonNull(id, "id");
        List<Stack> reordered = new ArrayList<>(stacks);
        Optional<Stack> chosen = reordered.stream().filter(stack -> stack.id().equals(id)).findFirst();
        if (chosen.isEmpty()) {
            return this;
        }
        reordered.remove(chosen.get());
        reordered.add(0, chosen.get());
        return new SlotSupply(reordered);
    }
}

