package dev.dutchy.runelite.gear.bank;

import dev.dutchy.runelite.gear.content.ItemQuantityFormat;
import dev.dutchy.runelite.libs.ui.item.ItemId;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.function.Function;

/**
 * Adds a plugin-owned entry per other dose or charge the bank holds to a laid-out slot's menu, so the
 * player can draw that stack in the slot and then withdraw from it as usual. The entries only change
 * what the plugin draws; the game's own entries are left alone.
 */
public final class VariantSwitchMenu {

    static final String OPTION = "Show here";
    private static final int ABOVE_CANCEL = 1;

    /** One entry: the words to show and the stack it would draw. */
    @Value
    public static class Entry {
        String target;
        ItemId id;

        public Entry(String target, ItemId id) {
            this.target = Objects.requireNonNull(target, "target");
            this.id = Objects.requireNonNull(id, "id");
        }
    }

    private final Client client;
    private final DrawnBankSource bank;
    private final SlotChooser chooser;
    private final BankItemNames names;

    @Inject
    public VariantSwitchMenu(Client client, DrawnBankSource bank, SlotChooser chooser, BankItemNames names) {
        this.client = Objects.requireNonNull(client, "client");
        this.bank = Objects.requireNonNull(bank, "bank");
        this.chooser = Objects.requireNonNull(chooser, "chooser");
        this.names = Objects.requireNonNull(names, "names");
    }

    @Subscribe
    public void onMenuOpened(MenuOpened event) {
        DrawnBank shown = bank.drawnBank();
        MenuEntry first = event.getFirstEntry();
        if (!shown.active() || first == null || first.getParam1() != InterfaceID.Bankmain.ITEMS) {
            return;
        }
        Optional<DrawnSlot> slot = shown.at(first.getParam0());
        if (slot.isEmpty()) {
            return;
        }
        int slotIndex = slot.get().plan().slotIndex();
        for (Entry entry : entriesFor(slot.get(), names::of)) {
            client.getMenu().createMenuEntry(ABOVE_CANCEL)
                    .setOption(OPTION)
                    .setTarget(entry.target())
                    .setType(MenuAction.RUNELITE)
                    .setParam0(first.getParam0())
                    .setParam1(first.getParam1())
                    .onClick(clicked -> chooser.show(slotIndex, entry.id()));
        }
    }

    /** One entry per stack the slot could draw instead, in the slot's order of preference. */
    public static List<Entry> entriesFor(DrawnSlot slot, Function<ItemId, String> names) {
        Objects.requireNonNull(slot, "slot");
        Objects.requireNonNull(names, "names");
        List<Entry> entries = new ArrayList<>();
        for (SlotSupply.Stack stack : slot.plan().supply().others()) {
            entries.add(new Entry("<col=ff9040>" + names.apply(stack.id()) + "</col> x" + ItemQuantityFormat.text(stack.count()), stack.id()));
        }
        return List.copyOf(entries);
    }

}

package dev.dutchy.runelite.gear.bank;

import dev.dutchy.runelite.gear.GearSetup;
import dev.dutchy.runelite.gear.content.SetupVariant;
import lombok.Value;

import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;

/**
 * The row of variant tabs drawn above a layout in the bank: every variant's name with the chosen one
 * lit. Up to four share the strip's width; more than that scroll between a pair of arrows.
 */
@Value
public class VariantTabs {

    public static final VariantTabs NONE = new VariantTabs(List.of(), 0);
    public static final int VISIBLE = 4;
    public static final int GAP = 4;
    public static final int ARROW_WIDTH = 18;

    List<String> names;
    int chosen;

    public VariantTabs(List<String> names, int chosen) {
        this.names = List.copyOf(Objects.requireNonNull(names, "names"));
        if (!this.names.isEmpty() && (chosen < 0 || chosen >= this.names.size())) {
            throw new IllegalArgumentException("No tab " + chosen + " among " + this.names.size());
        }
        this.chosen = chosen;
    }

    /** Tabs for a setup with more than one variant, none otherwise. */
    public static VariantTabs of(GearSetup setup) {
        Objects.requireNonNull(setup, "setup");
        if (!setup.hasVariants()) {
            return NONE;
        }
        return new VariantTabs(setup.variants().stream().map(SetupVariant::name).collect(Collectors.toList()), setup.selectedIndex());
    }

    public boolean isEmpty() {
        return names.isEmpty();
    }

    public int count() {
        return names.size();
    }

    /** Room the strip takes above the first row, nothing when there are no tabs. */
    public int height() {
        return isEmpty() ? 0 : BankGeometry.VARIANT_STRIP_HEIGHT;
    }

    /** Whether there are more tabs than fit on show at once, so the arrows are needed. */
    public boolean overflows() {
        return count() > VISIBLE;
    }

    /** How many tabs are on show at once. */
    public int visibleCount() {
        return Math.min(count(), VISIBLE);
    }

    /** The first tab on show after scrolling by {@code offset}, kept within what can scroll. */
    public int clampOffset(int offset) {
        return Math.max(0, Math.min(offset, count() - visibleCount()));
    }

    /** The last offset that can be scrolled to. */
    public int maxOffset() {
        return clampOffset(Integer.MAX_VALUE);
    }

    /** The offset that brings the chosen tab into view from the given one. */
    public int offsetShowingChosen(int offset) {
        int first = clampOffset(offset);
        if (chosen < first) {
            return chosen;
        }
        int last = first + visibleCount() - 1;
        return chosen > last ? clampOffset(chosen - visibleCount() + 1) : first;
    }

    /** How wide each tab is when the visible ones share the strip's width, at least a pixel. */
    public int tabWidth(int width) {
        int room = width - (overflows() ? 2 * (ARROW_WIDTH + GAP) : 0) - (visibleCount() - 1) * GAP;
        return Math.max(1, room / visibleCount());
    }

    /** Where a visible tab starts, measured from the strip's left edge. */
    public int tabX(int position, int width) {
        return (overflows() ? ARROW_WIDTH + GAP : 0) + position * (tabWidth(width) + GAP);
    }
}

package dev.dutchy.runelite.gear.bank;

import dev.dutchy.runelite.gear.config.GearComposerConfig;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

/**
 * Makes the withdraw option that matches the setup's amount the left-click while a setup is shown.
 * Only the order of the game's own entries changes, as RuneLite's menu entry swapper does.
 */
public final class WithdrawMenuSwapper {

    private final Client client;
    private final DrawnBankSource bank;
    private final GearComposerConfig config;

    @Inject
    public WithdrawMenuSwapper(Client client, DrawnBankSource bank, GearComposerConfig config) {
        this.client = Objects.requireNonNull(client, "client");
        this.bank = Objects.requireNonNull(bank, "bank");
        this.config = Objects.requireNonNull(config, "config");
    }

    @Subscribe
    public void onPostMenuSort(PostMenuSort event) {
        DrawnBank shown = bank.drawnBank();
        if (!config.withdrawSetupAmount() || !shown.active()) {
            return;
        }
        MenuEntry[] entries = client.getMenu().getMenuEntries();
        if (entries.length == 0) {
            return;
        }
        MenuEntry top = entries[entries.length - 1];
        if (top.getParam1() != InterfaceID.Bankmain.ITEMS) {
            return;
        }
        Optional<DrawnSlot> slot = shown.at(top.getParam0());
        if (slot.isEmpty() || !slot.get().plan().item().hasQuantity()) {
            return;
        }
        List<String> options = new ArrayList<>();
        for (MenuEntry entry : entries) {
            options.add(entry.getOption());
        }
        Optional<String> preferred = WithdrawOption.preferred(slot.get().required(), options);
        if (preferred.isEmpty() || preferred.get().equals(top.getOption())) {
            return;
        }
        client.getMenu().setMenuEntries(reordered(entries, preferred.get()));
    }

    /** The preferred entry moved to the end, which the client treats as the left-click option. */
    static MenuEntry[] reordered(MenuEntry[] entries, String preferredOption) {
        List<MenuEntry> others = new ArrayList<>();
        MenuEntry chosen = null;
        for (MenuEntry entry : entries) {
            if (chosen == null && preferredOption.equals(entry.getOption())) {
                chosen = entry;
            } else {
                others.add(entry);
            }
        }
        if (chosen == null) {
            return entries;
        }
        others.add(chosen);
        return others.toArray(new MenuEntry[0]);
    }
}

package dev.dutchy.runelite.gear.bank;

import dev.dutchy.runelite.gear.content.QuantityText;

import java.util.List;
import java.util.Objects;
import java.util.Optional;

/** Picks the bank's withdraw entry that hands over exactly the amount a setup asks for. */
public final class WithdrawOption {

    private static final String PREFIX = "Withdraw-";
    private static final String ALL = "Withdraw-All";

    private WithdrawOption() {
    }

    /** The menu option to prefer for {@code amount}, if the bank offers one that matches. */
    public static Optional<String> preferred(int amount, List<String> options) {
        Objects.requireNonNull(options, "options");
        if (amount == QuantityText.MAX && options.contains(ALL)) {
            return Optional.of(ALL);
        }
        String exact = PREFIX + amount;
        return options.stream().filter(exact::equals).findFirst();
    }
}

