package dev.dutchy.runelite.gear.content;

import lombok.Value;

import java.util.Objects;

/**
 * One named version of a setup's contents, such as Budget or Best-in-slot. The id is what points at
 * a variant, so a pointer survives the variant being renamed or moved.
 */
@Value
public class SetupVariant {
    VariantId id;
    String name;
    SetupContent content;

    public static final String DEFAULT_NAME = "Default";
    public static final int MAX_NAME_LENGTH = 24;

    public SetupVariant(String name, SetupContent content) {
        this(VariantId.random(), name, content);
    }

    public SetupVariant(VariantId id, String name, SetupContent content) {
        this.id = Objects.requireNonNull(id, "id");
        this.name = requireValidName(name);
        this.content = Objects.requireNonNull(content, "content");
    }

    public static SetupVariant of(SetupContent content) {
        return new SetupVariant(DEFAULT_NAME, content);
    }

    public boolean hasId(VariantId other) {
        return id.equals(other);
    }

    /** The same variant under another id, as when a shared setup is taken in. */
    public SetupVariant withId(VariantId newId) {
        return new SetupVariant(newId, name, content);
    }

    public SetupType type() {
        return content.type();
    }

    public SetupVariant withName(String newName) {
        return new SetupVariant(id, newName, content);
    }

    public SetupVariant withContent(SetupContent newContent) {
        return new SetupVariant(id, name, newContent);
    }

    public boolean isNamed(String other) {
        return other != null && name.equalsIgnoreCase(other.strip());
    }

    public static String requireValidName(String name) {
        Objects.requireNonNull(name, "name");
        String trimmed = name.strip();
        if (trimmed.isEmpty() || trimmed.length() > MAX_NAME_LENGTH) {
            throw new IllegalArgumentException("Variant name must be 1 to " + MAX_NAME_LENGTH + " characters");
        }
        return trimmed;
    }

    public static boolean isValidName(String name) {
        return name != null && !name.isBlank() && name.strip().length() <= MAX_NAME_LENGTH;
    }
}

package dev.dutchy.runelite.gear.content;

import lombok.Value;
import java.util.List;
import java.util.Objects;

/** Items lifted from slots, with where they came from so equipment goes back to matching slots. */
@Value
public class SlotClipboard {
    List<Entry> entries;


    @Value
    public static class Entry {
        SlotRef from;
        SetupItem item;

        public Entry(SlotRef from, SetupItem item) {
            Objects.requireNonNull(from, "from");
            Objects.requireNonNull(item, "item");
            this.from = from;
            this.item = item;
        }
    }

    public SlotClipboard(List<Entry> entries) {
        entries = List.copyOf(Objects.requireNonNull(entries, "entries"));
        this.entries = entries;
    }

    public static SlotClipboard empty() {
        return new SlotClipboard(List.of());
    }

    public boolean isEmpty() {
        return entries.isEmpty();
    }

    public int size() {
        return entries.size();
    }
}

package dev.dutchy.runelite.gear.content;

import lombok.Value;
import java.util.Objects;

public interface SlotRef {

    String describe();

    /** Whether the slot sits in an item grid, so it can name its neighbours. */
    default boolean inGrid() {
        return false;
    }

    default int gridIndex() {
        throw new IllegalStateException(describe() + " is not a grid slot");
    }

    /** The slot at {@code index} in the same grid as this one. */
    default SlotRef gridSibling(int index) {
        throw new IllegalStateException(describe() + " is not a grid slot");
    }

    static SlotRef of(EquipmentSlot slot) {
        return new Equipment(slot);
    }

    static SlotRef of(GridKind grid, int index) {
        return new Grid(grid, index);
    }

    static SlotRef in(CellRef cell, SlotRef inner) {
        return new Cell(cell, inner);
    }

    /** A slot inside one cell of a custom layout; the inner reference is an equipment slot or an inventory slot. */
    @Value
    class Cell implements SlotRef {
        CellRef cell;
        SlotRef inner;

        public Cell(CellRef cell, SlotRef inner) {
            this.cell = Objects.requireNonNull(cell, "cell");
            this.inner = Objects.requireNonNull(inner, "inner");
            if (!(inner instanceof Equipment) && !(inner instanceof Grid)) {
                throw new IllegalArgumentException("A cell holds equipment or inventory slots, not " + inner.describe());
            }
        }

        @Override
        public String describe() {
            return cell.describe() + ", " + inner.describe();
        }

        @Override
        public boolean inGrid() {
            return inner.inGrid();
        }

        @Override
        public int gridIndex() {
            return inner.gridIndex();
        }

        @Override
        public SlotRef gridSibling(int index) {
            return new Cell(cell, inner.gridSibling(index));
        }
    }

    @Value
    class Equipment implements SlotRef {
        EquipmentSlot slot;


        public Equipment(EquipmentSlot slot) {
            Objects.requireNonNull(slot, "slot");
            this.slot = slot;
        }

        @Override
        public String describe() {
            return slot.displayName();
        }
    }

    @Value
    class Grid implements SlotRef {
        GridKind grid;
        int index;


        public Grid(GridKind grid, int index) {
            Objects.requireNonNull(grid, "grid");
            if (index < 0 || index >= ItemGrid.SIZE) {
                throw new IllegalArgumentException("Slot index must be within [0, " + ItemGrid.SIZE + "), got " + index);
            }
            this.grid = grid;
            this.index = index;
        }

        @Override
        public String describe() {
            return grid.displayName() + " slot " + (index + 1);
        }

        @Override
        public boolean inGrid() {
            return true;
        }

        @Override
        public int gridIndex() {
            return index;
        }

        @Override
        public SlotRef gridSibling(int newIndex) {
            return new Grid(grid, newIndex);
        }
    }
}

