package dev.dutchy.runelite.gear.history;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import dev.dutchy.runelite.gear.SetupId;
import dev.dutchy.runelite.gear.content.VariantId;
import dev.dutchy.runelite.gear.persistence.ContentCodec;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.UUID;
import java.util.stream.Collectors;

/** One JSON file per setup under a directory; an unreadable file counts as no history. */
public final class FileHistoryStore implements HistoryStore {

    private static final Logger log = LoggerFactory.getLogger(FileHistoryStore.class);

    private final Path directory;
    private final Gson gson;

    public FileHistoryStore(Path directory, Gson gson) {
        this.directory = Objects.requireNonNull(directory, "directory");
        this.gson = Objects.requireNonNull(gson, "gson");
    }

    @Override
    public List<SetupRevision> revisions(SetupId setup) {
        Path file = fileFor(setup);
        if (!Files.exists(file)) {
            return List.of();
        }
        try {
            List<RevisionDto> dtos = gson.fromJson(Files.readString(file, StandardCharsets.UTF_8),
                    new TypeToken<List<RevisionDto>>() {
                    }.getType());
            List<SetupRevision> revisions = new ArrayList<>();
            for (RevisionDto dto : dtos == null ? List.<RevisionDto>of() : dtos) {
                revisions.add(new SetupRevision(Instant.ofEpochMilli(dto.at), dto.cause, variantOf(dto.variant),
                        ContentCodec.fromDto(dto.content)));
            }
            return List.copyOf(revisions);
        } catch (IOException | JsonParseException | IllegalArgumentException | NullPointerException e) {
            log.warn("History for {} could not be read", setup, e);
            return List.of();
        }
    }

    @Override
    public void record(SetupId setup, SetupRevision revision) {
        Objects.requireNonNull(revision, "revision");
        write(setup, RevisionTrail.with(revisions(setup), revision));
    }

    @Override
    public void forget(SetupId setup) {
        try {
            Files.deleteIfExists(fileFor(setup));
        } catch (IOException e) {
            log.warn("History for {} could not be removed", setup, e);
        }
    }

    private void write(SetupId setup, List<SetupRevision> trail) {
        List<RevisionDto> dtos = trail.stream().map(revision -> {
            RevisionDto dto = new RevisionDto();
            dto.at = revision.at().toEpochMilli();
            dto.cause = revision.cause();
            dto.variant = revision.variant().map(variant -> variant.value().toString()).orElse(null);
            dto.content = ContentCodec.toDto(revision.content());
            return dto;
        }).collect(Collectors.toList());
        try {
            Files.createDirectories(directory);
            Path temporary = Files.createTempFile(directory, "history", ".tmp");
            Files.writeString(temporary, gson.toJson(dtos), StandardCharsets.UTF_8);
            Files.move(temporary, fileFor(setup), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
        } catch (IOException e) {
            log.warn("History for {} could not be written", setup, e);
        }
    }

    /** A revision written before variants had ids has none, and restores into whichever is shown. */
    private static VariantId variantOf(String written) {
        return written == null ? null : new VariantId(UUID.fromString(written));
    }

    private Path fileFor(SetupId setup) {
        return directory.resolve(Objects.requireNonNull(setup, "setup").value() + ".json");
    }

    private static final class RevisionDto {
        long at;
        String cause;
        String variant;
        ContentCodec.ContentDto content;
    }
}

package dev.dutchy.runelite.gear.history;

import dev.dutchy.runelite.gear.SetupId;

import java.util.List;

/** Keeps a bounded trail of past contents per setup. Newest first. Safe to call from the EDT. */
public interface HistoryStore {

    int MAX_REVISIONS = 10;

    List<SetupRevision> revisions(SetupId setup);

    void record(SetupId setup, SetupRevision revision);

    void forget(SetupId setup);
}

package dev.dutchy.runelite.gear.history;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Objects;

/**
 * How a setup's trail of revisions grows. Each variant keeps its own last
 * {@link HistoryStore#MAX_REVISIONS}, so editing one variant cannot push another's history out.
 */
final class RevisionTrail {

    private RevisionTrail() {
    }

    /** The trail with the revision at its head, newest first, trimmed to what its variant may keep. */
    static List<SetupRevision> with(List<SetupRevision> trail, SetupRevision revision) {
        Objects.requireNonNull(trail, "trail");
        Objects.requireNonNull(revision, "revision");
        List<SetupRevision> updated = new ArrayList<>(trail);
        updated.add(0, revision);
        int kept = 0;
        for (Iterator<SetupRevision> each = updated.iterator(); each.hasNext(); ) {
            if (each.next().variant().equals(revision.variant()) && ++kept > HistoryStore.MAX_REVISIONS) {
                each.remove();
            }
        }
        return List.copyOf(updated);
    }
}

package dev.dutchy.runelite.gear.history;

import dev.dutchy.runelite.gear.GearSetup;
import dev.dutchy.runelite.gear.GearSetupBook;
import dev.dutchy.runelite.gear.SetupId;
import dev.dutchy.runelite.gear.content.SetupContent;
import dev.dutchy.runelite.gear.content.VariantId;

import javax.inject.Inject;
import java.time.Clock;
import java.util.List;
import java.util.Objects;

/** Records a setup's previous items whenever its contents change through here. */
public final class SetupHistory {

    private final GearSetupBook book;
    private final HistoryStore store;
    private final Clock clock;

    @Inject
    public SetupHistory(GearSetupBook book, HistoryStore store, Clock clock) {
        this.book = Objects.requireNonNull(book, "book");
        this.store = Objects.requireNonNull(store, "store");
        this.clock = Objects.requireNonNull(clock, "clock");
    }

    /** Replaces the selected variant's contents and remembers what they were, unless nothing changed. */
    public void applyContent(SetupId setup, SetupContent content, String cause) {
        applyContent(setup, found(setup).selected(), content, cause);
    }

    /** Replaces one variant's contents and remembers what they were, unless nothing changed. */
    public void applyContent(SetupId setup, VariantId variant, SetupContent content, String cause) {
        Objects.requireNonNull(content, "content");
        SetupContent before = found(setup).variant(variant)
                .orElseThrow(() -> new IllegalArgumentException("No variant " + variant)).content();
        if (before.equals(content)) {
            return;
        }
        store.record(setup, new SetupRevision(clock.instant(), cause, variant, before));
        book.updateVariantContent(setup, variant, content);
    }

    private GearSetup found(SetupId setup) {
        return book.setup(setup).orElseThrow(() -> new IllegalArgumentException("No setup " + setup));
    }

    public List<SetupRevision> revisions(SetupId setup) {
        return store.revisions(setup);
    }

    /**
     * Puts an old revision back into the variant it came from, recording the current contents first so the
     * restore itself can be undone. A revision from before variants had ids goes to the selected variant.
     */
    public void restore(SetupId setup, SetupRevision revision) {
        Objects.requireNonNull(revision, "revision");
        applyContent(setup, revision.variant().orElseGet(() -> found(setup).selected()),
                revision.content(), "Restored from history");
    }

    public void forget(SetupId setup) {
        store.forget(setup);
    }
}

package dev.dutchy.runelite.gear.history;

import dev.dutchy.runelite.gear.content.SetupContent;
import dev.dutchy.runelite.gear.content.VariantId;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Value;

import java.time.Instant;
import java.util.Objects;
import java.util.Optional;

/** What one variant's items looked like before a change, and what caused the change. */
@Value
public class SetupRevision {
    Instant at;
    String cause;
    @Getter(AccessLevel.NONE)
    VariantId variantId;
    SetupContent content;

    public static final int MAX_CAUSE = 60;

    /** A revision from before variants carried ids, so it does not know which one it came from. */
    public SetupRevision(Instant at, String cause, SetupContent content) {
        this(at, cause, null, content);
    }

    /** The variant this came from, empty for a revision recorded before variants had ids. */
    public Optional<VariantId> variant() {
        return Optional.ofNullable(variantId);
    }

    public SetupRevision(Instant at, String cause, VariantId variantId, SetupContent content) {
        Objects.requireNonNull(at, "at");
        Objects.requireNonNull(content, "content");
        cause = Objects.requireNonNull(cause, "cause").strip();
        if (cause.isEmpty() || cause.length() > MAX_CAUSE) {
            throw new IllegalArgumentException("A cause must be 1 to " + MAX_CAUSE + " characters");
        }
        this.at = at;
        this.cause = cause;
        this.variantId = variantId;
        this.content = content;
    }
}

package dev.dutchy.runelite.gear.items;

import dev.dutchy.runelite.libs.ui.item.ItemId;

import java.util.OptionalInt;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** The charges or doses an item variant carries, read from the "(n)" the game puts at the end of its name. */
public interface ItemCharges {

    Pattern TRAILING_COUNT = Pattern.compile("\\((\\d+)\\)\\s*$");

    /** Empty when the item has no charge count in its name. */
    OptionalInt chargesOf(ItemId item);

    static ItemCharges none() {
        return item -> OptionalInt.empty();
    }

    static OptionalInt parse(String name) {
        if (name == null) {
            return OptionalInt.empty();
        }
        Matcher matcher = TRAILING_COUNT.matcher(name);
        return matcher.find() ? OptionalInt.of(Integer.parseInt(matcher.group(1))) : OptionalInt.empty();
    }
}

package dev.dutchy.runelite.gear.items;

import dev.dutchy.runelite.libs.ui.item.ItemId;

import java.util.Optional;

/** Links noted items to the real item they stand for. */
public interface ItemNotes {

    /** The unnoted item behind a note; empty when the id is not a note. */
    Optional<ItemId> unnotedOf(ItemId item);

    /** Treats nothing as a note. */
    static ItemNotes none() {
        return item -> Optional.empty();
    }
}

package dev.dutchy.runelite.gear.items;

import dev.dutchy.runelite.libs.ui.item.ItemId;

import java.util.Collection;
import java.util.List;

/** Knows which item ids belong to the same family: charges, doses, degrade states, imbues. */
@FunctionalInterface
public interface ItemVariants {

    /** Every id in the family, including {@code item} itself, in a stable order. */
    Collection<ItemId> familyOf(ItemId item);

    /** Treats every item as its own family. */
    static ItemVariants none() {
        return List::of;
    }
}

package dev.dutchy.runelite.gear.items;

import dev.dutchy.runelite.libs.ui.item.ItemId;
import net.runelite.api.Client;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Map;
import java.util.Objects;
import java.util.OptionalInt;
import java.util.concurrent.ConcurrentHashMap;

/** Reads charge counts from item names; must be used on the client thread. */
@Singleton
public final class RuneLiteItemCharges implements ItemCharges {

    private final Client client;
    private final Map<ItemId, OptionalInt> known = new ConcurrentHashMap<>();

    @Inject
    public RuneLiteItemCharges(Client client) {
        this.client = Objects.requireNonNull(client, "client");
    }

    @Override
    public OptionalInt chargesOf(ItemId item) {
        return known.computeIfAbsent(Objects.requireNonNull(item, "item"), this::lookUp);
    }

    private OptionalInt lookUp(ItemId item) {
        return ItemCharges.parse(client.getItemDefinition(item.value()).getName());
    }
}

package dev.dutchy.runelite.gear.items;

import dev.dutchy.runelite.libs.ui.item.ItemId;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Objects;
import java.util.Optional;

/** Reads note links from item definitions; must be used on the client thread. */
@Singleton
public final class RuneLiteItemNotes implements ItemNotes {

    private final Client client;

    @Inject
    public RuneLiteItemNotes(Client client) {
        this.client = Objects.requireNonNull(client, "client");
    }

    @Override
    public Optional<ItemId> unnotedOf(ItemId item) {
        ItemComposition definition = client.getItemDefinition(Objects.requireNonNull(item, "item").value());
        if (definition.getNote() == -1) {
            return Optional.empty();
        }
        int linked = definition.getLinkedNoteId();
        return linked >= 0 ? Optional.of(ItemId.of(linked)) : Optional.empty();
    }
}

package dev.dutchy.runelite.gear.items;

import dev.dutchy.runelite.libs.ui.item.ItemId;
import net.runelite.client.game.ItemVariationMapping;

import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Objects;

/** Backed by RuneLite's item variation table. */
@Singleton
public final class RuneLiteItemVariants implements ItemVariants {

    @Override
    public Collection<ItemId> familyOf(ItemId item) {
        Objects.requireNonNull(item, "item");
        int base = ItemVariationMapping.map(item.value());
        List<ItemId> family = new ArrayList<>();
        family.add(item);
        for (int variation : ItemVariationMapping.getVariations(base)) {
            ItemId candidate = ItemId.of(variation);
            if (!family.contains(candidate)) {
                family.add(candidate);
            }
        }
        return List.copyOf(family);
    }
}

package dev.dutchy.runelite.gear.layout;

import lombok.Value;

import java.util.*;
import java.util.stream.Collectors;

/** A horizontal strip of the layout: the blocks that sit side by side, and the rows they take together. */
@Value
public class Band {
    int index;
    List<LayoutBlock> blocks;

    public Band(int index, List<LayoutBlock> blocks) {
        this.index = index;
        this.blocks = List.copyOf(Objects.requireNonNull(blocks, "blocks"));
        if (this.blocks.isEmpty()) {
            throw new IllegalArgumentException("A band holds at least one block");
        }
    }

    public int rowsTall() {
        return blocks.stream().mapToInt(LayoutBlock::rowsTall).max().orElse(0);
    }

    /** Header rows of the band, relative to its first row. */
    public SortedSet<Integer> headerRows() {
        return blocks.stream().flatMap(block -> block.headerRows().stream()).map(row -> row - firstRow())
                .collect(Collectors.toCollection(TreeSet::new));
    }

    public Optional<Integer> labelRow() {
        return blocks.get(0).labelRow();
    }

    public int firstRow() {
        return blocks.get(0).firstRow();
    }

    public Optional<LayoutBlock> on(BankSide side) {
        return blocks.stream().filter(block -> block.side() == side).findFirst();
    }
}

