import java.util.function.UnaryOperator;
import java.util.stream.Collectors;

/** A four by seven item grid with its dividers. */
public final class GridBlock extends LayoutBlock {

    private final GridKind kind;
    private final ItemGrid grid;
    private final UnaryOperator<SlotRef> refs;

    GridBlock(String title, int band, BankSide side, int firstRow, Integer labelRow, GridKind kind, ItemGrid grid, UnaryOperator<SlotRef> refs) {
        super(title, band, side, firstRow, labelRow);
        this.kind = Objects.requireNonNull(kind, "kind");
        this.grid = Objects.requireNonNull(grid, "grid");
        this.refs = Objects.requireNonNull(refs, "refs");
    }

    public GridKind kind() {
        return kind;
    }

    public ItemGrid grid() {
        return grid;
    }

    public SlotRef ref(int index) {
        return refs.apply(SlotRef.of(kind, index));
    }

    @Override
    public int rowsTall() {
        return ItemGrid.ROWS;
    }

    @Override
    public List<Integer> headerRows() {
        return grid.rowsWithDividers().stream().map(row -> firstRow() + row).collect(Collectors.toList());
    }

    @Override
    public int columnsWide() {
        return ItemGrid.COLUMNS;
    }

    @Override
    public List<Slot> slots() {
        List<Slot> slots = new ArrayList<>();
        for (int index = 0; index < ItemGrid.SIZE; index++) {
            slots.add(new Slot(ref(index), grid.slot(index).orElse(null)));
        }
        return List.copyOf(slots);
    }

    @Override
    public List<BankPlacement> placements() {
        List<BankPlacement> placements = new ArrayList<>();
        for (int index = 0; index < ItemGrid.SIZE; index++) {
            int slotIndex = index;
            grid.slot(index).ifPresent(item -> placements.add(new BankPlacement(side(), ItemGrid.column(slotIndex),
                    firstRow() + ItemGrid.row(slotIndex), item)));
        }
        return List.copyOf(placements);
    }

    @Override
    List<LayoutLabel> labels() {
        List<LayoutLabel> labels = new ArrayList<>(super.labels());
        grid.dividers().forEach(divider -> labels.add(LayoutLabel.header(side(), firstRow() + divider.row(),
                divider.fromColumn(), divider.toColumn(), divider.label(), divider.align(), divider.underlined())));
        return List.copyOf(labels);
    }

    @Override
    public <R> R accept(Visitor<R> visitor) {
        return visitor.grid(this);
    }
}

package dev.dutchy.runelite.gear.layout;

import dev.dutchy.runelite.gear.content.*;

import java.util.*;
import java.util.function.UnaryOperator;
import java.util.stream.Collectors;

/**
 * A setup's contents as blocks in bands, the one place that knows what each layout type looks like.
 * Everything that draws, plans, sums or compares a setup walks these blocks instead of asking the shape.
 */
public final class Layout {

    private final List<LayoutBlock> blocks;

    private Layout(List<LayoutBlock> blocks) {
        this.blocks = List.copyOf(blocks);
    }

    public static Layout of(SetupContent content) {
        Objects.requireNonNull(content, "content");
        if (content instanceof GearContent) {
            return ofGear((GearContent) content);
        }
        if (content instanceof BankContent) {
            return ofBank((BankContent) content);
        }
        return ofCustom((CustomContent) content);
    }

    public List<LayoutBlock> blocks() {
        return blocks;
    }

    public List<Band> bands() {
        Map<Integer, List<LayoutBlock>> grouped = new TreeMap<>();
        blocks.forEach(block -> grouped.computeIfAbsent(block.band(), b -> new ArrayList<>()).add(block));
        return grouped.entrySet().stream().map(entry -> new Band(entry.getKey(), entry.getValue())).collect(Collectors.toList());
    }

    /** Bank rows the whole layout takes. */
    public int rowsTall() {
        return blocks.stream().mapToInt(block -> block.firstRow() + block.rowsTall()).max().orElse(0);
    }

    public List<BankPlacement> placements() {
        return blocks.stream().flatMap(block -> block.placements().stream()).collect(Collectors.toList());
    }

    public List<LayoutLabel> labels() {
        return blocks.stream().flatMap(block -> block.labels().stream()).collect(Collectors.toList());
    }

    /** Bank rows that carry a header strip on either side; both sides grow together so they stay aligned. */
    public SortedSet<Integer> headerRows() {
        return blocks.stream().flatMap(block -> block.headerRows().stream()).collect(Collectors.toCollection(TreeSet::new));
    }

    /** Every slot of every block, in reading order. */
    public List<LayoutBlock.Slot> slots() {
        return blocks.stream().flatMap(block -> block.slots().stream()).collect(Collectors.toList());
    }

    public List<SetupItem> items() {
        return blocks.stream().flatMap(block -> block.items().stream()).collect(Collectors.toList());
    }

    public boolean hasLabelledBands() {
        return bands().stream().anyMatch(band -> band.labelRow().isPresent());
    }

    private static Layout ofGear(GearContent gear) {
        return new Layout(List.of(
                new EquipmentBlock("Equipment", 0, BankSide.LEFT, 0, null, gear.equipment(), UnaryOperator.identity(), true),
                new GridBlock("Inventory", 0, BankSide.RIGHT, 0, null, GridKind.INVENTORY, gear.inventory(), UnaryOperator.identity())));
    }

    private static Layout ofBank(BankContent bank) {
        return new Layout(List.of(
                new GridBlock("Left side", 0, BankSide.LEFT, 0, null, GridKind.LEFT, bank.left(), UnaryOperator.identity()),
                new GridBlock("Right side", 0, BankSide.RIGHT, 0, null, GridKind.RIGHT, bank.right(), UnaryOperator.identity())));
    }

    private static Layout ofCustom(CustomContent custom) {
        List<LayoutBlock> blocks = new ArrayList<>();
        int cursor = 0;
        for (int row = 0; row < custom.rows(); row++) {
            List<LayoutBlock> band = new ArrayList<>();
            for (int column = 0; column < CustomContent.COLUMNS; column++) {
                CellRef ref = CellRef.of(row, column);
                LayoutCell cell = custom.cell(ref);
                BankSide side = ref.isLeft() ? BankSide.LEFT : BankSide.RIGHT;
                UnaryOperator<SlotRef> refs = inner -> SlotRef.in(ref, inner);
                if (cell.kind() == CellKind.EQUIPMENT) {
                    band.add(new EquipmentBlock(cell.label(), row, side, cursor + 1, cursor, cell.equipment(), refs, false));
                } else if (cell.kind() == CellKind.INVENTORY) {
                    band.add(new GridBlock(cell.label(), row, side, cursor + 1, cursor, GridKind.INVENTORY, cell.inventory(), refs));
                }
            }
            if (band.isEmpty()) {
                continue;
            }
            blocks.addAll(band);
            cursor += 1 + band.stream().mapToInt(LayoutBlock::rowsTall).max().orElse(0);
        }
        return new Layout(blocks);
    }
}

package dev.dutchy.runelite.gear.layout;

import dev.dutchy.runelite.gear.content.SetupItem;
import dev.dutchy.runelite.gear.content.SlotRef;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Collectors;

/**
 * One piece of a layout with a fixed shape: an equipment cross or an item grid.
 * A block knows its band, its side of the bank, the bank row its items start on, and the row its
 * title is painted on when it has one.
 */
public abstract class LayoutBlock {

    /** How a consumer tells the shapes apart without an instanceof chain. */
    public interface Visitor<R> {
        R equipment(EquipmentBlock block);

        R grid(GridBlock block);
    }

    /** One slot of a block: where it is and what it holds. */
    public static final class Slot {
        private final SlotRef ref;
        private final SetupItem item;

        Slot(SlotRef ref, SetupItem item) {
            this.ref = Objects.requireNonNull(ref, "ref");
            this.item = item;
        }

        public SlotRef ref() {
            return ref;
        }

        public Optional<SetupItem> item() {
            return Optional.ofNullable(item);
        }
    }

    private final String title;
    private final int band;
    private final BankSide side;
    private final int firstRow;
    private final Integer labelRow;

    LayoutBlock(String title, int band, BankSide side, int firstRow, Integer labelRow) {
        this.title = Objects.requireNonNull(title, "title");
        this.band = band;
        this.side = Objects.requireNonNull(side, "side");
        this.firstRow = firstRow;
        this.labelRow = labelRow;
    }

    public String title() {
        return title;
    }

    /** Blocks in the same band sit side by side; bands stack top to bottom. */
    public int band() {
        return band;
    }

    public BankSide side() {
        return side;
    }

    /** The bank row the block's first item row lands on. */
    public int firstRow() {
        return firstRow;
    }

    /** The bank row the title is painted on, when the block has one. */
    public Optional<Integer> labelRow() {
        return Optional.ofNullable(labelRow);
    }

    /** Bank rows the block's items take. */
    public abstract int rowsTall();

    /** Bank rows of this block that carry a header strip above their items. */
    public List<Integer> headerRows() {
        return List.of();
    }

    /** Columns the block takes on its side of the bank. */
    public abstract int columnsWide();

    /** Every slot of the block, filled or not, in reading order. */
    public abstract List<Slot> slots();

    public abstract List<BankPlacement> placements();

    public abstract <R> R accept(Visitor<R> visitor);

    /** Every item the block holds, in slot order. */
    public List<SetupItem> items() {
        return slots().stream().filter(slot -> slot.item().isPresent()).map(slot -> slot.item().get()).collect(Collectors.toList());
    }

    public boolean isEmpty() {
        return items().isEmpty();
    }

    List<LayoutLabel> labels() {
        return labelRow == null ? List.of() : List.of(new LayoutLabel(side, labelRow, title));
    }
}

package dev.dutchy.runelite.gear.layout;

import dev.dutchy.runelite.gear.content.ItemGrid;
import dev.dutchy.runelite.gear.content.TextAlign;
import lombok.Value;

import java.util.Objects;

/**
 * Text the bank paints for a layout: a band's title on a blank row across its side, or a divider in
 * the header strip of the row it heads, across the columns it spans.
 */
@Value
public class LayoutLabel {
    BankSide side;
    int row;
    int fromColumn;
    int toColumn;
    String text;
    TextAlign align;
    boolean header;
    boolean underlined;

    /** A title on a blank row across the whole side, read from the left. */
    public LayoutLabel(BankSide side, int row, String text) {
        this(side, row, 0, ItemGrid.COLUMNS - 1, text, TextAlign.LEFT, false, false);
    }

    public LayoutLabel(BankSide side, int row, int fromColumn, int toColumn, String text, TextAlign align, boolean header, boolean underlined) {
        this.side = Objects.requireNonNull(side, "side");
        if (row < 0) {
            throw new IllegalArgumentException("Row must not be negative, got " + row);
        }
        if (fromColumn < 0 || toColumn >= ItemGrid.COLUMNS || fromColumn > toColumn) {
            throw new IllegalArgumentException("Columns must run left to right within a side, got " + fromColumn + " to " + toColumn);
        }
        this.row = row;
        this.fromColumn = fromColumn;
        this.toColumn = toColumn;
        this.text = Objects.requireNonNull(text, "text");
        this.align = Objects.requireNonNull(align, "align");
        this.header = header;
        this.underlined = underlined;
    }

    /** A divider in the header strip of the row it heads. */
    public static LayoutLabel header(BankSide side, int row, int fromColumn, int toColumn, String text, TextAlign align, boolean underlined) {
        return new LayoutLabel(side, row, fromColumn, toColumn, text, align, true, underlined);
    }

    public int width() {
        return toColumn - fromColumn + 1;
    }

}

package dev.dutchy.runelite.gear.persistence;

import dev.dutchy.runelite.gear.GearSection;
import dev.dutchy.runelite.gear.GearSetupBook;
import dev.dutchy.runelite.gear.GearSetupBookListener;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.time.Duration;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

/** Writes the book a moment after it last changed, and immediately on {@link #flush()}. */
public final class AutoSave implements GearSetupBookListener {

    private static final Logger log = LoggerFactory.getLogger(AutoSave.class);

    private final BookStore store;
    private final BookCodec codec;
    private final ScheduledExecutorService scheduler;
    private final Duration delay;
    private final AtomicReference<List<GearSection>> pending = new AtomicReference<>();
    private final Object lock = new Object();

    private ScheduledFuture<?> scheduled;
    private GearSetupBook watched;

    public AutoSave(BookStore store, BookCodec codec, ScheduledExecutorService scheduler, Duration delay) {
        this.store = Objects.requireNonNull(store, "store");
        this.codec = Objects.requireNonNull(codec, "codec");
        this.scheduler = Objects.requireNonNull(scheduler, "scheduler");
        this.delay = Objects.requireNonNull(delay, "delay");
        if (delay.isNegative()) {
            throw new IllegalArgumentException("Delay must not be negative");
        }
    }

    public void watch(GearSetupBook book) {
        Objects.requireNonNull(book, "book");
        synchronized (lock) {
            if (watched != null) {
                throw new IllegalStateException("Already watching a book");
            }
            watched = book;
        }
        book.addChangeListener(this);
    }

    /**
     * Stops listening at once and hands any last write to the scheduler. The write does not happen
     * on the calling thread: this runs from the plugin's shutdown, which is the client thread, and
     * a write reaches the disk through the backup store. The scheduler is single threaded, so the
     * write still lands before anything a restart reads.
     */
    public void stop() {
        GearSetupBook book;
        synchronized (lock) {
            book = watched;
            watched = null;
        }
        if (book != null) {
            book.removeChangeListener(this);
        }
        synchronized (lock) {
            if (scheduled != null) {
                scheduled.cancel(false);
                scheduled = null;
            }
            if (pending.get() != null) {
                scheduled = scheduler.schedule(this::flush, 0, TimeUnit.MILLISECONDS);
            }
        }
    }

    @Override
    public void onBookChanged(GearSetupBook book) {
        pending.set(book.sections());
        synchronized (lock) {
            if (scheduled != null) {
                scheduled.cancel(false);
            }
            scheduled = scheduler.schedule(this::flush, delay.toMillis(), TimeUnit.MILLISECONDS);
        }
    }

    /** Writes whatever is waiting, now, on the calling thread. */
    public void flush() {
        synchronized (lock) {
            if (scheduled != null) {
                scheduled.cancel(false);
                scheduled = null;
            }
        }
        List<GearSection> sections = pending.getAndSet(null);
        if (sections == null) {
            return;
        }
        try {
            store.write(codec.encode(sections));
        } catch (RuntimeException e) {
            log.warn("Could not save gear setups", e);
            pending.compareAndSet(null, sections);
        }
    }

    public boolean hasUnsavedChanges() {
        return pending.get() != null;
    }
}

