import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Duration;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.ScheduledExecutorService;

/** Restores the book at start-up and keeps it saved afterwards. */
@Singleton
public final class BookPersistence {

    static final Duration SAVE_DELAY = Duration.ofMillis(500);

    private static final Logger log = LoggerFactory.getLogger(BookPersistence.class);

    private final BookStore store;
    private final BookCodec codec;
    private final ScheduledExecutorService scheduler;

    @Inject
    public BookPersistence(BookStore store, BookCodec codec, ScheduledExecutorService scheduler) {
        this.store = Objects.requireNonNull(store, "store");
        this.codec = Objects.requireNonNull(codec, "codec");
        this.scheduler = Objects.requireNonNull(scheduler, "scheduler");
    }

    /** Fills the book from storage. An unreadable document is quarantined and the book is left as it was. */
    public boolean restore(GearSetupBook book) {
        Objects.requireNonNull(book, "book");
        Optional<String> stored = store.read();
        if (stored.isEmpty()) {
            return false;
        }
        List<GearSection> sections;
        try {
            sections = codec.decode(stored.get());
        } catch (BookFormatException e) {
            log.warn("Stored gear setups could not be read and were set aside", e);
            store.quarantine(stored.get());
            return false;
        }
        if (sections.isEmpty()) {
            return false;
        }
        book.replaceSections(sections);
        return true;
    }

    /** Saves the book shortly after every change until {@link AutoSave#stop()} is called. */
    public AutoSave autoSave(GearSetupBook book) {
        AutoSave autoSave = new AutoSave(store, codec, scheduler, SAVE_DELAY);
        autoSave.watch(book);
        return autoSave;
    }
}

package dev.dutchy.runelite.gear.persistence;

import java.util.Optional;

/** Where the encoded book lives. Implementations must be safe to call from any thread. */
public interface BookStore {

    Optional<String> read();

    void write(String encoded);

    /** Sets aside an unreadable document so a later save cannot destroy it. */
    void quarantine(String encoded);
}

package dev.dutchy.runelite.gear.persistence;

import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Clock;
import java.util.Objects;
import java.util.Optional;

/** Keeps the book in RuneLite's configuration, which follows the player's RuneLite account. */
@Singleton
public final class ConfigBookStore implements BookStore {

    static final String GROUP = "gearcomposer";
    static final String KEY = "book";
    static final String QUARANTINE_PREFIX = "book.unreadable.";

    private final ConfigManager configManager;
    private final Clock clock;

    @Inject
    public ConfigBookStore(ConfigManager configManager) {
        this(configManager, Clock.systemUTC());
    }

    ConfigBookStore(ConfigManager configManager, Clock clock) {
        this.configManager = Objects.requireNonNull(configManager, "configManager");
        this.clock = Objects.requireNonNull(clock, "clock");
    }

    @Override
    public Optional<String> read() {
        String value = configManager.getConfiguration(GROUP, KEY);
        return value == null || value.isBlank() ? Optional.empty() : Optional.of(value);
    }

    @Override
    public void write(String encoded) {
        configManager.setConfiguration(GROUP, KEY, Objects.requireNonNull(encoded, "encoded"));
    }

    @Override
    public void quarantine(String encoded) {
        configManager.setConfiguration(GROUP, QUARANTINE_PREFIX + clock.millis(), Objects.requireNonNull(encoded, "encoded"));
    }
}

package dev.dutchy.runelite.gear.persistence;

import com.google.gson.TypeAdapter;
import com.google.gson.annotations.JsonAdapter;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;
import dev.dutchy.runelite.gear.content.*;
import dev.dutchy.runelite.libs.ui.item.ItemId;

import java.io.IOException;

import java.util.*;
import java.util.stream.Collectors;

/** Maps setup contents to and from plain transfer objects shared by every JSON document. */
public final class ContentCodec {

    private ContentCodec() {
    }

    public static class ContentDto {
        String type;
        Map<String, ItemDto> equipment;
        Map<String, ItemDto> inventory;
        Map<String, ItemDto> left;
        Map<String, ItemDto> right;
        @JsonAdapter(DividerListAdapter.class)
        List<DividerDto> inventoryDividers;
        @JsonAdapter(DividerListAdapter.class)
        List<DividerDto> leftDividers;
        @JsonAdapter(DividerListAdapter.class)
        List<DividerDto> rightDividers;
        Integer rows;
        List<CellDto> cells;
    }

    public static final class CellDto {
        String kind;
        String name;
        Map<String, ItemDto> equipment;
        Map<String, ItemDto> items;
        @JsonAdapter(DividerListAdapter.class)
        List<DividerDto> dividers;
    }

    public static final class DividerDto {
        int row;
        Integer from;
        Integer to;
        String label;
        String align;
        Boolean line;
    }

    /** Reads dividers as the list they are now, or as the row-to-label map older books wrote, and writes the list. */
    public static final class DividerListAdapter extends TypeAdapter<List<DividerDto>> {

        @Override
        public void write(JsonWriter out, List<DividerDto> dividers) throws IOException {
            if (dividers == null) {
                out.nullValue();
                return;
            }
            out.beginArray();
            for (DividerDto divider : dividers) {
                out.beginObject();
                out.name("row").value(divider.row);
                if (divider.from != null) {
                    out.name("from").value(divider.from);
                }
                if (divider.to != null) {
                    out.name("to").value(divider.to);
                }
                out.name("label").value(divider.label);
                if (divider.align != null) {
                    out.name("align").value(divider.align);
                }
                if (divider.line != null) {
                    out.name("line").value(divider.line);
                }
                out.endObject();
            }
            out.endArray();
        }

        @Override
        public List<DividerDto> read(JsonReader in) throws IOException {
            List<DividerDto> dividers = new ArrayList<>();
            if (in.peek() == JsonToken.NULL) {
                in.nextNull();
                return null;
            }
            if (in.peek() == JsonToken.BEGIN_OBJECT) {
                in.beginObject();
                while (in.hasNext()) {
                    DividerDto divider = new DividerDto();
                    divider.row = Integer.parseInt(in.nextName());
                    divider.label = in.nextString();
                    dividers.add(divider);
                }
                in.endObject();
                return dividers;
            }
            in.beginArray();
            while (in.hasNext()) {
                DividerDto divider = new DividerDto();
                in.beginObject();
                while (in.hasNext()) {
                    String name = in.nextName();
                    switch (name) {
                        case "row":
                            divider.row = in.nextInt();
                            break;
                        case "from":
                            divider.from = in.nextInt();
                            break;
                        case "to":
                            divider.to = in.nextInt();
                            break;
                        case "label":
                            divider.label = in.nextString();
                            break;
                        case "align":
                            divider.align = in.nextString();
                            break;
                        case "line":
                            divider.line = in.nextBoolean();
                            break;
                        default:
                            in.skipValue();
                    }
                }
                in.endObject();
                dividers.add(divider);
            }
            in.endArray();
            return dividers;
        }
    }

    public static final class ItemDto {
        int id;
        Integer qty;
        String match;
        List<Integer> alts;
        Boolean noted;
    }

    public static ContentDto toDto(SetupContent content) {
        return write(content, new ContentDto());
    }

    /** Fills the document's content fields, leaving any others alone. */
    public static <D extends ContentDto> D write(SetupContent content, D dto) {
        dto.type = content.type().name();
        if (content instanceof GearContent) {
            GearContent gear = (GearContent) content;
            dto.equipment = new LinkedHashMap<>();
            gear.equipment().forEach((slot, item) -> dto.equipment.put(slot.name(), toDto(item)));
            dto.inventory = toDto(gear.inventory());
            dto.inventoryDividers = dividersOf(gear.inventory());
        } else if (content instanceof BankContent) {
            BankContent bank = (BankContent) content;
            dto.left = toDto(bank.left());
            dto.right = toDto(bank.right());
            dto.leftDividers = dividersOf(bank.left());
            dto.rightDividers = dividersOf(bank.right());
        } else if (content instanceof CustomContent) {
            CustomContent custom = (CustomContent) content;
            dto.rows = custom.rows();
            dto.cells = custom.cells().stream().map(ContentCodec::toDto).collect(Collectors.toList());
        }
        return dto;
    }

    public static SetupContent fromDto(ContentDto dto) {
        Objects.requireNonNull(dto, "content");
        SetupType type = SetupType.valueOf(require(dto.type, "setup type"));
        switch (type) {
            case GEAR:
                return new GearContent(equipmentFrom(dto.equipment), gridFrom(dto.inventory, dto.inventoryDividers));
            case BANK:
                return new BankContent(gridFrom(dto.left, dto.leftDividers), gridFrom(dto.right, dto.rightDividers));
            default:
                return customFrom(dto);
        }
    }

    private static Map<EquipmentSlot, SetupItem> equipmentFrom(Map<String, ItemDto> dto) {
        Map<EquipmentSlot, SetupItem> equipment = new EnumMap<>(EquipmentSlot.class);
        if (dto != null) {
            dto.forEach((slot, item) -> equipment.put(EquipmentSlot.valueOf(slot), fromDto(item)));
        }
        return equipment;
    }

    private static CellDto toDto(LayoutCell cell) {
        CellDto dto = new CellDto();
        dto.kind = cell.kind().name();
        dto.name = cell.name().orElse(null);
        if (cell.kind() == CellKind.EQUIPMENT) {
            dto.equipment = new LinkedHashMap<>();
            cell.equipment().forEach((slot, item) -> dto.equipment.put(slot.name(), toDto(item)));
        } else if (cell.kind() == CellKind.INVENTORY) {
            dto.items = toDto(cell.inventory());
            dto.dividers = dividersOf(cell.inventory());
        }
        return dto;
    }

    private static CustomContent customFrom(ContentDto dto) {
        if (dto.rows == null) {
            throw new IllegalArgumentException("Missing row count");
        }
        List<LayoutCell> cells = new ArrayList<>();
        if (dto.cells != null) {
            for (CellDto cell : dto.cells) {
                CellKind kind = CellKind.valueOf(require(cell.kind, "cell kind"));
                cells.add(new LayoutCell(kind, cell.name, equipmentFrom(cell.equipment), gridFrom(cell.items, cell.dividers)));
            }
        }
        return new CustomContent(dto.rows, cells);
    }

    private static Map<String, ItemDto> toDto(ItemGrid grid) {
        Map<String, ItemDto> slots = new LinkedHashMap<>();
        for (int index = 0; index < ItemGrid.SIZE; index++) {
            String key = String.valueOf(index);
            grid.slot(index).ifPresent(item -> slots.put(key, toDto(item)));
        }
        return slots;
    }

    private static List<DividerDto> dividersOf(ItemGrid grid) {
        if (grid.dividers().isEmpty()) {
            return null;
        }
        List<DividerDto> dividers = new ArrayList<>();
        for (Divider divider : grid.dividers()) {
            DividerDto dto = new DividerDto();
            dto.row = divider.row();
            dto.from = divider.spansWholeRow() ? null : divider.fromColumn();
            dto.to = divider.spansWholeRow() ? null : divider.toColumn();
            dto.label = divider.label();
            dto.align = divider.align() == TextAlign.DEFAULT ? null : divider.align().name();
            dto.line = divider.underlined() ? null : Boolean.FALSE;
            dividers.add(dto);
        }
        return dividers;
    }

    private static ItemGrid gridFrom(Map<String, ItemDto> dto, List<DividerDto> dividerDto) {
        Map<Integer, SetupItem> slots = new LinkedHashMap<>();
        if (dto != null) {
            dto.forEach((index, item) -> slots.put(Integer.parseInt(index), fromDto(item)));
        }
        List<Divider> dividers = new ArrayList<>();
        if (dividerDto != null) {
            for (DividerDto divider : dividerDto) {
                dividers.add(new Divider(divider.row, divider.from == null ? 0 : divider.from, divider.to == null ? ItemGrid.COLUMNS - 1 : divider.to,
                        require(divider.label, "divider label"), divider.align == null ? TextAlign.DEFAULT : TextAlign.valueOf(divider.align),
                        divider.line == null || divider.line));
            }
        }
        return ItemGrid.of(slots, dividers);
    }

    static ItemDto toDto(SetupItem item) {
        ItemDto dto = new ItemDto();
        dto.id = item.id().value();
        dto.qty = item.quantity().isPresent() ? item.quantity().getAsInt() : null;
        dto.match = item.match() == ItemMatch.DEFAULT ? null : item.match().name();
        dto.alts = item.alternatives().isEmpty() ? null : item.alternatives().stream().map(ItemId::value).collect(Collectors.toList());
        dto.noted = item.noted() ? Boolean.TRUE : null;
        return dto;
    }

    static SetupItem fromDto(ItemDto dto) {
        Objects.requireNonNull(dto, "item");
        ItemMatch match = dto.match == null ? ItemMatch.DEFAULT : ItemMatch.valueOf(dto.match);
        List<ItemId> alternatives = dto.alts == null ? List.of() : dto.alts.stream().map(ItemId::of).collect(Collectors.toList());
        SetupItem item = new SetupItem(ItemId.of(dto.id), SetupItem.BANK_AMOUNT, match, alternatives, Boolean.TRUE.equals(dto.noted));
        return dto.qty == null ? item : item.withQuantity(dto.qty);
    }

    static String require(String value, String what) {
        if (value == null) {
            throw new IllegalArgumentException("Missing " + what);
        }
        return value;
    }
}

package dev.dutchy.runelite.gear.persistence;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.*;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/** Backups as {@code book-<timestamp>.json} files in one directory, thinned by a {@link BackupRotation}. */
public final class FileBackupStore implements BackupStore {

    private static final Logger log = LoggerFactory.getLogger(FileBackupStore.class);
    private static final String PREFIX = "book-";
    private static final String SUFFIX = ".json";
    private static final DateTimeFormatter STAMP = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss-SSS").withZone(ZoneOffset.UTC);

    private final Path directory;
    private final BackupRotation rotation;
    private final Clock clock;

    public FileBackupStore(Path directory, BackupRotation rotation, Clock clock) {
        this.directory = Objects.requireNonNull(directory, "directory");
        this.rotation = Objects.requireNonNull(rotation, "rotation");
        this.clock = Objects.requireNonNull(clock, "clock");
    }

    @Override
    public void save(String encoded) {
        Objects.requireNonNull(encoded, "encoded");
        Instant now = clock.instant();
        try {
            Files.createDirectories(directory);
            Path temporary = Files.createTempFile(directory, "backup", ".tmp");
            Files.writeString(temporary, encoded, StandardCharsets.UTF_8);
            Files.move(temporary, fileFor(now), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
            rotate(now);
        } catch (IOException e) {
            log.warn("Backup could not be written", e);
        }
    }

    @Override
    public List<Backup> list() {
        if (!Files.isDirectory(directory)) {
            return List.of();
        }
        try (Stream<Path> files = Files.list(directory)) {
            List<Backup> backups = new ArrayList<>();
            files.forEach(file -> parse(file).ifPresent(at -> backups.add(new Backup(file, at))));
            backups.sort(Comparator.comparing(Backup::at).reversed());
            return List.copyOf(backups);
        } catch (IOException e) {
            log.warn("Backups could not be listed", e);
            return List.of();
        }
    }

    @Override
    public String read(Backup backup) {
        try {
            return Files.readString(Objects.requireNonNull(backup, "backup").file(), StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private void rotate(Instant now) {
        List<Backup> backups = list();
        Set<Instant> kept = rotation.keep(backups.stream().map(Backup::at).collect(Collectors.toList()), now);
        for (Backup backup : backups) {
            if (!kept.contains(backup.at())) {
                try {
                    Files.deleteIfExists(backup.file());
                } catch (IOException e) {
                    log.warn("Old backup {} could not be removed", backup.file(), e);
                }
            }
        }
    }

    private Path fileFor(Instant at) {
        return directory.resolve(PREFIX + STAMP.format(at) + SUFFIX);
    }

    private static Optional<Instant> parse(Path file) {
        String name = file.getFileName().toString();
        if (!name.startsWith(PREFIX) || !name.endsWith(SUFFIX)) {
            return Optional.empty();
        }
        String stamp = name.substring(PREFIX.length(), name.length() - SUFFIX.length());
        try {
            return Optional.of(Instant.from(STAMP.parse(stamp)));
        } catch (DateTimeParseException e) {
            return Optional.empty();
        }
    }
}

package dev.dutchy.runelite.gear.persistence;

import dev.dutchy.runelite.gear.*;
import dev.dutchy.runelite.gear.content.SetupVariant;
import dev.dutchy.runelite.libs.ui.item.ItemId;

import java.util.*;
import java.util.stream.Collectors;

/**
 * One setup as a flat JSON document: name, icon, the selected variant's contents at the top level, every variant
 * when there is more than one, and the meta that travels with it. Pins, hotkeys, ids and ownership are personal
 * to a book, so documents that need them extend this one.
 */
public class SetupDocument extends ContentCodec.ContentDto {
    String name;
    Integer icon;
    List<VariantDto> variants;
    Integer variant;
    String label;
    List<String> tags;
    String notes;
    String spellbook;
    List<String> quickPrayers;

    public SetupDocument() {
    }

    public static final class VariantDto extends ContentCodec.ContentDto {
        String name;
    }

    /** Fills the document from the setup, leaving fields a subclass adds alone. */
    public static <D extends SetupDocument> D write(GearSetup setup, D document) {
        Objects.requireNonNull(setup, "setup");
        ContentCodec.write(setup.content(), document);
        document.name = setup.name();
        document.icon = setup.icon().map(ItemId::value).orElse(null);
        if (setup.hasVariants()) {
            document.variants = setup.variants().stream().map(SetupDocument::toDto).collect(Collectors.toList());
            document.variant = setup.selectedIndex();
        }
        SetupMeta meta = setup.meta();
        document.label = meta.label().isNone() ? null : meta.label().name();
        document.tags = meta.tags().isEmpty() ? null : List.copyOf(meta.tags());
        document.notes = meta.hasNotes() ? meta.notes() : null;
        document.spellbook = meta.requirements().spellbook().isRequirement() ? meta.requirements().spellbook().name() : null;
        document.quickPrayers = meta.requirements().hasQuickPrayers()
                ? meta.requirements().quickPrayers().stream().sorted().map(Prayer::name).collect(Collectors.toList()) : null;
        return document;
    }

    public boolean hasName() {
        return name != null;
    }

    /** Copies content fields from an older document that nested them under their own object. */
    public void adoptContent(ContentCodec.ContentDto content) {
        type = content.type;
        equipment = content.equipment;
        inventory = content.inventory;
        left = content.left;
        right = content.right;
        inventoryDividers = content.inventoryDividers;
        leftDividers = content.leftDividers;
        rightDividers = content.rightDividers;
        rows = content.rows;
        cells = content.cells;
    }

    /** A fresh setup under a new id; the caller adds whatever personal fields it keeps. */
    public GearSetup toSetup() {
        GearSetup setup = GearSetup.named(ContentCodec.require(name, "setup name"));
        if (variants == null || variants.isEmpty()) {
            setup = setup.withContent(ContentCodec.fromDto(this));
        } else {
            List<SetupVariant> read = new ArrayList<>();
            for (VariantDto dto : variants) {
                read.add(new SetupVariant(ContentCodec.require(dto.name, "variant name"), ContentCodec.fromDto(dto)));
            }
            setup = setup.withVariants(read, variant == null ? 0 : variant);
        }
        if (icon != null) {
            setup = setup.withIcon(ItemId.of(icon));
        }
        return setup.withMeta(meta());
    }

    /** The shared part of the meta; personal flags are left at their defaults. */
    public SetupMeta meta() {
        Requirements requirements = new Requirements(spellbook == null ? Spellbook.ANY : Spellbook.valueOf(spellbook), prayersFrom(quickPrayers));
        return SetupMeta.none()
                .withLabel(label == null ? ColourLabel.NONE : ColourLabel.valueOf(label))
                .withTags(tags == null ? Set.of() : new HashSet<>(tags))
                .withNotes(notes == null ? "" : notes)
                .withRequirements(requirements);
    }

    public static Set<Prayer> prayersFrom(List<String> names) {
        if (names == null || names.isEmpty()) {
            return Set.of();
        }
        Set<Prayer> prayers = EnumSet.noneOf(Prayer.class);
        names.forEach(name -> prayers.add(Prayer.valueOf(name)));
        return prayers;
    }

    private static VariantDto toDto(SetupVariant variant) {
        VariantDto dto = ContentCodec.write(variant.content(), new VariantDto());
        dto.name = variant.name();
        return dto;
    }
}

package dev.dutchy.runelite.gear.player;

import dev.dutchy.runelite.gear.content.Loadout;

import java.util.function.Consumer;

/** Reads what the player is wearing and carrying. Both callbacks run on the EDT; only one of them runs. */
@FunctionalInterface
public interface PlayerItems {

    void capture(Consumer<Loadout> onCaptured, Runnable onUnavailable);
}

package dev.dutchy.runelite.gear.player;

import dev.dutchy.runelite.gear.content.EquipmentSlot;
import dev.dutchy.runelite.gear.content.EquipmentSlots;
import dev.dutchy.runelite.libs.ui.item.ItemId;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

/**
 * Reads worn slots from RuneLite's item statistics. The lookup needs the client thread, so answers
 * are cached and an unknown item is looked up in the background and reported as unknown meanwhile.
 */
@Singleton
public final class RuneLiteEquipmentSlots implements EquipmentSlots {

    private final ItemManager itemManager;
    private final ClientThread clientThread;
    private final Map<ItemId, Optional<EquipmentSlot>> known = new ConcurrentHashMap<>();

    @Inject
    public RuneLiteEquipmentSlots(ItemManager itemManager, ClientThread clientThread) {
        this.itemManager = Objects.requireNonNull(itemManager, "itemManager");
        this.clientThread = Objects.requireNonNull(clientThread, "clientThread");
    }

    @Override
    public Optional<EquipmentSlot> slotOf(ItemId item) {
        Objects.requireNonNull(item, "item");
        Optional<EquipmentSlot> cached = known.get(item);
        if (cached != null) {
            return cached;
        }
        warmUp(List.of(item));
        return Optional.empty();
    }

    @Override
    public void warmUp(Collection<ItemId> items) {
        List<ItemId> missing = items.stream().filter(item -> !known.containsKey(item)).distinct().collect(Collectors.toList());
        if (missing.isEmpty()) {
            return;
        }
        clientThread.invoke(() -> missing.forEach(item -> known.put(item, lookUp(item))));
    }

    /** Must run on the client thread. */
    private Optional<EquipmentSlot> lookUp(ItemId item) {
        ItemStats stats = itemManager.getItemStats(item.value());
        if (stats == null || !stats.isEquipable() || stats.getEquipment() == null) {
            return Optional.empty();
        }
        return WornSlots.fromIndex(stats.getEquipment().getSlot());
    }
}

package dev.dutchy.runelite.gear.player;

import dev.dutchy.runelite.gear.content.EquipmentSlot;
import dev.dutchy.runelite.gear.content.ItemGrid;
import dev.dutchy.runelite.gear.content.Loadout;
import dev.dutchy.runelite.gear.content.SetupItem;
import dev.dutchy.runelite.gear.items.ItemNotes;
import dev.dutchy.runelite.libs.ui.item.ItemId;
import dev.dutchy.runelite.libs.ui.swing.EdtDispatch;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.function.Consumer;

@Singleton
public final class RuneLitePlayerItems implements PlayerItems {

    private final Client client;
    private final ClientThread clientThread;
    private final ItemNotes notes;

    @Inject
    public RuneLitePlayerItems(Client client, ClientThread clientThread, ItemNotes notes) {
        this.client = Objects.requireNonNull(client, "client");
        this.clientThread = Objects.requireNonNull(clientThread, "clientThread");
        this.notes = Objects.requireNonNull(notes, "notes");
    }

    @Override
    public void capture(Consumer<Loadout> onCaptured, Runnable onUnavailable) {
        Objects.requireNonNull(onCaptured, "onCaptured");
        Objects.requireNonNull(onUnavailable, "onUnavailable");
        clientThread.invoke(() -> {
            Optional<Loadout> loadout = read();
            EdtDispatch.onEdt(() -> loadout.ifPresentOrElse(onCaptured, onUnavailable));
        });
    }

    private Optional<Loadout> read() {
        if (client.getGameState() != GameState.LOGGED_IN) {
            return Optional.empty();
        }
        return Optional.of(new Loadout(
                equipment(client.getItemContainer(InventoryID.WORN)),
                inventory(client.getItemContainer(InventoryID.INV))));
    }

    private Map<EquipmentSlot, SetupItem> equipment(ItemContainer worn) {
        Map<EquipmentSlot, SetupItem> equipment = new EnumMap<>(EquipmentSlot.class);
        if (worn == null) {
            return equipment;
        }
        for (EquipmentSlot slot : EquipmentSlot.values()) {
            setupItem(worn.getItem(WornSlots.indexOf(slot))).ifPresent(item -> equipment.put(slot, item));
        }
        return equipment;
    }

    private ItemGrid inventory(ItemContainer carried) {
        Map<Integer, SetupItem> slots = new LinkedHashMap<>();
        if (carried == null) {
            return ItemGrid.EMPTY;
        }
        for (int index = 0; index < ItemGrid.SIZE; index++) {
            int slotIndex = index;
            setupItem(carried.getItem(index)).ifPresent(item -> slots.put(slotIndex, item));
        }
        return ItemGrid.of(slots);
    }

    /** A carried note is recorded as the real item, flagged to be withdrawn as a note. */
    private Optional<SetupItem> setupItem(Item item) {
        if (item == null || item.getId() < 0 || item.getQuantity() < SetupItem.MIN_QUANTITY) {
            return Optional.empty();
        }
        ItemId id = ItemId.of(item.getId());
        Optional<ItemId> unnoted = notes.unnotedOf(id);
        SetupItem setupItem = SetupItem.of(unnoted.orElse(id).value(), item.getQuantity());
        return Optional.of(unnoted.isPresent() ? setupItem.withNoted(true) : setupItem);
    }
}

package dev.dutchy.runelite.gear.player;

import dev.dutchy.runelite.gear.content.EquipmentSlot;
import net.runelite.api.EquipmentInventorySlot;

import java.util.Map;
import java.util.Optional;

/** How the game's worn-equipment container indices line up with the plugin's equipment slots. */
public final class WornSlots {

    private static final Map<EquipmentSlot, EquipmentInventorySlot> BY_SLOT = Map.ofEntries(
            Map.entry(EquipmentSlot.HEAD, EquipmentInventorySlot.HEAD),
            Map.entry(EquipmentSlot.CAPE, EquipmentInventorySlot.CAPE),
            Map.entry(EquipmentSlot.AMULET, EquipmentInventorySlot.AMULET),
            Map.entry(EquipmentSlot.AMMUNITION, EquipmentInventorySlot.AMMO),
            Map.entry(EquipmentSlot.WEAPON, EquipmentInventorySlot.WEAPON),
            Map.entry(EquipmentSlot.BODY, EquipmentInventorySlot.BODY),
            Map.entry(EquipmentSlot.SHIELD, EquipmentInventorySlot.SHIELD),
            Map.entry(EquipmentSlot.LEGS, EquipmentInventorySlot.LEGS),
            Map.entry(EquipmentSlot.HANDS, EquipmentInventorySlot.GLOVES),
            Map.entry(EquipmentSlot.FEET, EquipmentInventorySlot.BOOTS),
            Map.entry(EquipmentSlot.RING, EquipmentInventorySlot.RING));

    private WornSlots() {
    }

    public static int indexOf(EquipmentSlot slot) {
        return BY_SLOT.get(slot).getSlotIdx();
    }

    public static Optional<EquipmentSlot> fromIndex(int index) {
        return BY_SLOT.entrySet().stream()
                .filter(entry -> entry.getValue().getSlotIdx() == index)
                .map(Map.Entry::getKey)
                .findFirst();
    }
}

