public interface FileDialogs {

    Optional<Path> chooseFileToOpen();

    Optional<Path> chooseFileToSave(String suggestedName);
}

package dev.dutchy.runelite.gear.transfer;

import dev.dutchy.runelite.gear.persistence.BookFiles;

import javax.swing.*;
import javax.swing.filechooser.FileNameExtensionFilter;
import java.awt.*;
import java.io.File;
import java.nio.file.Path;
import java.util.Objects;
import java.util.Optional;

public final class SwingFileDialogs implements FileDialogs {

    private final Component parent;
    private final File startIn;

    public SwingFileDialogs(Component parent, File startIn) {
        this.parent = parent;
        this.startIn = Objects.requireNonNull(startIn, "startIn");
    }

    @Override
    public Optional<Path> chooseFileToOpen() {
        JFileChooser chooser = chooser("Import setups");
        return chooser.showOpenDialog(parent) == JFileChooser.APPROVE_OPTION
                ? Optional.of(chooser.getSelectedFile().toPath())
                : Optional.empty();
    }

    @Override
    public Optional<Path> chooseFileToSave(String suggestedName) {
        JFileChooser chooser = chooser("Export setups");
        chooser.setSelectedFile(new File(startIn, suggestedName));
        if (chooser.showSaveDialog(parent) != JFileChooser.APPROVE_OPTION) {
            return Optional.empty();
        }
        File chosen = chooser.getSelectedFile();
        if (!chosen.getName().toLowerCase().endsWith("." + BookFiles.EXTENSION)) {
            chosen = new File(chosen.getParentFile(), chosen.getName() + "." + BookFiles.EXTENSION);
        }
        return Optional.of(chosen.toPath());
    }

    private JFileChooser chooser(String title) {
        JFileChooser chooser = new JFileChooser(startIn);
        chooser.setDialogTitle(title);
        chooser.setFileFilter(new FileNameExtensionFilter("Gear Composer setups (*.json)", BookFiles.EXTENSION));
        return chooser;
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.Owner;
import dev.dutchy.runelite.gear.content.CellKind;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;
import java.util.Locale;
import java.util.Objects;

/** A coloured circle with the account's initial; the colour comes from the key, so an account always looks the same. */
final class AccountBadge extends JComponent {

    static final int SIZE = 28;

    private final Owner owner;
    private final String initial;

    AccountBadge(Owner owner, String name) {
        this.owner = Objects.requireNonNull(owner, "owner");
        this.initial = name.isBlank() ? "?" : name.substring(0, 1).toUpperCase(Locale.ROOT);
        setPreferredSize(new Dimension(SIZE, SIZE));
        setMinimumSize(new Dimension(SIZE, SIZE));
        setMaximumSize(new Dimension(SIZE, SIZE));
        setOpaque(false);
    }

    static Color colourFor(Owner owner) {
        if (owner.isShared()) {
            return ColorScheme.BRAND_ORANGE;
        }
        int hue = Math.floorMod(owner.account().orElse("").hashCode(), 360);
        return Color.getHSBColor(hue / 360f, 0.45f, 0.75f);
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        try {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(colourFor(owner));
            g2.fillOval(0, 0, SIZE - 1, SIZE - 1);
            if (owner.isShared()) {
                g2.setColor(new Color(30, 30, 30));
                CellGlyphs.paint(g2, CellKind.INVENTORY, 8, 7, 12, 14);
                return;
            }
            g2.setFont(FontManager.getRunescapeBoldFont());
            g2.setColor(new Color(30, 30, 30));
            FontMetrics metrics = g2.getFontMetrics();
            g2.drawString(initial, (SIZE - metrics.stringWidth(initial)) / 2, (SIZE + metrics.getAscent() - metrics.getDescent()) / 2);
        } finally {
            g2.dispose();
        }
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.account.AccountEntry;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Objects;
import java.util.function.Consumer;

/** One account on the accounts screen: badge over name, short id and setup count; click opens its list, right-click for more. */
final class AccountCardView extends Card {

    static final int HEIGHT = 96;
    static final String OPEN = "Open";
    static final String FORGET = "Forget account";

    private final AccountEntry entry;
    private final Consumer<AccountEntry> onOpen;
    private final Consumer<AccountEntry> onForget;
    private boolean hovered;

    AccountCardView(AccountEntry entry, Consumer<AccountEntry> onOpen, Consumer<AccountEntry> onForget) {
        this.entry = Objects.requireNonNull(entry, "entry");
        this.onOpen = Objects.requireNonNull(onOpen, "onOpen");
        this.onForget = Objects.requireNonNull(onForget, "onForget");
        setLayout(new BorderLayout(0, 4));
        setBorder(BorderFactory.createEmptyBorder(8, 6, 8, 6));
        setPreferredSize(new Dimension(0, HEIGHT));
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        setToolTipText(entry.isShared() ? "Setups every account can use" : entry.name() + " · " + entry.shortId()
                + (entry.canForget() ? ". Right-click to forget." : ""));

        JPanel badge = Ui.panel(new FlowLayout(FlowLayout.CENTER, 0, 0));
        badge.add(new AccountBadge(entry.owner(), entry.name()));

        JLabel name = new JLabel(entry.isShared() ? "Shared" : entry.name(), SwingConstants.CENTER);
        name.setFont(FontManager.getRunescapeBoldFont());
        name.setForeground(ColorScheme.TEXT_COLOR);
        JLabel detail = Ui.hint(entry.isShared() ? "all accounts" : entry.shortId() + (entry.loggedIn() ? " · here" : ""));
        detail.setHorizontalAlignment(SwingConstants.CENTER);
        JLabel count = Ui.body(entry.setupCount() == 1 ? "1 setup" : entry.setupCount() + " setups");
        count.setHorizontalAlignment(SwingConstants.CENTER);

        JPanel text = Ui.column(0, name, detail, count);
        add(badge, BorderLayout.NORTH);
        add(text, BorderLayout.CENTER);

        MouseAdapter mouse = new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                if (SwingUtilities.isLeftMouseButton(e)) {
                    onOpen.accept(entry);
                }
            }

            @Override
            public void mousePressed(MouseEvent e) {
                maybeShowMenu(e);
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                maybeShowMenu(e);
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                hovered = true;
                refresh();
            }

            @Override
            public void mouseExited(MouseEvent e) {
                hovered = false;
                refresh();
            }
        };
        addMouseListener(mouse);
        refresh();
    }

    AccountEntry entry() {
        return entry;
    }

    ContextMenu contextMenu() {
        ContextMenu menu = new ContextMenu().item(ActionIcon.GRID, OPEN, () -> onOpen.accept(entry));
        if (entry.canForget()) {
            menu.divider().danger(FORGET, () -> onForget.accept(entry));
        }
        return menu;
    }

    private void maybeShowMenu(MouseEvent e) {
        if (e.isPopupTrigger() && !entry.isShared()) {
            contextMenu().show(e.getComponent(), e.getX(), e.getY());
        }
    }

    private void refresh() {
        setBackground(hovered ? Ui.SURFACE_HOVER : Ui.SURFACE);
        setOutline(entry.loggedIn() ? ColorScheme.BRAND_ORANGE : Ui.OUTLINE);
        repaint();
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.GearSetup;
import dev.dutchy.runelite.gear.GearSetupBook;
import dev.dutchy.runelite.gear.Owner;
import dev.dutchy.runelite.gear.account.AccountDirectory;
import dev.dutchy.runelite.gear.account.AccountEntry;
import dev.dutchy.runelite.gear.account.AccountRoster;
import dev.dutchy.runelite.gear.account.CurrentAccount;

import javax.inject.Inject;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

/**
 * Whose setups are on show, and who each setup belongs to. The logged-in character's name is
 * remembered as soon as it is known, so their setups still read as theirs when they are logged out.
 */
public final class Accounts {

    /** What the sidebar does when who is logged in, or what they are called, changes. */
    interface Listener {

        void loggedIn();

        void loggedOut();

        /** A name was learnt or forgotten, so the accounts screen has something else to show. */
        void rosterChanged();
    }

    private final GearSetupBook book;
    private final AccountDirectory directory;
    private final CurrentAccount account;

    private Prompts prompts = SilentPrompts.INSTANCE;
    private Listener listener = new Listener() {
        @Override
        public void loggedIn() {
        }

        @Override
        public void loggedOut() {
        }

        @Override
        public void rosterChanged() {
        }
    };

    private Owner viewed;

    @Inject
    public Accounts(GearSetupBook book, AccountDirectory directory, CurrentAccount account) {
        this.book = Objects.requireNonNull(book, "book");
        this.directory = Objects.requireNonNull(directory, "directory");
        this.account = Objects.requireNonNull(account, "account");
        this.viewed = mine().orElse(Owner.shared());
        rememberCurrent();
    }

    /** Wired by the sidebar, after which the module follows logins and name changes itself. */
    void shownBy(Prompts newPrompts, Listener newListener) {
        this.prompts = Objects.requireNonNull(newPrompts, "newPrompts");
        this.listener = Objects.requireNonNull(newListener, "newListener");
        account.addListener(this::refresh);
        directory.addListener(() -> listener.rosterChanged());
    }

    /** The logged-in character, when there is one. */
    public Optional<Owner> mine() {
        return account.key().map(Owner::account);
    }

    public Owner viewed() {
        return viewed;
    }

    public void view(Owner owner) {
        viewed = Objects.requireNonNull(owner, "owner");
    }

    /** New setups belong to whoever's list is on show. */
    public Owner ownerForNewSetups() {
        return viewed;
    }

    /** Every account with setups, plus the shared one. */
    public List<AccountEntry> roster() {
        return AccountRoster.of(book.sections(), directory, account);
    }

    public String describeViewed() {
        return describe(viewed);
    }

    /** The remembered name, the live one for whoever is logged in, or a shortened key. */
    public String describe(Owner owner) {
        if (owner.isShared()) {
            return AccountEntry.SHARED_NAME;
        }
        String key = owner.account().orElseThrow();
        return directory.nameOf(key)
                .or(() -> account.key().filter(key::equals).flatMap(unused -> account.displayName()))
                .orElse(AccountEntry.UNKNOWN_NAME + " " + AccountEntry.shorten(key));
    }

    /** Where a setup could go instead, shared first. */
    public List<Owner> otherOwners(GearSetup setup) {
        List<Owner> owners = new ArrayList<>();
        owners.add(Owner.shared());
        roster().stream().map(AccountEntry::owner).filter(owner -> !owner.isShared()).forEach(owners::add);
        owners.remove(setup.owner());
        return List.copyOf(owners);
    }

    /** An account is only forgotten once nothing is left of it; true when it was. */
    public boolean forget(AccountEntry entry) {
        if (!entry.canForget()) {
            prompts.say(entry.name() + " still holds setups");
            return false;
        }
        entry.owner().account().ifPresent(directory::forget);
        prompts.say("Forgot " + entry.name());
        return true;
    }

    public void moveTo(GearSetup setup, Owner owner) {
        if (setup.owner().equals(owner)) {
            return;
        }
        book.setOwner(setup.id(), owner);
        prompts.announce(owner.isShared()
                ? "Shared " + setup.name() + " with all accounts"
                : "Moved " + setup.name() + " to " + describe(owner));
    }

    /** Flips between shared and the account whose list is on show, or the logged-in one when that is shared. */
    public void toggleSharing(GearSetup setup) {
        if (!setup.owner().isShared()) {
            moveTo(setup, Owner.shared());
            return;
        }
        Optional<Owner> target = viewed.isShared() ? mine() : Optional.of(viewed);
        if (target.isEmpty()) {
            prompts.say("Log in, or open an account, to keep " + setup.name() + " to one");
            return;
        }
        moveTo(setup, target.get());
    }

    /** Login opens that character's list; logout leaves nothing of theirs on show. */
    public void refresh() {
        rememberCurrent();
        Optional<Owner> mine = mine();
        if (mine.isPresent()) {
            viewed = mine.get();
            listener.loggedIn();
        } else {
            listener.loggedOut();
        }
    }

    private void rememberCurrent() {
        account.key().ifPresent(key -> account.displayName().ifPresent(name -> directory.remember(key, name)));
    }
}

