        JPanel row = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 2));
        row.setBackground(ColorScheme.DARK_GRAY_COLOR);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.add(child);
        return row;
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.GearSetup;
import dev.dutchy.runelite.gear.SetupId;
import dev.dutchy.runelite.gear.content.*;
import dev.dutchy.runelite.gear.history.SetupHistory;
import dev.dutchy.runelite.gear.history.SetupRevision;
import dev.dutchy.runelite.gear.player.PlayerItems;

import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;

/**
 * The commands the contents page sends to the setup it has open: variants, cells, slots and syncing
 * from the game. Asks before anything is lost and refuses a name that is already taken, so the page
 * itself only has to pass the click on.
 */
final class ContentHost {

    static final String MAX_VARIANTS = "A setup holds at most " + GearSetup.MAX_VARIANTS + " variants";
    static final String NEW_VARIANT_NAME = "Name for the new variant";
    static final String VARIANT_NAME = "Name for this variant";
    static final String NO_GAME_FOR_VARIANT = "Log in to start a variant from the game.";
    static final String NO_GAME_FOR_CELL = "Log in to fill a cell from the game.";
    static final String NO_GAME_FOR_SYNC = "Log in to sync from the game.";
    static final String NOTHING_COPIED = "Nothing copied yet";

    /** What the page does when a command needs another page. */
    interface Pages {

        /** Back to the contents page, for a command that has finished with the one on show. */
        void showContents();
    }

    private final OpenSetupEditor editor;
    private final SetupHistory history;
    private final PlayerItems playerItems;
    private final BooleanSupplier confirmBeforeSync;

    private Prompts prompts = SilentPrompts.INSTANCE;
    private Pages pages = () -> {
    };

    public ContentHost(OpenSetupEditor editor, SetupHistory history, PlayerItems playerItems, BooleanSupplier confirmBeforeSync) {
        this.editor = Objects.requireNonNull(editor, "editor");
        this.history = Objects.requireNonNull(history, "history");
        this.playerItems = Objects.requireNonNull(playerItems, "playerItems");
        this.confirmBeforeSync = Objects.requireNonNull(confirmBeforeSync, "confirmBeforeSync");
    }

    void shownBy(Prompts newPrompts, Pages newPages) {
        this.prompts = Objects.requireNonNull(newPrompts, "newPrompts");
        this.pages = Objects.requireNonNull(newPages, "newPages");
    }

    // --- variants ---

    /** Asks for a name, suggesting one nothing else is using. */
    public void addVariant(NewVariant start) {
        if (editor.setup().isEmpty()) {
            return;
        }
        if (!editor.canAddVariant()) {
            prompts.say(MAX_VARIANTS);
            return;
        }
        String suggestion = editor.freeVariantName(editor.editingVariant().map(SetupVariant::name)
                .orElse(SetupVariant.DEFAULT_NAME)).orElse("");
        prompts.askForName(NEW_VARIANT_NAME, suggestion).ifPresent(name -> addVariant(start, name));
    }

    public void addVariant(NewVariant start, String name) {
        Optional<GearSetup> setup = editor.setup();
        Optional<String> problem = editor.newVariantNameProblem(name);
        if (setup.isEmpty() || problem.isPresent()) {
            problem.ifPresent(prompts::say);
            return;
        }
        SetupContent edited = editor.content().orElse(setup.get().content());
        switch (start) {
            case COPY:
                editor.addVariant(name, edited);
                break;
            case EMPTY:
                editor.addVariant(name, NewVariant.emptyLike(edited));
                break;
            default:
                whileOpen(loadout -> editor.addVariant(name, new GearContent(loadout.equipment(), loadout.inventory())),
                        NO_GAME_FOR_VARIANT);
                break;
        }
    }

    public void renameVariant(int index) {
        editor.setup().flatMap(setup -> setup.variantAt(index))
                .flatMap(variant -> prompts.askForName(VARIANT_NAME, variant.name()))
                .ifPresent(name -> renameVariant(index, name));
    }

    public void renameVariant(int index, String name) {
        editor.renamedVariantNameProblem(index, name)
                .ifPresentOrElse(prompts::say, () -> editor.renameVariant(index, name));
    }

    public void duplicateVariant(int index) {
        if (editor.canAddVariant()) {
            editor.duplicateVariant(index);
        } else {
            prompts.say(MAX_VARIANTS);
        }
    }

    /** The last variant cannot go, because then the setup would hold nothing. */
    public void deleteVariant(int index) {
        editor.setup().filter(GearSetup::hasVariants).flatMap(setup -> setup.variantAt(index)).ifPresent(variant -> {
            if (prompts.confirm("Delete the variant \"" + variant.name() + "\" and its items?", "Delete variant")) {
                editor.removeVariant(index);
            }
        });
    }

    // --- cells ---

    public void renameCell(CellRef ref) {
        Optional<LayoutCell> cell = editor.cellAt(ref);
        if (cell.isEmpty()) {
            return;
        }
        prompts.askForName("Name for " + ref.describe(), cell.get().label()).ifPresent(name -> renameCell(ref, name));
    }

    public void renameCell(CellRef ref, String name) {
        if (!LayoutCell.isValidName(name)) {
            prompts.say("A cell name is 1 to " + LayoutCell.MAX_NAME_LENGTH + " characters");
            return;
        }
        editor.renameCell(ref, name);
    }

    /** Turning a cell back into an empty one drops its items, so it is asked about first. */
    public void emptyCell(CellRef ref) {
        Optional<LayoutCell> cell = editor.cellAt(ref);
        if (cell.isEmpty()) {
            return;
        }
        if (!cell.get().isEmpty() && !prompts.confirm(
                "Empty " + ref.describe() + " and drop its " + cell.get().items().size() + " item(s)?", "Empty cell")) {
            return;
        }
        editor.emptyCell(ref);
    }

    public void fillCellFromGame(CellRef ref) {
        whileOpen(loadout -> editor.fillCellFromGame(ref, loadout), NO_GAME_FOR_CELL);
    }

    // --- slots ---

    public void copySlots(List<SlotRef> refs) {
        prompts.say("Copied " + editor.copy(refs) + " item(s)");
        pages.showContents();
    }

    public void pasteAt(SlotRef anchor) {
        if (!editor.canPaste()) {
            prompts.say(NOTHING_COPIED);
            return;
        }
        editor.paste(anchor);
    }

    // --- history ---

    /** Every change to the setup on the page, newest first, whichever variant it came from. */
    public List<SetupRevision> revisions(SetupId setup) {
        return history.revisions(setup);
    }

    /** Puts an old revision back and opens the variant it came from. */
    public void restore(SetupRevision revision) {
        editor.restore(revision);
    }

    // --- syncing from the game ---

    /** Overwrites every slot in scope, so it is asked about unless that was turned off. */
    public void requestSync(SyncScope scope) {
        Optional<GearSetup> setup = editor.setup();
        if (setup.isEmpty()) {
            return;
        }
        if (!confirmBeforeSync.getAsBoolean() || prompts.confirm(warningFor(scope, setup.get()), "Sync from game")) {
            applySync(scope);
        }
    }

    public void applySync(SyncScope scope) {
        whileOpen(loadout -> editor.setup().ifPresent(setup -> editor.sync(scope, loadout, doneFor(scope, setup))),
                NO_GAME_FOR_SYNC);
    }

    static String warningFor(SyncScope scope, GearSetup setup) {
        switch (scope) {
            case GEAR:
                return "Replace everything in \"" + setup.name() + "\" with what you are wearing and carrying right now?\n"
                        + "Every equipment and inventory slot will be overwritten, including the ones you leave empty.";
            case LEFT_SIDE:
                return "Replace the left side of \"" + setup.name() + "\" with what you are carrying right now?\n"
                        + "Every slot on that side will be overwritten; the right side is left alone.";
            default:
                return "Replace the right side of \"" + setup.name() + "\" with what you are carrying right now?\n"
                        + "Every slot on that side will be overwritten; the left side is left alone.";
        }
    }

    static String doneFor(SyncScope scope, GearSetup setup) {
        switch (scope) {
            case GEAR:
                return setup.name() + " synced from the game";
            case LEFT_SIDE:
                return "Left side of " + setup.name() + " synced";
            default:
                return "Right side of " + setup.name() + " synced";
        }
    }

    /** Captures the player's items for the setup open now, dropping the capture if another was opened meanwhile. */
    private void whileOpen(Consumer<Loadout> onCaptured, String whenLoggedOut) {
        Optional<SetupId> target = editor.id();
        if (target.isEmpty()) {
            return;
        }
        playerItems.capture(loadout -> {
            if (editor.isOpen(target.get())) {
                onCaptured.accept(loadout);
            }
        }, () -> prompts.say(whenLoggedOut));
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.content.CellRef;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Value;
import lombok.With;

import java.util.Objects;
import java.util.Optional;

/** Where the contents page is looking: the row on show, the marked cell, and whether the variants and finder are open. */
@Value
@With
class ContentViewState {

    int row;
    @Getter(AccessLevel.NONE)
    CellRef cell;
    boolean variantsOpen;
    boolean finderOpen;
    String finderQuery;

    ContentViewState(int row, CellRef cell, boolean variantsOpen, boolean finderOpen, String finderQuery) {
        this.row = Math.max(0, row);
        this.cell = cell;
        this.variantsOpen = variantsOpen;
        this.finderOpen = finderOpen;
        this.finderQuery = Objects.requireNonNull(finderQuery, "finderQuery");
    }

    static ContentViewState initial() {
        return new ContentViewState(0, null, true, false, "");
    }

    Optional<CellRef> cell() {
        return Optional.ofNullable(cell);
    }

    /** Marks the cell and switches to its row. */
    ContentViewState at(CellRef ref) {
        return new ContentViewState(ref.row(), ref, variantsOpen, finderOpen, finderQuery);
    }

    ContentViewState withFinder(boolean open, String query) {
        return new ContentViewState(row, cell, variantsOpen, open, query);
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.ColourLabel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.function.Consumer;
import java.util.stream.Collectors;

/** A right-click menu drawn like the rest of the panel: a dark card with flat, icon-led rows. */
// A menu's rows stay general even where the one caller that builds them pins an argument.
@SuppressWarnings("SameParameterValue")
final class ContextMenu extends JPopupMenu {

    private static final int ROW_HEIGHT = 24;
    private static final int INSET = 8;
    private static final int ICON_GAP = 8;
    private static final int ICON_WIDTH = ActionIcon.ADD.getIconWidth();
    private static final int ARROW_WIDTH = 10;

    private final List<JMenuItem> entries = new ArrayList<>();
    private final List<Submenu> submenus = new ArrayList<>();
    private final List<ColourSwatch> swatches = new ArrayList<>();

    ContextMenu() {
        style(this);
    }

    ContextMenu item(ActionIcon icon, String text, Runnable action) {
        return add(new Entry(icon, text, action, false, false));
    }

    /** A destructive choice, coloured so it is not picked by accident. */
    ContextMenu danger(String text, Runnable action) {
        return add(new Entry(ActionIcon.TRASH, text, action, true, false));
    }

    ContextMenu divider() {
        add(new Divider());
        return this;
    }

    /** A row that opens a side menu on hover; {@code fill} adds its entries. */
    ContextMenu submenu(ActionIcon icon, String text, Consumer<Submenu> fill) {
        Submenu submenu = new Submenu(icon, text);
        Objects.requireNonNull(fill, "fill").accept(submenu);
        submenus.add(submenu);
        entries.add(submenu);
        super.add(submenu);
        return this;
    }

    /** A row of colour dots; picking one closes the menu. */
    ContextMenu swatches(ColourLabel current, Consumer<ColourLabel> onPick) {
        Objects.requireNonNull(onPick, "onPick");
        JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
        row.setOpaque(false);
        row.setBorder(BorderFactory.createEmptyBorder(3, INSET, 3, INSET));
        for (ColourLabel label : ColourLabel.values()) {
            ColourSwatch swatch = new ColourSwatch(label, label == current, () -> {
                setVisible(false);
                onPick.accept(label);
            });
            swatches.add(swatch);
            row.add(swatch);
        }
        super.add(row);
        return this;
    }

    List<ColourLabel> swatchLabels() {
        return swatches.stream().map(ColourSwatch::label).collect(Collectors.toList());
    }

    void pickSwatch(ColourLabel label) {
        swatches.stream().filter(swatch -> swatch.label() == label).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("No swatch for " + label)).pick();
    }

    List<String> entryTexts() {
        return entries.stream().map(JMenuItem::getText).collect(Collectors.toList());
    }

    void invoke(String text) {
        entries.stream()
                .filter(entry -> entry.getText().equals(text))
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException("No entry named " + text))
                .doClick(0);
    }

    Optional<Submenu> submenu(String text) {
        return submenus.stream().filter(submenu -> submenu.getText().equals(text)).findFirst();
    }

    private ContextMenu add(Entry entry) {
        entries.add(entry);
        super.add(entry);
        return this;
    }

    private static void style(JPopupMenu menu) {
        menu.setOpaque(true);
        menu.setBackground(Ui.SURFACE);
        menu.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(Ui.OUTLINE, 1),
                BorderFactory.createEmptyBorder(4, 4, 4, 4)));
    }

    private static void paintRow(Graphics g, JMenuItem row, ActionIcon icon, boolean armed, Color hover, Color foreground, boolean arrow) {
        Graphics2D g2 = (Graphics2D) g.create();
        try {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            if (armed) {
                g2.setColor(hover);
                g2.fillRoundRect(0, 0, row.getWidth(), row.getHeight(), Ui.RADIUS, Ui.RADIUS);
            }
            g2.setColor(foreground);
            if (icon != null) {
                icon.paintIcon(row, g2, INSET, (row.getHeight() - icon.getIconHeight()) / 2);
            }
            g2.setFont(row.getFont());
            FontMetrics metrics = g2.getFontMetrics();
            int y = (row.getHeight() - metrics.getHeight()) / 2 + metrics.getAscent();
            g2.drawString(row.getText(), INSET + ICON_WIDTH + ICON_GAP, y);
            if (arrow) {
                int tip = row.getWidth() - INSET - 2;
                int middle = row.getHeight() / 2;
                g2.drawLine(tip - 4, middle - 4, tip, middle);
                g2.drawLine(tip, middle, tip - 4, middle + 4);
            }
        } finally {
            g2.dispose();
        }
    }

    private static int rowWidth(JMenuItem row, boolean arrow) {
        FontMetrics metrics = row.getFontMetrics(row.getFont());
        return INSET + ICON_WIDTH + ICON_GAP + metrics.stringWidth(row.getText()) + INSET * 2 + (arrow ? ARROW_WIDTH : 0);
    }

    /** The side menu a submenu row opens: the same flat rows, one of which may be marked as the current choice. */
    static final class Submenu extends JMenu {

        private final ActionIcon icon;
        private final List<Entry> entries = new ArrayList<>();

        private Submenu(ActionIcon icon, String text) {
            super(Objects.requireNonNull(text, "text"));
            this.icon = Objects.requireNonNull(icon, "icon");
            setFont(FontManager.getRunescapeSmallFont());
            setOpaque(false);
            setBorderPainted(false);
            style(getPopupMenu());
        }

        void item(ActionIcon entryIcon, String text, Runnable action) {
            add(new Entry(entryIcon, text, action, false, false));
        }

        /** A choice that is the current one, marked with a tick. */
        void chosen(String text, Runnable action) {
            add(new Entry(ActionIcon.CHECK, text, action, false, true));
        }

        /** A choice that is not the current one, indented to line up with the ticked one. */
        void choice(String text, Runnable action) {
            add(new Entry(null, text, action, false, false));
        }

        void divider() {
            super.add(new Divider());
        }

        List<String> entryTexts() {
            return entries.stream().map(Entry::getText).collect(Collectors.toList());
        }

        List<String> chosenTexts() {
            return entries.stream().filter(entry -> entry.chosen).map(Entry::getText).collect(Collectors.toList());
        }

        void invoke(String text) {
            entries.stream()
                    .filter(entry -> entry.getText().equals(text))
                    .findFirst()
                    .orElseThrow(() -> new IllegalArgumentException("No entry named " + text))
                    .doClick(0);
        }

        private void add(Entry entry) {
            entries.add(entry);
            super.add(entry);
        }

        @Override
        public Color getForeground() {
            return isSelected() || isArmed() ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR;
        }

        @Override
        public Dimension getPreferredSize() {
            return new Dimension(rowWidth(this, true), ROW_HEIGHT);
        }

        @Override
        protected void paintComponent(Graphics g) {
            paintRow(g, this, icon, isSelected() || isArmed(), Ui.SURFACE_HOVER, getForeground(), true);
        }
    }

    private static final class Entry extends JMenuItem {

        private final ActionIcon icon;
        private final boolean danger;
        private final boolean chosen;

        Entry(ActionIcon icon, String text, Runnable action, boolean danger, boolean chosen) {
            super(Objects.requireNonNull(text, "text"));
            this.icon = icon;
            this.danger = danger;
            this.chosen = chosen;
            Objects.requireNonNull(action, "action");
            setFont(FontManager.getRunescapeSmallFont());
            setOpaque(false);
            setBorderPainted(false);
            addActionListener(e -> action.run());
        }

        @Override
        public Color getForeground() {
            if (danger) {
                return isArmed() ? ColorScheme.TEXT_COLOR : Ui.DANGER;
            }
            if (chosen) {
                return isArmed() ? ColorScheme.TEXT_COLOR : ColorScheme.BRAND_ORANGE;
            }
            return isArmed() ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR;
        }

        @Override
        public Dimension getPreferredSize() {
            return new Dimension(rowWidth(this, false), ROW_HEIGHT);
        }

        @Override
        protected void paintComponent(Graphics g) {
            paintRow(g, this, icon, isArmed(), danger ? Highlights.danger(Ui.SURFACE) : Ui.SURFACE_HOVER, getForeground(), false);
        }
    }

    private static final class Divider extends JComponent {

        Divider() {
            setPreferredSize(new Dimension(1, 7));
            setOpaque(false);
        }

        @Override
        protected void paintComponent(Graphics g) {
            g.setColor(Ui.OUTLINE);
            g.fillRect(INSET / 2, getHeight() / 2, getWidth() - INSET, 1);
        }
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.content.CellRef;
import dev.dutchy.runelite.gear.content.CustomContent;
import dev.dutchy.runelite.gear.content.SlotRef;
import dev.dutchy.runelite.gear.guide.HelpTopic;
import dev.dutchy.runelite.libs.ui.icon.ItemIconFactory;

import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;

/** A map of the grid on top, then one row of cells at a time, chosen by tab or by clicking the map. */
final class CustomBody extends ContentBody {

    private final CustomContent custom;
    private final ItemIconFactory icons;
    private final SlotView.Listener listener;
    private final CellActions cellActions;
    private final EquipmentSlotArtwork artwork;
    private final LayoutMap map;
    private final JPanel rowStrip = Ui.panel(new FlowLayout(FlowLayout.LEFT, Ui.SMALL_GAP, 0));
    private final List<Chip> rowChips = new ArrayList<>();
    private final JPanel cellArea = Ui.column(0);
    private final List<CellView> cellViews = new ArrayList<>();
    private int shownRow;

    CustomBody(CustomContent custom, ItemIconFactory icons, EquipmentSlotArtwork artwork, SlotView.Listener listener, CellActions cellActions) {
        this.custom = custom;
        this.icons = icons;
        this.artwork = artwork;
        this.listener = listener;
        this.cellActions = cellActions;
        map = Help.describe(new LayoutMap(custom, this::showCell), HelpTopic.LAYOUT_MAP);
        add(centered(map));
        add(Box.createVerticalStrut(Ui.GAP));
        if (custom.rows() > 1) {
            add(rowStripRow());
        }
        cellArea.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(cellArea);
        showRow(0);
    }

    @Override
    List<SlotView> slots() {
        List<SlotView> slots = new ArrayList<>();
        cellViews.forEach(view -> slots.addAll(view.slots()));
        return slots;
    }

    @Override
    void show(ContentViewState view) {
        if (view.row() != shownRow) {
            showRow(view.row());
        }
        view.cell().ifPresent(this::showCell);
    }

    @Override
    ContentViewState remember(ContentViewState view) {
        return map.current() == null ? view.withRow(shownRow).withCell(null) : view.at(map.current());
    }

    @Override
    void clicked(SlotRef ref) {
        if (ref instanceof SlotRef.Cell) {
            map.setCurrent(((SlotRef.Cell) ref).cell());
        }
    }

    @Override
    void showRowWithCell(boolean blank) {
        for (CellRef ref : custom.cellRefs()) {
            if (custom.cell(ref).isBlank() == blank) {
                if (ref.row() != shownRow) {
                    showRow(ref.row());
                }
                return;
            }
        }
    }

    @Override
    List<CellView> cellViews() {
        return List.copyOf(cellViews);
    }

    /** Shows one row of the grid: its two cells, stacked. */
    private void showRow(int row) {
        shownRow = Math.max(0, Math.min(custom.rows() - 1, row));
        cellViews.clear();
        cellArea.removeAll();
        boolean filledAnchored = false;
        boolean blankAnchored = false;
        for (int column = 0; column < CustomContent.COLUMNS; column++) {
            CellRef ref = CellRef.of(shownRow, column);
            CellView view = new CellView(ref, custom.cell(ref), icons, artwork, listener, cellActions);
            if (custom.cell(ref).isBlank() && !blankAnchored) {
                Help.anchor(view, HelpTopic.EMPTY_CELL);
                blankAnchored = true;
            } else if (!custom.cell(ref).isBlank() && !filledAnchored) {
                Help.anchor(view, HelpTopic.CELL);
                filledAnchored = true;
            }
            cellViews.add(view);
            cellArea.add(view);
        }
        for (int i = 0; i < rowChips.size(); i++) {
            rowChips.get(i).setChosen(i == shownRow);
        }
        cellArea.revalidate();
        cellArea.repaint();
    }

    /** Marks a cell on the map, switches to its row, and brings it into view. */
    private void showCell(CellRef ref) {
        if (ref.row() != shownRow) {
            showRow(ref.row());
        }
        map.setCurrent(ref);
        cellViews.stream().filter(view -> view.ref().equals(ref)).findFirst()
                .ifPresent(view -> view.scrollRectToVisible(new Rectangle(0, 0, view.getWidth(), view.getHeight())));
    }

    private JPanel rowStripRow() {
        rowStrip.setAlignmentX(Component.LEFT_ALIGNMENT);
        for (int row = 0; row < custom.rows(); row++) {
            int index = row;
            Chip chip = Chip.sized("Row " + (row + 1), "Show row " + (row + 1) + " of the grid", () -> showRow(index));
            rowChips.add(chip);
            rowStrip.add(chip);
        }
        return Help.anchor(rowStrip, HelpTopic.ROW_TABS);
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.content.*;
import dev.dutchy.runelite.gear.guide.HelpTopic;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import java.awt.*;
import java.awt.event.MouseEvent;
import java.util.*;
import java.util.List;
import java.util.stream.Collectors;

/** Edits one divider: its text, the columns it covers, and where the text sits; the strip below previews it. */
final class DividerEditorForm extends JPanel {

    interface Listener {

        void onDividerSet(SlotRef at, Divider divider);

        void onDividerRemoved(SlotRef at);

        void onCancelled();
    }

    static final String SAVE = "Save";
    static final String REMOVE = "Remove divider";

    private final SlotRef slot;
    private final int row;
    private final List<Divider> others;
    private final Listener listener;
    private final TextInput labelField = new TextInput();
    private final List<Chip> columnChips = new ArrayList<>();
    private final Map<TextAlign, Chip> alignChips = new EnumMap<>(TextAlign.class);
    private final Chip lineChip = new Chip("Underline", "Draw a line under the text, across the columns", () -> setUnderlined(true));
    private final Chip noLineChip = new Chip("No line", "Text only", () -> setUnderlined(false));
    private final PrimaryButton saveButton;
    private final JPanel previewHolder = Ui.panel(new BorderLayout());
    private int fromColumn;
    private int toColumn;
    private TextAlign align;
    private boolean underlined = true;

    /**
     * @param existing the divider over the slot's column, or null to start one there
     * @param onRow    every divider above the row, so a new one can take the free columns around the slot
     */
    DividerEditorForm(SlotRef slot, Divider existing, List<Divider> onRow, Listener listener) {
        this.slot = Objects.requireNonNull(slot, "slot");
        this.listener = Objects.requireNonNull(listener, "listener");
        Objects.requireNonNull(onRow, "onRow");
        this.row = ItemGrid.row(slot.gridIndex());
        this.others = onRow.stream().filter(divider -> !divider.equals(existing)).collect(Collectors.toList());
        int column = ItemGrid.column(slot.gridIndex());
        if (existing != null) {
            fromColumn = existing.fromColumn();
            toColumn = existing.toColumn();
            align = existing.align();
            underlined = existing.underlined();
            labelField.setText(existing.label());
        } else {
            fromColumn = freeEdge(column, -1);
            toColumn = freeEdge(column, 1);
            align = TextAlign.DEFAULT;
        }
        this.saveButton = new PrimaryButton(SAVE, "Keep this divider", this::save);

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        Help.anchor(this, HelpTopic.DIVIDER_PAGE);
        Help.describe(saveButton, HelpTopic.DIVIDER_SAVE);
        labelField.getDocument().addDocumentListener(new DocumentListener() {
            @Override
            public void insertUpdate(DocumentEvent e) {
                refresh();
            }

            @Override
            public void removeUpdate(DocumentEvent e) {
                refresh();
            }

            @Override
            public void changedUpdate(DocumentEvent e) {
                refresh();
            }
        });
        labelField.addActionListener(e -> save());

        JPanel actions = Ui.panel(new BorderLayout(Ui.SMALL_GAP, 0));
        actions.add(saveButton, BorderLayout.CENTER);
        JPanel secondary = Ui.panel(new FlowLayout(FlowLayout.RIGHT, Ui.SMALL_GAP, 0));
        if (existing != null) {
            secondary.add(new FlatButton(REMOVE, "Take this divider off the row", () -> listener.onDividerRemoved(slot)));
        }
        secondary.add(new FlatButton("Cancel", "Back without changing anything", listener::onCancelled));
        actions.add(secondary, BorderLayout.EAST);

        add(Ui.column(Ui.GAP,
                NavBar.create((existing == null ? "New divider above row " : "Divider above row ") + (row + 1), listener::onCancelled),
                Help.describe(Ui.labelled("Text", "up to " + Divider.MAX_LABEL_LENGTH + " characters", labelField), HelpTopic.DIVIDER_TEXT),
                Help.describe(Ui.labelled("Columns", "click to extend or shrink", columnChooser()), HelpTopic.DIVIDER_COLUMNS),
                Help.describe(Ui.labelled("Text sits", alignChooser()), HelpTopic.DIVIDER_ALIGN),
                Help.describe(Ui.labelled("Line", lineChooser()), HelpTopic.DIVIDER_LINE),
                Ui.labelled("Preview", previewHolder),
                actions), BorderLayout.NORTH);
        refresh();
    }

    String label() {
        return labelField.getText();
    }

    void setLabel(String text) {
        labelField.setText(text);
    }

    int fromColumn() {
        return fromColumn;
    }

    int toColumn() {
        return toColumn;
    }

    void setAlign(TextAlign newAlign) {
        align = Objects.requireNonNull(newAlign, "newAlign");
        refresh();
    }

    boolean isUnderlined() {
        return underlined;
    }

    void setUnderlined(boolean withLine) {
        underlined = withLine;
        refresh();
    }

    /** Extends the span to reach the column, or shrinks it when the column is an edge of a wider span. */
    void toggleColumn(int column) {
        if (column < fromColumn) {
            fromColumn = column;
        } else if (column > toColumn) {
            toColumn = column;
        } else if (column == fromColumn && toColumn > fromColumn) {
            fromColumn++;
        } else if (column == toColumn && toColumn > fromColumn) {
            toColumn--;
        }
        refresh();
    }

    /** The divider as it would be saved, or empty while the text is not valid. */
    Optional<Divider> draft() {
        return Divider.isValidLabel(labelField.getText())
                ? Optional.of(new Divider(row, fromColumn, toColumn, labelField.getText(), align, underlined))
                : Optional.empty();
    }

    void save() {
        draft().ifPresent(divider -> listener.onDividerSet(slot, divider));
    }

    @Override
    public boolean requestFocusInWindow() {
        return labelField.requestFocusInWindow();
    }

    private int freeEdge(int column, int direction) {
        int edge = column;
        while (edge + direction >= 0 && edge + direction < ItemGrid.COLUMNS && !taken(edge + direction)) {
            edge += direction;
        }
        return edge;
    }

    private boolean taken(int column) {
        return others.stream().anyMatch(divider -> divider.spansColumn(column));
    }

    private JPanel columnChooser() {
        JPanel row = Ui.panel(new GridLayout(1, ItemGrid.COLUMNS, Ui.SMALL_GAP, 0));
        for (int column = 0; column < ItemGrid.COLUMNS; column++) {
            int index = column;
            Chip chip = new Chip(String.valueOf(column + 1), "Column " + (column + 1), () -> toggleColumn(index));
            columnChips.add(chip);
            row.add(chip);
        }
        return row;
    }

    private JPanel alignChooser() {
        JPanel row = Ui.panel(new GridLayout(1, TextAlign.values().length, Ui.SMALL_GAP, 0));
        for (TextAlign choice : TextAlign.values()) {
            Chip chip = new Chip(choice.displayName(), "Put the text at the " + choice.displayName().toLowerCase(Locale.ROOT), () -> setAlign(choice));
            alignChips.put(choice, chip);
            row.add(chip);
        }
        return row;
    }

    private JPanel lineChooser() {
        JPanel row = Ui.panel(new GridLayout(1, 2, Ui.SMALL_GAP, 0));
        row.add(lineChip);
        row.add(noLineChip);
        return row;
    }

    private void refresh() {
        lineChip.setChosen(underlined);
        noLineChip.setChosen(!underlined);
        for (int column = 0; column < columnChips.size(); column++) {
            columnChips.get(column).setChosen(column >= fromColumn && column <= toColumn);
        }
        alignChips.forEach((choice, chip) -> chip.setChosen(choice == align));
        saveButton.setEnabled(draft().isPresent());
        previewHolder.removeAll();
        List<Divider> shown = new ArrayList<>(others);
        draft().ifPresent(shown::add);
        previewHolder.add(new DividerStrip(slot.gridSibling(row * ItemGrid.COLUMNS), shown, QUIET), BorderLayout.CENTER);
        previewHolder.revalidate();
        previewHolder.repaint();
    }

    /** The preview strip is only a picture; nothing on it does anything. */
    private static final SlotView.Listener QUIET = new SlotView.Listener() {
        @Override
        public void clicked(SlotView view, MouseEvent event) {
        }

        @Override
        public void pressed(SlotView view, MouseEvent event) {
        }

        @Override
        public void dragged(SlotView view, MouseEvent event) {
        }

        @Override
        public void released(SlotView view, MouseEvent event) {
        }

        @Override
        public void edit(SlotRef ref) {
        }

        @Override
        public void clear(SlotRef ref) {
        }

        @Override
        public void fillRemaining(SlotRef from) {
        }

        @Override
        public void fillRow(SlotRef from) {
        }

        @Override
        public void editDivider(SlotRef slot) {
        }

        @Override
        public void removeDivider(SlotRef slot) {
        }

        @Override
        public void changeDivider(SlotRef slot, DividerChange change) {
        }
    };
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.content.*;
import dev.dutchy.runelite.gear.guide.HelpTopic;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Collectors;

/**
 * The dividers above one grid row, each drawn as a labelled rule across the columns it covers.
 * Click a divider to edit it, click a free stretch to start one there, right-click for quick changes.
 */
final class DividerStrip extends JPanel {

    static final int HEIGHT = 16;
    static final String EDIT = "Edit divider…";
    static final String ADD = "Add divider here…";
    static final String REMOVE = "Remove divider";

    private static final int GAP = 2;
    private static final Color FREE = new Color(70, 70, 70);

    private final SlotRef rowStart;
    private final List<Divider> dividers;
    private final SlotView.Listener listener;
    private int hoveredColumn = -1;

    DividerStrip(SlotRef rowStart, List<Divider> dividers, SlotView.Listener listener) {
        this.rowStart = Objects.requireNonNull(rowStart, "rowStart");
        this.dividers = List.copyOf(Objects.requireNonNull(dividers, "dividers"));
        this.listener = Objects.requireNonNull(listener, "listener");
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setPreferredSize(new Dimension(0, HEIGHT));
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        Help.anchor(this, HelpTopic.DIVIDER);
        MouseAdapter mouse = new MouseAdapter() {
            @Override
            public void mouseMoved(MouseEvent e) {
                hoveredColumn = columnAt(e.getX());
                setToolTipText(dividerAt(hoveredColumn).map(divider -> divider.label() + " · click to edit, right-click for more")
                        .orElse("Click to add a divider over this column"));
                repaint();
            }

            @Override
            public void mouseExited(MouseEvent e) {
                hoveredColumn = -1;
                repaint();
            }

            @Override
            public void mousePressed(MouseEvent e) {
                maybeShowMenu(e);
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                maybeShowMenu(e);
            }

            @Override
            public void mouseClicked(MouseEvent e) {
                if (SwingUtilities.isLeftMouseButton(e)) {
                    listener.editDivider(slotAt(columnAt(e.getX())));
                }
            }
        };
        addMouseListener(mouse);
        addMouseMotionListener(mouse);
    }

    List<String> labels() {
        return dividers.stream().map(Divider::label).collect(Collectors.toList());
    }

    /** The slot under the column, which is how the host names a divider's place. */
    SlotRef slotAt(int column) {
        return rowStart.gridSibling(rowStart.gridIndex() + column);
    }

    Optional<Divider> dividerAt(int column) {
        return dividers.stream().filter(divider -> divider.spansColumn(column)).findFirst();
    }

    ContextMenu contextMenu(int column) {
        SlotRef slot = slotAt(column);
        Optional<Divider> divider = dividerAt(column);
        if (divider.isEmpty()) {
            return new ContextMenu().item(ActionIcon.ADD, ADD, () -> listener.editDivider(slot));
        }
        ContextMenu menu = new ContextMenu().item(ActionIcon.RENAME, EDIT, () -> listener.editDivider(slot));
        for (DividerChange change : DividerChange.values()) {
            if (change.changes(divider.get())) {
                menu.item(ActionIcon.MOVE_DOWN, change.label(), () -> listener.changeDivider(slot, change));
            }
        }
        return menu.divider().danger(REMOVE, () -> listener.removeDivider(slot));
    }

    private int columnAt(int x) {
        return Math.max(0, Math.min(ItemGrid.COLUMNS - 1, x * ItemGrid.COLUMNS / Math.max(1, getWidth())));
    }

    private void maybeShowMenu(MouseEvent e) {
        if (e.isPopupTrigger()) {
            contextMenu(columnAt(e.getX())).show(this, e.getX(), e.getY());
        }
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        Graphics2D g2 = (Graphics2D) g.create();
        try {
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g2.setFont(FontManager.getRunescapeSmallFont());
            FontMetrics metrics = g2.getFontMetrics();
            double column = (double) getWidth() / ItemGrid.COLUMNS;
            for (int c = 0; c < ItemGrid.COLUMNS; c++) {
                if (dividerAt(c).isEmpty()) {
                    g2.setColor(c == hoveredColumn ? ColorScheme.LIGHT_GRAY_COLOR : FREE);
                    g2.drawLine((int) (c * column) + GAP, getHeight() - 1, (int) ((c + 1) * column) - GAP, getHeight() - 1);
                }
            }
            for (Divider divider : dividers) {
                int left = (int) (divider.fromColumn() * column) + GAP;
                int right = (int) ((divider.toColumn() + 1) * column) - GAP;
                boolean lit = hoveredColumn >= 0 && divider.spansColumn(hoveredColumn);
                g2.setColor(lit ? ColorScheme.TEXT_COLOR : ColorScheme.BRAND_ORANGE);
                if (divider.underlined() || lit) {
                    g2.drawLine(left, getHeight() - 1, right, getHeight() - 1);
                }
                String text = fit(divider.label(), metrics, right - left);
                int x = alignedX(divider.align(), left + 1, right - 1, metrics.stringWidth(text));
                g2.drawString(text, x, getHeight() - 4);
            }
        } finally {
            g2.dispose();
        }
    }

    static int alignedX(TextAlign align, int left, int right, int textWidth) {
        switch (align) {
            case CENTRE:
                return left + (right - left - textWidth) / 2;
            case RIGHT:
                return right - textWidth;
            default:
                return left;
        }
    }

    private static String fit(String text, FontMetrics metrics, int width) {
        if (metrics.stringWidth(text) <= width) {
            return text;
        }
        String shortened = text;
        while (shortened.length() > 1 && metrics.stringWidth(shortened + "…") > width) {
            shortened = shortened.substring(0, shortened.length() - 1);
        }
        return shortened + "…";
    }
}

package dev.dutchy.runelite.gear.ui;

import java.awt.*;
import java.util.List;

final class DropIndex {

    private DropIndex() {
    }

    /** Returns a value from 0 to sections.size(). */
    static int sectionInsertionIndex(List<Rectangle> sections, int y) {
        int index = 0;
        for (Rectangle bounds : sections) {
            if (y > bounds.y + bounds.height / 2) {
                index++;
            }
        }
        return index;
    }

    /** Returns a value from 0 to tiles.size(). */
    static int insertionIndex(List<Rectangle> tiles, Point drop) {
        for (int i = 0; i < tiles.size(); i++) {
            Rectangle bounds = tiles.get(i);
            boolean aboveThisRow = drop.y < bounds.y;
            boolean inThisRow = drop.y >= bounds.y && drop.y < bounds.y + bounds.height;
            boolean leftHalf = drop.x < bounds.x + bounds.width / 2;
            if (aboveThisRow || (inThisRow && leftHalf)) {
                return i;
            }
        }
        return tiles.size();
    }
}

