        this.target = BulkTarget.of(section.id());
        this.grid = new SetupGrid(section.id(), section.setups(), icons, setupActions, setupDrags, bulk, style, preview, !config.hasChildren());
        this.toggleButton = new FlatButton(toggleIcon(), toggleTooltip(), () -> sectionActions.toggleSection(sectionId));
        this.title = titleOf(section);

        setLayout(new BorderLayout(0, Ui.SMALL_GAP));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(config.nested()
                ? BorderFactory.createCompoundBorder(
                        BorderFactory.createEmptyBorder(0, CHILD_INDENT - 2, Ui.GAP, 0),
                        BorderFactory.createMatteBorder(0, 2, 0, 0, Ui.OUTLINE))
                : BorderFactory.createEmptyBorder(0, 0, Ui.GAP, 0));
        setAlignmentX(Component.LEFT_ALIGNMENT);

        this.headerPanel = header(section, sectionDrags);
        add(headerPanel, BorderLayout.NORTH);
        if (!collapsed) {
            add(grid, BorderLayout.CENTER);
        }
    }

    SectionId sectionId() {
        return sectionId;
    }

    SetupGrid grid() {
        return grid;
    }

    boolean isRenaming() {
        return renaming;
    }

    boolean isNested() {
        return config.nested();
    }

    void refreshBulkHighlight() {
        headerPanel.setBackground(bulk != null && bulk.isSelected(target)
                ? Highlights.danger(ColorScheme.DARK_GRAY_COLOR)
                : ColorScheme.DARK_GRAY_COLOR);
        headerPanel.setOpaque(true);
        headerPanel.repaint();
    }

    boolean isCollapsed() {
        return collapsed;
    }

    /** Shows the grid in place, without rebuilding the panel. */
    void expand() {
        if (!collapsed) {
            return;
        }
        collapsed = false;
        add(grid, BorderLayout.CENTER);
        toggleButton.setIcon(toggleIcon());
        toggleButton.setToolTipText(toggleTooltip());
        revalidate();
        repaint();
    }

    /** Swaps the name for a field; Enter keeps the new name, Escape drops it. */
    void startRename() {
        if (renaming || bulk != null) {
            return;
        }
        renaming = true;
        renameField.setText(sectionName);
        titleArea.removeAll();
        titleArea.add(renameField, BorderLayout.CENTER);
        titleArea.revalidate();
        titleArea.repaint();
        renameField.requestFocusInWindow();
        renameField.selectAll();
    }

    void commitRename() {
        if (!renaming) {
            return;
        }
        String newName = renameField.getText();
        stopRenaming();
        if (GearSection.isValidName(newName) && !newName.strip().equals(sectionName)) {
            actions.renameSection(sectionId, newName);
        }
    }

    void cancelRename() {
        stopRenaming();
    }

    ContextMenu contextMenu() {
        ContextMenu menu = new ContextMenu()
                .item(ActionIcon.ADD, NEW_SETUP, () -> actions.addSetupTo(sectionId))
                .item(ActionIcon.SYNC, NEW_FROM_GAME, () -> actions.addSetupFromGame(sectionId))
                .item(ActionIcon.RENAME, RENAME, this::startRename)
                .item(ActionIcon.COLLAPSED, COLLAPSE_OTHERS, () -> actions.collapseOthers(sectionId))
                .item(ActionIcon.MOVE_UP, INSERT_ABOVE, () -> actions.insertSectionAbove(sectionId))
                .item(ActionIcon.MOVE_DOWN, INSERT_BELOW, () -> actions.insertSectionBelow(sectionId))
                .item(ActionIcon.COPY, EXPORT, () -> actions.exportSection(sectionId));
        for (SetupOrder order : SetupOrder.values()) {
            menu.item(ActionIcon.MOVE_DOWN, order.displayName(), () -> actions.sortSection(sectionId, order));
        }
        if (config.canAddChild()) {
            menu.item(ActionIcon.ADD, NEW_SUBSECTION, () -> actions.addSubSection(sectionId));
        }
        for (GearSection target : config.nestTargets()) {
            menu.item(ActionIcon.MOVE_DOWN, NEST_PREFIX + target.name(), () -> actions.nestSection(sectionId, target.id()));
        }
        if (config.canUnnest()) {
            menu.item(ActionIcon.MOVE_UP, UNNEST, () -> actions.unnestSection(sectionId));
        }
        if (config.deletable()) {
            menu.divider().danger(DELETE, () -> actions.deleteSection(sectionId));
        }
        return menu;
    }

    private ContextMenu addMenu() {
        return new ContextMenu()
                .item(ActionIcon.ADD, NEW_SETUP, () -> actions.addSetupTo(sectionId))
                .item(ActionIcon.SYNC, NEW_FROM_GAME, () -> actions.addSetupFromGame(sectionId));
    }

    private void stopRenaming() {
        renaming = false;
        titleArea.removeAll();
        titleArea.add(title, BorderLayout.CENTER);
        titleArea.revalidate();
        titleArea.repaint();
    }

    private ActionIcon toggleIcon() {
        return collapsed ? ActionIcon.COLLAPSED : ActionIcon.EXPANDED;
    }

    private String toggleTooltip() {
        return (collapsed ? "Expand " : "Collapse ") + sectionName;
    }

    private JPanel titleOf(GearSection section) {
        JLabel name = new JLabel(section.name());
        name.setFont(FontManager.getRunescapeBoldFont());
        name.setForeground(ColorScheme.TEXT_COLOR);
        JLabel count = Ui.hint(String.valueOf(section.size()));
        JPanel panel = Ui.panel(new FlowLayout(FlowLayout.LEFT, 5, 0));
        panel.setToolTipText("Drag to reorder, click to expand or collapse, double-click to rename, right-click for more");
        panel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        panel.add(name);
        panel.add(count);
        return panel;
    }

    private JPanel header(GearSection section, SectionDragController drags) {
        JPanel header = new JPanel(new BorderLayout(2, 0));
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        header.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createMatteBorder(0, 0, 1, 0, Ui.OUTLINE),
                BorderFactory.createEmptyBorder(0, 0, 2, 0)));

        titleArea.add(title, BorderLayout.CENTER);
        renameField.addActionListener(e -> commitRename());
        renameField.addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                if (e.getKeyCode() == KeyEvent.VK_ESCAPE) {
                    cancelRename();
                }
            }
        });
        renameField.addFocusListener(new FocusAdapter() {
            @Override
            public void focusLost(FocusEvent e) {
                commitRename();
            }
        });

        JPanel buttons = Ui.panel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
        if (bulk == null && config.canMoveUp()) {
            buttons.add(new FlatButton(ActionIcon.MOVE_UP, "Move " + section.name() + " up",
                    () -> actions.moveSectionUp(sectionId)));
        }
        if (bulk == null && config.canMoveDown()) {
            buttons.add(new FlatButton(ActionIcon.MOVE_DOWN, "Move " + section.name() + " down",
                    () -> actions.moveSectionDown(sectionId)));
        }
        if (bulk == null) {
            FlatButton add = Help.anchor(new FlatButton(ActionIcon.ADD, "Add a setup to " + section.name(), () -> {
            }), HelpTopic.SECTION_ADD);
            add.addActionListener(e -> addMenu().show(add, 0, add.getHeight()));
            buttons.add(add);
            FlatButton more = new FlatButton(ActionIcon.MORE, "More for " + section.name(), () -> {
            });
            more.addActionListener(e -> contextMenu().show(more, 0, more.getHeight()));
            buttons.add(more);
        }

        Help.anchor(header, HelpTopic.SECTION_HEADER);
        header.add(toggleButton, BorderLayout.WEST);
        header.add(titleArea, BorderLayout.CENTER);
        header.add(buttons, BorderLayout.EAST);

        if (bulk != null) {
            MouseAdapter picker = bulkHandle();
            header.addMouseListener(picker);
            title.addMouseListener(picker);
            title.setToolTipText("Click to select, shift click to select a range");
        } else {
            MouseAdapter handle = dragHandle(drags);
            header.addMouseListener(handle);
            header.addMouseMotionListener(handle);
            title.addMouseListener(handle);
            title.addMouseMotionListener(handle);
        }
        for (Component child : title.getComponents()) {
            for (MouseListener listener : title.getMouseListeners()) {
                child.addMouseListener(listener);
            }
            for (MouseMotionListener listener : title.getMouseMotionListeners()) {
                child.addMouseMotionListener(listener);
            }
        }
        return header;
    }

    private MouseAdapter bulkHandle() {
        return new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                bulk.select(target, e.isShiftDown());
            }
        };
    }

    private MouseAdapter dragHandle(SectionDragController drags) {
        return new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                if (maybeShowMenu(e)) {
                    return;
                }
                if (drags != null) {
                    drags.press(SectionView.this, e);
                }
            }

            @Override
            public void mouseDragged(MouseEvent e) {
                if (drags != null) {
                    drags.drag(SectionView.this, e);
                }
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                if (maybeShowMenu(e)) {
                    if (drags != null) {
                        drags.cancel();
                    }
                    return;
                }
                if (drags != null) {
                    drags.release(SectionView.this, e);
                }
            }

            @Override
            public void mouseClicked(MouseEvent e) {
                if (!SwingUtilities.isLeftMouseButton(e) || (drags != null && drags.draggedSincePress())) {
                    return;
                }
                if (e.getClickCount() == 2) {
                    startRename();
                } else if (e.getClickCount() == 1) {
                    actions.toggleSection(sectionId);
                }
            }
        };
    }

    private boolean maybeShowMenu(MouseEvent e) {
        if (!e.isPopupTrigger()) {
            return false;
        }
        Component source = e.getComponent();
        contextMenu().show(source, e.getX(), e.getY());
        return true;
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.ColourLabel;
import dev.dutchy.runelite.gear.GearSetup;
import dev.dutchy.runelite.gear.Owner;

import java.util.List;

interface SetupActions {

    void activate(GearSetup setup);

    void edit(GearSetup setup);

    void editContents(GearSetup setup);

    /** Makes the variant the setup's chosen one, so the bank shows it. */
    void selectVariant(GearSetup setup, int index);

    /** Opens the setup's contents and adds a variant that starts as a copy of the chosen one. */
    void addVariant(GearSetup setup);

    void delete(GearSetup setup);

    /** Every owner the setup could move to, the shared owner included, without its current one. */
    List<Owner> otherOwners(GearSetup setup);

    String describeOwner(Owner owner);

    void moveTo(GearSetup setup, Owner owner);

    void duplicate(GearSetup setup);

    void togglePin(GearSetup setup);

    void setLabel(GearSetup setup, ColourLabel label);

    /** Opens the key capture for the setup's hotkey. */
    void chooseHotkey(GearSetup setup);
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.*;
import dev.dutchy.runelite.gear.activation.SetupActivator;
import dev.dutchy.runelite.gear.content.CustomContent;
import dev.dutchy.runelite.gear.history.SetupHistory;

import javax.inject.Inject;
import java.util.Objects;
import java.util.Optional;
import java.util.function.Supplier;

/** What can be done to a whole setup: shown in the bank, pinned, coloured, bound to a key, copied, deleted. */
public final class SetupCommands {

    /** How many setups can sit in the pinned row at once. */
    public static final int MAX_PINNED = 8;

    private final GearSetupBook book;
    private final SetupHistory history;
    private final SetupActivator activator;

    private Prompts prompts = SilentPrompts.INSTANCE;
    private Runnable shownChanged = () -> {
    };
    private Supplier<Owner> owner = Owner::shared;

    @Inject
    public SetupCommands(GearSetupBook book, SetupHistory history, SetupActivator activator) {
        this.book = Objects.requireNonNull(book, "book");
        this.history = Objects.requireNonNull(history, "history");
        this.activator = Objects.requireNonNull(activator, "activator");
    }

    /** Wired by the list, which marks which setup the bank is showing and owns the dialogs. */
    void shownBy(Prompts newPrompts, Runnable onShownChanged, Supplier<Owner> ownerForNewSetups) {
        this.prompts = Objects.requireNonNull(newPrompts, "newPrompts");
        this.shownChanged = Objects.requireNonNull(onShownChanged, "onShownChanged");
        this.owner = Objects.requireNonNull(ownerForNewSetups, "ownerForNewSetups");
    }

    /** Shows the setup in the bank, or stops showing it when it is the one already up. */
    public void activate(GearSetup setup) {
        boolean nowShown = activator.toggle(setup.id()).filter(current -> current.id().equals(setup.id())).isPresent();
        prompts.say(nowShown ? "Showing " + setup.name() + " in the bank" : "Stopped showing " + setup.name());
        shownChanged.run();
    }

    public void delete(GearSetup setup) {
        if (!prompts.confirm("Delete \"" + setup.name() + "\"?", "Delete setup")) {
            return;
        }
        book.removeSetup(setup.id());
        history.forget(setup.id());
        prompts.announce("Deleted " + setup.name());
    }

    public void duplicate(GearSetup setup) {
        prompts.announce("Duplicated as " + book.duplicateSetup(setup.id()).name());
    }

    /** The pinned row holds only so many, so a further pin is refused rather than dropping one. */
    public void togglePin(GearSetup setup) {
        if (!setup.isPinned() && book.pinnedSetups().size() >= MAX_PINNED) {
            prompts.say("Up to " + MAX_PINNED + " setups can be pinned");
            return;
        }
        book.changeMeta(setup.id(), meta -> meta.withPinned(!setup.isPinned()));
        prompts.announce(setup.isPinned() ? "Unpinned " + setup.name() : "Pinned " + setup.name());
    }

    public void setLabel(GearSetup setup, ColourLabel label) {
        book.changeMeta(setup.id(), meta -> meta.withLabel(label));
        prompts.announce(label.isNone() ? "Removed the colour from " + setup.name() : "Coloured " + setup.name());
    }

    /** Binds the key to this setup alone; {@link Hotkey#NONE} clears it. */
    public void setHotkey(GearSetup setup, Hotkey hotkey) {
        if (hotkey.isSet()) {
            book.sections().stream().flatMap(section -> section.setups().stream())
                    .filter(other -> !other.id().equals(setup.id()) && other.meta().hotkey().equals(hotkey))
                    .forEach(other -> book.changeMeta(other.id(), meta -> meta.withHotkey(Hotkey.NONE)));
        }
        book.changeMeta(setup.id(), meta -> meta.withHotkey(hotkey));
        prompts.announce(hotkey.isSet() ? setup.name() + " is now on " + hotkey.describe() : "Removed the hotkey from " + setup.name());
    }

    /** Switches which variant the bank shows, from a menu rather than from the editor. */
    public void showVariant(GearSetup setup, int index) {
        setup.variantAt(index).ifPresent(variant -> {
            book.change(setup.id(), current -> current.withSelectedVariant(index));
            prompts.announce(setup.name() + " now shows " + variant.name());
        });
    }

    public GearSetup add(SectionId sectionId, GearSetup draft) {
        GearSetup added = book.addSetup(sectionId, draft.withOwner(owner.get()));
        prompts.announce("Created " + draft.name());
        return added;
    }

    /** A setup made from what the player is wearing right now. */
    public void addFromGame(SectionId sectionId, GearSetup draft) {
        book.addSetup(sectionId, draft.withOwner(owner.get()));
        prompts.announce("Created " + draft.name() + " from the game");
    }

    /**
     * Name, icon and meta always follow the draft; a custom layout's row count does too, once any
     * loss of items is confirmed.
     */
    public void applyEdit(SetupId id, GearSetup draft) {
        book.change(id, current -> current.withName(draft.name()).withIconOf(draft).withMeta(draft.meta()));
        prompts.announce("Saved " + draft.name());
        Optional<CustomContent> custom = book.setup(id).map(GearSetup::content)
                .filter(content -> content instanceof CustomContent).map(content -> (CustomContent) content);
        if (custom.isEmpty() || !(draft.content() instanceof CustomContent)) {
            return;
        }
        int rows = ((CustomContent) draft.content()).rows();
        if (rows == custom.get().rows()) {
            return;
        }
        if (custom.get().hasItemsBelow(rows) && !prompts.confirm("Drop the rows below row " + rows + " and everything in them?", "Fewer rows")) {
            return;
        }
        resizeRows(id, rows);
    }

    public void resizeRows(SetupId id, int rows) {
        book.change(id, current -> current.content() instanceof CustomContent
                ? current.withContent(((CustomContent) current.content()).withRows(rows)) : current);
    }

    public void moveToSection(SetupId setupId, SectionId section, int index) {
        book.moveSetup(setupId, section, index);
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.GearSetup;
import dev.dutchy.runelite.gear.Prayer;
import dev.dutchy.runelite.gear.Requirements;
import dev.dutchy.runelite.gear.content.*;
import dev.dutchy.runelite.gear.guide.HelpTopic;
import dev.dutchy.runelite.libs.ui.icon.ItemIconFactory;
import dev.dutchy.runelite.libs.ui.item.ResolvedItem;
import dev.dutchy.runelite.libs.ui.selector.ItemRowDragListener;
import dev.dutchy.runelite.libs.ui.selector.ItemSelector;
import dev.dutchy.runelite.libs.ui.selector.ItemSelectorFactory;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Collectors;

final class SetupContentPanel extends JPanel implements SlotView.Listener {

    static final String SYNC_GEAR = "Sync from game";
    static final String SYNC_SIDE = "Sync inventory";
    private static final int SEARCH_RESULTS = 5;

    private final ContentActions actions;
    private final SlotSelection selection = new SlotSelection();
    private final SlotDragController drags;
    private final ItemSelector finder;
    private final JPanel finderStrip;
    private final JPanel selectionStrip = Ui.panel(new BorderLayout(Ui.SMALL_GAP, 0));
    private final JLabel selectionCount = Ui.body("");
    private final FlatButton pasteButton;
    private final ContentBody body;
    private final VariantsPanel variants;

    SetupContentPanel(GearSetup setup,
                      int editing,
                      ItemIconFactory icons,
                      EquipmentSlotArtwork artwork,
                      ItemSelectorFactory selectors,
                      DropRule dropRule,
                      ContentActions actions,
                      CellActions cellActions,
                      ContentViewState view) {
        Objects.requireNonNull(setup, "setup");
        Objects.requireNonNull(view, "view");
        Objects.requireNonNull(selectors, "selectors");
        Objects.requireNonNull(icons, "icons");
        SetupContent content = setup.variantAt(editing).map(SetupVariant::content).orElse(setup.content());
        this.actions = Objects.requireNonNull(actions, "actions");
        Objects.requireNonNull(cellActions, "cellActions");
        Help.anchor(this, HelpTopic.CONTENTS_PAGE);
        this.drags = new SlotDragController(this, this::slotAt, dropRule, actions);
        this.pasteButton = new FlatButton("Paste", "Put copied items down from the first selected slot (Ctrl+V)", this::pasteSelection);

        setLayout(new BorderLayout(0, Ui.SMALL_GAP));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        finder = selectors.selector()
                .limit(SEARCH_RESULTS)
                .onRowDrag(finderDrag())
                .keepResultsOnSelect()
                .onSelect(this::finderPicked)
                .build();
        finderStrip = finderStrip();

        body = ContentBody.of(content, icons, Objects.requireNonNull(artwork, "artwork"), this, actions, cellActions);
        variants = new VariantsPanel(setup, editing, icons, actions, view.variantsOpen());

        JPanel header = Ui.panel(new BorderLayout(0, Ui.SMALL_GAP));
        header.setBorder(BorderFactory.createEmptyBorder(0, 0, Ui.SMALL_GAP, 0));
        header.add(navBar(setup), BorderLayout.NORTH);
        header.add(Ui.column(Ui.SMALL_GAP, variants, toolbar(body.toolbarAction().orElse(null)), notesLine(setup), requirementsLine(setup.meta().requirements()),
                finderStrip, selectionStrip()), BorderLayout.CENTER);

        JPanel middle = Ui.column(0, body);
        add(header, BorderLayout.NORTH);
        add(middle, BorderLayout.CENTER);
        installShortcuts();
        refreshSelectionStrip();
        show(view);
    }

    /** Where the page is looking now, to carry over to the page that replaces it. */
    ContentViewState viewState() {
        return body.remember(ContentViewState.initial()).withVariantsOpen(variants.isOpen())
                .withFinder(finderStrip.isVisible(), finder.query());
    }

    private void show(ContentViewState view) {
        body.show(view);
        if (view.finderOpen()) {
            finderStrip.setVisible(true);
            if (!view.finderQuery().isBlank()) {
                finder.setQuery(view.finderQuery());
            }
        }
    }

    VariantsPanel variants() {
        return variants;
    }

    int shownRow() {
        return viewState().row();
    }

    Optional<CellRef> currentCell() {
        return viewState().cell();
    }

    List<CellView> cellViews() {
        return body.cellViews();
    }

    void showCell(CellRef ref) {
        body.show(viewState().at(ref));
    }

    void showRowWithCell(boolean blank) {
        body.showRowWithCell(blank);
    }

    List<SlotView> slots() {
        return body.slots();
    }

    List<SlotRef> selectedSlots() {
        return selection.ordered(slotOrder());
    }

    boolean isFinderShowing() {
        return finderStrip.isVisible();
    }

    ItemSelector finder() {
        return finder;
    }

    SlotDragController drags() {
        return drags;
    }

    /** Selects as a click would: shift extends from the anchor, control toggles. */
    void select(SlotRef ref, boolean shift, boolean control) {
        selection.click(ref, shift, control, slotOrder());
        refreshSelection();
    }

    void clearSelection() {
        selection.clear();
        refreshSelection();
    }

    void copySelection() {
        if (!selection.isEmpty()) {
            actions.copySlots(selectedSlots());
        }
    }

    void pasteSelection() {
        selection.anchor().ifPresent(actions::pasteAt);
    }

    void deleteSelection() {
        if (!selection.isEmpty()) {
            actions.clearSlots(selectedSlots());
        }
    }

    void toggleFinder() {
        finderStrip.setVisible(!finderStrip.isVisible());
        if (finderStrip.isVisible()) {
            finder.requestFocusInWindow();
        }
        revalidate();
        repaint();
    }

    @Override
    public void clicked(SlotView view, MouseEvent event) {
        if (drags.isDragging()) {
            return;
        }
        body.clicked(view.ref());
        if (event.isShiftDown() || event.isControlDown()) {
            select(view.ref(), event.isShiftDown(), event.isControlDown());
            return;
        }
        if (!selection.isEmpty()) {
            clearSelection();
        }
        actions.editSlot(view.ref());
    }

    @Override
    public void pressed(SlotView view, MouseEvent event) {
        if (view.item().isPresent() && !event.isShiftDown() && !event.isControlDown()) {
            drags.press(new SlotDragController.FromSlot(view), view, event);
        }
    }

    @Override
    public void dragged(SlotView view, MouseEvent event) {
        drags.drag(view, event);
    }

    @Override
    public void released(SlotView view, MouseEvent event) {
        drags.release(view, event);
    }

    @Override
    public void edit(SlotRef ref) {
        actions.editSlot(ref);
    }

    @Override
    public void clear(SlotRef ref) {
        actions.clearSlot(ref);
    }

    @Override
    public void fillRemaining(SlotRef from) {
        actions.fillRemaining(from);
    }

    @Override
    public void fillRow(SlotRef from) {
        actions.fillRow(from);
    }

    @Override
    public void editDivider(SlotRef rowSlot) {
        actions.editDivider(rowSlot);
    }

    @Override
    public void removeDivider(SlotRef rowSlot) {
        actions.removeDivider(rowSlot);
    }

    @Override
    public void changeDivider(SlotRef slot, DividerChange change) {
        actions.changeDivider(slot, change);
    }

    private ItemRowDragListener finderDrag() {
        return new ItemRowDragListener() {
            @Override
            public void pressed(ResolvedItem item, MouseEvent event) {
                drags.press(new SlotDragController.FromSearch(item), (JComponent) event.getComponent(), event);
            }

            @Override
            public void dragged(ResolvedItem item, MouseEvent event) {
                drags.drag((JComponent) event.getComponent(), event);
            }

            @Override
            public void released(ResolvedItem item, MouseEvent event) {
                drags.release((JComponent) event.getComponent(), event);
            }
        };
    }

    /** Clicking a result with exactly one slot selected fills that slot. */
    private void finderPicked(ResolvedItem item) {
        List<SlotRef> selected = selectedSlots();
        if (selected.size() == 1) {
            actions.dropItem(item, selected.get(0));
        }
    }

    private SlotView slotAt(Point inPanel) {
        for (SlotView slot : body.slots()) {
            if (slot.getParent() == null) {
                continue;
            }
            Rectangle bounds = SwingUtilities.convertRectangle(slot.getParent(), slot.getBounds(), this);
            if (bounds.contains(inPanel)) {
                return slot;
            }
        }
        return null;
    }

    private List<SlotRef> slotOrder() {
        return body.slots().stream().map(SlotView::ref).collect(Collectors.toList());
    }

    private void refreshSelection() {
        for (SlotView slot : body.slots()) {
            slot.setSelected(selection.contains(slot.ref()));
        }
        refreshSelectionStrip();
    }

    private void refreshSelectionStrip() {
        selectionStrip.setVisible(!selection.isEmpty());
        selectionCount.setText(selection.size() + " selected");
        pasteButton.setEnabled(actions.canPaste());
        revalidate();
        repaint();
    }

    private JPanel selectionStrip() {
        selectionStrip.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 0));
        Help.anchor(selectionStrip, HelpTopic.SELECTION);
        JPanel buttons = Ui.panel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
        buttons.add(new FlatButton("Copy", "Copy the selected items (Ctrl+C)", this::copySelection));
        buttons.add(pasteButton);
        buttons.add(new FlatButton("Clear", "Empty the selected slots (Delete)", this::deleteSelection));
        selectionStrip.add(selectionCount, BorderLayout.CENTER);
        selectionStrip.add(buttons, BorderLayout.EAST);
        return selectionStrip;
    }

    private JPanel finderStrip() {
        JPanel strip = Ui.panel(new BorderLayout());
        strip.add(Help.anchor(finder, HelpTopic.FINDER), BorderLayout.CENTER);
        strip.setVisible(false);
        return strip;
    }

    private JPanel navBar(GearSetup setup) {
        JPanel bar = NavBar.create(setup.name(), actions::back);
        JPanel tools = Ui.panel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
        FlatButton find = new FlatButton(ActionIcon.SEARCH, "Find items to drag into slots", this::toggleFinder);
        FlatButton history = new FlatButton(ActionIcon.CLOCK, "Earlier versions of this setup", actions::showHistory);
        for (FlatButton button : List.of(find, history)) {
            button.setPreferredSize(new Dimension(24, 24));
            tools.add(button);
        }
        Help.anchor(tools, HelpTopic.CONTENTS_TOOLS);
        bar.add(tools, BorderLayout.EAST);
        return bar;
    }

    private static JPanel notesLine(GearSetup setup) {
        JPanel line = Ui.panel(new BorderLayout());
        if (!setup.meta().hasNotes()) {
            line.setVisible(false);
            return line;
        }
        WrappedText notes = Ui.paragraph(setup.meta().notes());
        notes.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 0));
        line.add(Ui.hint("Notes "), BorderLayout.WEST);
        line.add(notes, BorderLayout.CENTER);
        return line;
    }

    private static JPanel requirementsLine(Requirements requirements) {
        JPanel line = Ui.panel(new BorderLayout());
        if (requirements.isEmpty()) {
            line.setVisible(false);
            return line;
        }
        List<String> parts = new ArrayList<>();
        if (requirements.spellbook().isRequirement()) {
            parts.add(requirements.spellbook().displayName() + " spellbook");
        }
        if (requirements.hasQuickPrayers()) {
            parts.add("Quick prayers: " + Prayer.describe(requirements.quickPrayers()));
        }
        String joined = String.join(" · ", parts);
        WrappedText text = Ui.paragraph(joined);
        text.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 0));
        line.add(Ui.hint("Needs "), BorderLayout.WEST);
        line.add(text, BorderLayout.CENTER);
        return line;
    }

    private void installShortcuts() {
        bind(KeyStroke.getKeyStroke(KeyEvent.VK_C, InputEvent.CTRL_DOWN_MASK), "copy", this::copySelection);
        bind(KeyStroke.getKeyStroke(KeyEvent.VK_V, InputEvent.CTRL_DOWN_MASK), "paste", this::pasteSelection);
        bind(KeyStroke.getKeyStroke(KeyEvent.VK_DELETE, 0), "delete", this::deleteSelection);
        bind(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), "deselect", this::clearSelection);
        bind(KeyStroke.getKeyStroke(KeyEvent.VK_F, InputEvent.CTRL_DOWN_MASK), "find", this::toggleFinder);
    }

    private void bind(KeyStroke key, String name, Runnable action) {
        getInputMap(JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT).put(key, name);
        getActionMap().put(name, new AbstractAction() {
            @Override
            public void actionPerformed(ActionEvent e) {
                action.run();
            }
        });
    }

    private static JPanel toolbar(JComponent action) {
        JPanel row = Ui.panel(new BorderLayout(Ui.SMALL_GAP, 0));
        JLabel hint = Ui.hint("Click a slot to edit");
        hint.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 0));
        row.add(hint, BorderLayout.CENTER);
        if (action != null) {
            row.add(action, BorderLayout.EAST);
        }
        return row;
    }

}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.libs.ui.image.ImageTransforms;

import javax.swing.*;
import java.awt.*;
import java.awt.dnd.DragSource;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.Objects;
import java.util.function.Consumer;
import java.util.function.Function;

/** Mouse-driven drag that draws its own preview and caret. */
final class SetupDragController {

    private static final float PREVIEW_OPACITY = 0.75f;

    private static final int SPRING_DELAY_MILLIS = 550;

    private final JComponent dropArea;
    private final Function<Point, SetupGrid> gridAt;
    private final Function<Point, SectionView> sectionAt;
    private final Consumer<SectionView> onSpringOpen;
    private final SetupDropHandler handler;
    private final Timer springTimer;

    private SectionView springTarget;

    private SetupTile source;
    private Point pressPoint;
    private boolean dragging;
    private JLayeredPane dragLayer;
    private JLabel preview;
    private SetupGrid caretGrid;

    SetupDragController(JComponent dropArea,
                        Function<Point, SetupGrid> gridAt,
                        Function<Point, SectionView> sectionAt,
                        Consumer<SectionView> onSpringOpen,
                        SetupDropHandler handler) {
        this.dropArea = Objects.requireNonNull(dropArea, "dropArea");
        this.gridAt = Objects.requireNonNull(gridAt, "gridAt");
        this.sectionAt = Objects.requireNonNull(sectionAt, "sectionAt");
        this.onSpringOpen = Objects.requireNonNull(onSpringOpen, "onSpringOpen");
        this.handler = Objects.requireNonNull(handler, "handler");
        this.springTimer = new Timer(SPRING_DELAY_MILLIS, e -> springOpen());
        this.springTimer.setRepeats(false);
    }

    void press(SetupTile tile, MouseEvent event) {
        if (!SwingUtilities.isLeftMouseButton(event)) {
            return;
        }
        source = tile;
        pressPoint = event.getPoint();
        dragging = false;
    }

    void drag(SetupTile tile, MouseEvent event) {
        if (source != tile || pressPoint == null) {
            return;
        }
        if (!dragging) {
            if (event.getPoint().distance(pressPoint) <= DragSource.getDragThreshold()) {
                return;
            }
            dragging = true;
            addPreview();
        }
        Point inDropArea = SwingUtilities.convertPoint(tile, event.getPoint(), dropArea);
        movePreview(tile, event);
        showCaret(inDropArea);
        updateSpring(inDropArea);
    }

    private void updateSpring(Point inDropArea) {
        SectionView hovered = sectionAt.apply(inDropArea);
        if (hovered == null || !hovered.isCollapsed()) {
            springTarget = null;
            springTimer.stop();
            return;
        }
        if (springTarget != hovered) {
            springTarget = hovered;
            springTimer.restart();
        }
    }

    private void springOpen() {
        if (dragging && springTarget != null && springTarget.isCollapsed()) {
            onSpringOpen.accept(springTarget);
        }
        springTarget = null;
    }

    void release(SetupTile tile, MouseEvent event) {
        if (source != tile) {
            return;
        }
        if (dragging) {
            Point inDropArea = SwingUtilities.convertPoint(tile, event.getPoint(), dropArea);
            SetupGrid target = gridAt.apply(inDropArea);
            if (target != null) {
                Point inGrid = SwingUtilities.convertPoint(dropArea, inDropArea, target);
                handler.onSetupDropped(tile.setup().id(), target.sectionId(), target.insertionIndexAt(inGrid));
            }
        }
        cancel();
    }

    void cancel() {
        springTimer.stop();
        springTarget = null;
        clearCaret();
        removePreview();
        source = null;
        pressPoint = null;
        dragging = false;
    }

    private void showCaret(Point inDropArea) {
        SetupGrid target = gridAt.apply(inDropArea);
        if (target == null) {
            clearCaret();
            return;
        }
        if (caretGrid != null && caretGrid != target) {
            caretGrid.clearCaret();
        }
        caretGrid = target;
        target.showCaret(target.insertionIndexAt(SwingUtilities.convertPoint(dropArea, inDropArea, target)));
    }

    private void clearCaret() {
        if (caretGrid != null) {
            caretGrid.clearCaret();
            caretGrid = null;
        }
    }

    private void addPreview() {
        JRootPane rootPane = SwingUtilities.getRootPane(dropArea);
        if (rootPane == null || source.getWidth() <= 0) {
            return;
        }
        BufferedImage image = ImageTransforms.opacity(PREVIEW_OPACITY).apply(source.snapshot());
        dragLayer = rootPane.getLayeredPane();
        preview = new JLabel(new ImageIcon(image));
        preview.setSize(source.getSize());
        dragLayer.add(preview, JLayeredPane.DRAG_LAYER);
    }

    private void movePreview(SetupTile tile, MouseEvent event) {
        if (preview == null) {
            return;
        }
        Point inLayer = SwingUtilities.convertPoint(tile, event.getPoint(), dragLayer);
        preview.setLocation(inLayer.x - pressPoint.x, inLayer.y - pressPoint.y);
        dragLayer.repaint();
    }

    private void removePreview() {
        if (preview != null && dragLayer != null) {
            dragLayer.remove(preview);
            dragLayer.repaint();
        }
        preview = null;
        dragLayer = null;
    }
}

