import javax.swing.event.DocumentListener;
import java.awt.*;
import java.util.*;
import java.util.List;

final class SlotEditorForm extends JPanel {

    interface Listener {

        void onSlotSet(SlotRef ref, SetupItem item);

        void onSlotCleared(SlotRef ref);

        void onCancelled();
    }

    private final SlotRef ref;
    private final Listener listener;
    private final ItemPicker picker;
    private final TextInput quantityField = new TextInput();
    private final AmountPresets presets = new AmountPresets(this::setEnteredQuantity);
    private final PrimaryButton saveButton;
    private final FlatButton clearButton;
    private final ItemIconFactory icons;
    private final Map<ItemMatch, Chip> matchChips = new EnumMap<>(ItemMatch.class);
    private final Chip asItemChip = new Chip("Item", "Withdraw the item itself", () -> setNoted(false));
    private final Chip asNoteChip = new Chip("Note", "Withdraw it as a bank note", () -> setNoted(true));
    private boolean noted;
    private final JPanel alternativeRows = Ui.column(Ui.SMALL_GAP);
    private final ItemPicker alternativePicker;
    private final FlatButton addAlternativeButton;

    private ItemId item;
    private ItemMatch match;
    private final List<ItemId> alternatives = new ArrayList<>();

    /** An editor for a slot that is still empty. */
    static SlotEditorForm forEmptySlot(SlotRef ref, ItemIconFactory icons, ItemSelectorFactory selectors, Listener listener) {
        return new SlotEditorForm(ref, null, icons, selectors, listener);
    }

    /** An editor pre-filled with the slot's current item. */
    static SlotEditorForm forItem(SlotRef ref, SetupItem existing, ItemIconFactory icons, ItemSelectorFactory selectors, Listener listener) {
        return new SlotEditorForm(ref, Objects.requireNonNull(existing, "existing"), icons, selectors, listener);
    }

    private SlotEditorForm(SlotRef ref,
                           SetupItem existing,
                           ItemIconFactory icons,
                           ItemSelectorFactory selectors,
                           Listener listener) {
        this.ref = Objects.requireNonNull(ref, "ref");
        this.listener = Objects.requireNonNull(listener, "listener");
        this.icons = Objects.requireNonNull(icons, "icons");
        this.item = existing == null ? null : existing.id();
        this.match = existing == null ? ItemMatch.DEFAULT : existing.match();
        this.noted = existing != null && existing.noted();
        if (existing != null) {
            alternatives.addAll(existing.alternatives());
        }
        this.picker = new ItemPicker(icons, selectors, resolved -> chooseItem(resolved.id()), this::forgetItem);
        this.alternativePicker = new ItemPicker(icons, selectors, resolved -> addAlternative(resolved.id()), () -> {
        });
        this.addAlternativeButton = FlatButton.outlined(ActionIcon.ADD, "Add alternative", "Accept another item in this slot", this::showAlternativePicker);
        this.saveButton = new PrimaryButton("Save", "Put this item in the slot", this::save);
        this.clearButton = new FlatButton("Empty slot", "Remove the item from this slot", this::clear);

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        Help.anchor(this, HelpTopic.SLOT_PAGE);
        Help.describe(saveButton, HelpTopic.SLOT_SAVE);
        add(Ui.column(Ui.GAP,
                NavBar.create(ref.describe(), this::cancel),
                Help.describe(Ui.labelled("Item", picker), HelpTopic.SLOT_ITEM),
                Help.describe(Ui.labelled("Match", "how the bank is searched", matchChooser()), HelpTopic.SLOT_MATCH),
                Help.describe(Ui.labelled("Withdraw as", "notes for bulk trips", notedChooser()), HelpTopic.SLOT_NOTED),
                Help.describe(Ui.labelled("Also accept", "in order of preference", alternativesSection()), HelpTopic.SLOT_ALTERNATIVES),
                Help.describe(Ui.labelled("Amount", "blank follows the bank", Ui.column(Ui.SMALL_GAP, presets, quantityField())), HelpTopic.SLOT_AMOUNT),
                actions()), BorderLayout.NORTH);

        if (item != null) {
            picker.show(item);
        }
        quantityField.setText(existing != null && existing.hasQuantity() ? String.valueOf(existing.quantity().orElse(0)) : "");
        clearButton.setEnabled(existing != null);
        refreshMatch();
        refreshNoted();
        refreshAlternatives();
        refreshAmount();
    }

    boolean isNoted() {
        return noted;
    }

    void setNoted(boolean asNote) {
        noted = asNote;
        refreshNoted();
    }

    private JPanel notedChooser() {
        JPanel row = Ui.panel(new GridLayout(1, 2, Ui.SMALL_GAP, 0));
        row.add(asItemChip);
        row.add(asNoteChip);
        return row;
    }

    private void refreshNoted() {
        asItemChip.setChosen(!noted);
        asNoteChip.setChosen(noted);
    }

    ItemMatch chosenMatch() {
        return match;
    }

    void setMatch(ItemMatch newMatch) {
        match = Objects.requireNonNull(newMatch, "newMatch");
        refreshMatch();
    }

    List<ItemId> alternatives() {
        return List.copyOf(alternatives);
    }

    void addAlternative(ItemId alternative) {
        Objects.requireNonNull(alternative, "alternative");
        boolean isPrimary = alternative.equals(item);
        if (isPrimary || alternatives.contains(alternative) || alternatives.size() >= SetupItem.MAX_ALTERNATIVES) {
            alternativePicker.clear();
            return;
        }
        alternatives.add(alternative);
        alternativePicker.clear();
        alternativePicker.setVisible(false);
        refreshAlternatives();
    }

    void removeAlternative(ItemId alternative) {
        if (alternatives.remove(alternative)) {
            refreshAlternatives();
        }
    }

    Optional<ItemId> chosenItem() {
        return Optional.ofNullable(item);
    }

    OptionalInt enteredQuantity() {
        return enteredAmount();
    }

    void setEnteredQuantity(String text) {
        quantityField.setText(text);
    }

    boolean isSaveEnabled() {
        return saveButton.isEnabled();
    }

    void chooseItem(ItemId newItem) {
        item = Objects.requireNonNull(newItem, "newItem");
        picker.show(newItem);
        refreshSaveEnabled();
    }

    void save() {
        if (item == null || !isQuantityUsable()) {
            return;
        }
        listener.onSlotSet(ref, new SetupItem(item, enteredAmount().orElse(SetupItem.BANK_AMOUNT), match, alternatives, noted));
    }

    void clear() {
        listener.onSlotCleared(ref);
    }

    void cancel() {
        listener.onCancelled();
    }

    @Override
    public boolean requestFocusInWindow() {
        return picker.requestFocusInWindow();
    }

    /** One chip per rule, the rules that accept variants together on the top row. */
    private JPanel matchChooser() {
        JPanel rows = Ui.panel(new GridLayout(2, 2, Ui.SMALL_GAP, Ui.SMALL_GAP));
        for (ItemMatch rule : List.of(ItemMatch.ANY_VARIANT, ItemMatch.PREFER_THIS, ItemMatch.EMPTIEST_FIRST, ItemMatch.EXACT)) {
            Chip chip = new Chip(rule.displayName(), rule.description(), () -> setMatch(rule));
            matchChips.put(rule, chip);
            rows.add(chip);
        }
        return rows;
    }

    private JPanel alternativesSection() {
        alternativePicker.setVisible(false);
        JPanel footer = Ui.panel(new BorderLayout());
        footer.add(addAlternativeButton, BorderLayout.WEST);
        return Ui.column(Ui.SMALL_GAP, alternativeRows, alternativePicker, footer);
    }

    private void showAlternativePicker() {
        alternativePicker.setVisible(true);
        alternativePicker.requestFocusInWindow();
        revalidate();
    }

    private void refreshMatch() {
        matchChips.forEach((rule, chip) -> chip.setChosen(rule == match));
    }

    private void refreshAlternatives() {
        alternativeRows.removeAll();
        int rank = 1;
        for (ItemId alternative : alternatives) {
            AlternativeRow row = new AlternativeRow(rank++, alternative, icons, this::removeAlternative);
            row.setAlignmentX(Component.LEFT_ALIGNMENT);
            alternativeRows.add(row);
        }
        alternativeRows.setVisible(!alternatives.isEmpty());
        addAlternativeButton.setEnabled(alternatives.size() < SetupItem.MAX_ALTERNATIVES);
        alternativeRows.revalidate();
        alternativeRows.repaint();
        revalidate();
        repaint();
    }

    private void forgetItem() {
        item = null;
        refreshSaveEnabled();
    }

    private boolean isQuantityUsable() {
        return quantityField.getText().isBlank() || enteredAmount().isPresent();
    }

    Optional<String> chosenPreset() {
        return presets.chosen();
    }

    private OptionalInt enteredAmount() {
        return QuantityText.parse(quantityField.getText());
    }

    private void refreshAmount() {
        presets.reflect(quantityField.getText());
        refreshSaveEnabled();
    }

    private void refreshSaveEnabled() {
        saveButton.setEnabled(item != null && isQuantityUsable());
    }

    private JPanel actions() {
        JPanel row = Ui.panel(new BorderLayout(Ui.SMALL_GAP, 0));
        row.setBorder(BorderFactory.createEmptyBorder(Ui.SMALL_GAP, 0, 0, 0));
        row.add(saveButton, BorderLayout.CENTER);
        row.add(clearButton, BorderLayout.EAST);
        return row;
    }

    private TextInput quantityField() {
        quantityField.setToolTipText("How many to withdraw, such as 250, 10K, 2.5M or MAX; blank takes whatever the bank holds");
        quantityField.addActionListener(e -> save());
        quantityField.getDocument().addDocumentListener(new DocumentListener() {
            @Override
            public void insertUpdate(DocumentEvent e) {
                refreshAmount();
            }

            @Override
            public void removeUpdate(DocumentEvent e) {
                refreshAmount();
            }

            @Override
            public void changedUpdate(DocumentEvent e) {
                refreshAmount();
            }
        });
        return quantityField;
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.content.SlotRef;

import java.util.*;

/** Which slots on the contents page are selected; click, shift-click for a range, ctrl-click to toggle. */
final class SlotSelection {

    private final Set<SlotRef> selected = new LinkedHashSet<>();
    private SlotRef anchor;

    void click(SlotRef ref, boolean shift, boolean control, List<SlotRef> order) {
        Objects.requireNonNull(ref, "ref");
        Objects.requireNonNull(order, "order");
        if (shift && anchor != null) {
            int from = order.indexOf(anchor);
            int to = order.indexOf(ref);
            if (from >= 0 && to >= 0) {
                if (!control) {
                    selected.clear();
                }
                for (int index = Math.min(from, to); index <= Math.max(from, to); index++) {
                    selected.add(order.get(index));
                }
                return;
            }
        }
        if (control) {
            if (!selected.remove(ref)) {
                selected.add(ref);
            }
        } else {
            selected.clear();
            selected.add(ref);
        }
        anchor = ref;
    }

    void clear() {
        selected.clear();
        anchor = null;
    }

    boolean contains(SlotRef ref) {
        return selected.contains(ref);
    }

    boolean isEmpty() {
        return selected.isEmpty();
    }

    int size() {
        return selected.size();
    }

    /** Selected slots in page order. */
    List<SlotRef> ordered(List<SlotRef> order) {
        List<SlotRef> ordered = new ArrayList<>();
        for (SlotRef ref : order) {
            if (selected.contains(ref)) {
                ordered.add(ref);
            }
        }
        return ordered;
    }

    Optional<SlotRef> anchor() {
        return Optional.ofNullable(anchor);
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.content.*;
import dev.dutchy.runelite.libs.ui.icon.ItemIcon;
import dev.dutchy.runelite.libs.ui.icon.ItemIconFactory;
import dev.dutchy.runelite.libs.ui.image.ImageTransforms;
import dev.dutchy.runelite.libs.ui.item.ItemReference;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.Locale;
import java.util.Objects;
import java.util.Optional;

final class SlotView extends Card {

    /** How the host hears about clicks, drags, and menu choices on a slot. */
    interface Listener {

        void clicked(SlotView view, MouseEvent event);

        void pressed(SlotView view, MouseEvent event);

        void dragged(SlotView view, MouseEvent event);

        void released(SlotView view, MouseEvent event);

        void edit(SlotRef ref);

        void clear(SlotRef ref);

        void fillRemaining(SlotRef from);

        void fillRow(SlotRef from);

        /** Opens the divider over the slot's column for editing, or starts one there. */
        void editDivider(SlotRef slot);

        /** Drops the divider over the slot's column. */
        void removeDivider(SlotRef slot);

        /** Applies a one-step change to the divider over the slot's column. */
        void changeDivider(SlotRef slot, DividerChange change);
    }

    enum DropState { NONE, ALLOWED, REFUSED }

    static final int SIZE = 44;
    static final String ADD_ITEM = "Add item";
    static final String CHANGE_ITEM = "Change item";
    static final String DELETE_ITEM = "Delete item";
    static final String FILL_REMAINING = "Fill remaining";
    static final String FILL_ROW = "Fill this row";
    static final String ADD_DIVIDER = "Divider above…";
    private static final int ICON_SIZE = 34;
    private static final int QUANTITY_INSET = 3;
    private static final float GHOST_OPACITY = 0.3f;
    private static final float GLYPH_OPACITY = 0.45f;
    private static final Color NOTE_BADGE = new Color(120, 190, 255);

    private final SlotRef ref;
    private final SetupItem item;
    private final SetupItem shadow;
    private final Listener listener;
    private boolean hovered;
    private boolean selected;
    private DropState dropState = DropState.NONE;
    private BufferedImage glyph;

    /** An empty slot. */
    SlotView(SlotRef ref, ItemIconFactory icons, Listener listener) {
        this(ref, null, null, icons, listener);
    }

    /** A slot holding an item. */
    SlotView(SlotRef ref, SetupItem item, ItemIconFactory icons, Listener listener) {
        this(ref, Objects.requireNonNull(item, "item"), null, icons, listener);
    }

    private SlotView(SlotRef ref, SetupItem item, SetupItem shadow, ItemIconFactory icons, Listener listener) {
        this.ref = Objects.requireNonNull(ref, "ref");
        this.item = item;
        this.shadow = shadow;
        this.listener = Objects.requireNonNull(listener, "listener");

        setLayout(new BorderLayout());
        setPreferredSize(new Dimension(SIZE, SIZE));
        setMinimumSize(new Dimension(SIZE, SIZE));
        setMaximumSize(new Dimension(SIZE, SIZE));
        setRadius(4);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        setToolTipText(tooltip(null));

        if (item != null) {
            ItemIcon icon = icons.icon(ICON_SIZE, ICON_SIZE);
            icon.setResolvedListener(resolved -> setToolTipText(tooltip(resolved.name())));
            icon.setItem(ItemReference.byId(item.id()));
            add(icon, BorderLayout.CENTER);
        } else if (shadow != null) {
            ItemIcon icon = icons.icon(ICON_SIZE, ICON_SIZE);
            icon.setImageTransform(ImageTransforms.opacity(GHOST_OPACITY));
            icon.setResolvedListener(resolved -> setToolTipText(tooltip(resolved.name())));
            icon.setItem(ItemReference.byId(shadow.id()));
            add(icon, BorderLayout.CENTER);
        }

        MouseAdapter mouse = new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                if (SwingUtilities.isLeftMouseButton(e)) {
                    listener.clicked(SlotView.this, e);
                }
            }

            @Override
            public void mousePressed(MouseEvent e) {
                if (maybeShowMenu(e)) {
                    return;
                }
                listener.pressed(SlotView.this, e);
            }

            @Override
            public void mouseDragged(MouseEvent e) {
                listener.dragged(SlotView.this, e);
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                if (maybeShowMenu(e)) {
                    return;
                }
                listener.released(SlotView.this, e);
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                hovered = true;
                refresh();
            }

            @Override
            public void mouseExited(MouseEvent e) {
                hovered = false;
                refresh();
            }
        };
        addMouseListener(mouse);
        addMouseMotionListener(mouse);
        refresh();
    }

    SlotRef ref() {
        return ref;
    }

    Optional<SetupItem> item() {
        return Optional.ofNullable(item);
    }

    void setSelected(boolean isSelected) {
        selected = isSelected;
        refresh();
    }

    DropState dropState() {
        return dropState;
    }

    /** The game's own picture of what goes here, drawn faded while the slot is empty. */
    void showGlyph(BufferedImage image) {
        glyph = Objects.requireNonNull(image, "image");
        repaint();
    }

    boolean hasGlyph() {
        return glyph != null;
    }

    void setDropState(DropState state) {
        dropState = Objects.requireNonNull(state, "state");
        refresh();
    }

    ContextMenu contextMenu() {
        ContextMenu menu = new ContextMenu();
        if (item == null) {
            menu.item(ActionIcon.ADD, ADD_ITEM, () -> listener.edit(ref));
            if (ref.inGrid()) {
                menu.item(ActionIcon.RENAME, ADD_DIVIDER, () -> listener.editDivider(ref));
            }
            return menu;
        }
        menu.item(ActionIcon.RENAME, CHANGE_ITEM, () -> listener.edit(ref));
        if (ref.inGrid()) {
            menu.item(ActionIcon.MOVE_DOWN, FILL_REMAINING, () -> listener.fillRemaining(ref))
                    .item(ActionIcon.GRID, FILL_ROW, () -> listener.fillRow(ref))
                    .item(ActionIcon.RENAME, ADD_DIVIDER, () -> listener.editDivider(ref));
        }
        return menu.divider().danger(DELETE_ITEM, () -> listener.clear(ref));
    }

    private boolean maybeShowMenu(MouseEvent e) {
        if (!e.isPopupTrigger()) {
            return false;
        }
        contextMenu().show(this, e.getX(), e.getY());
        return true;
    }

    /** The item name on its own line once it has resolved, then the slot and how it is filled. */
    private String tooltip(String itemName) {
        String details;
        if (item == null) {
            details = shadow != null ? ref.describe() + ": same as base, click to swap" : "Set " + ref.describe();
        } else {
            String amount = item.quantity().isPresent() ? item.quantity().getAsInt() + "x" : "whatever the bank holds";
            String rule = item.match() == ItemMatch.DEFAULT ? "" : ", " + item.match().displayName().toLowerCase(Locale.ROOT);
            String standIns = item.hasAlternatives() ? ", " + item.alternatives().size() + " alternative(s)" : "";
            String note = item.noted() ? ", as a note" : "";
            details = ref.describe() + ": " + amount + rule + standIns + note;
        }
        return itemName == null ? details : "<html><b>" + escape(itemName) + "</b><br>" + escape(details) + "</html>";
    }

    private static String escape(String text) {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }


    private void refresh() {
        setBackground(background());
        setOutline(outline());
        repaint();
    }

    private Color background() {
        switch (dropState) {
            case ALLOWED:
                return Highlights.selection(Ui.SURFACE);
            case REFUSED:
                return Highlights.danger(Ui.SURFACE);
            default:
                return selected ? Highlights.selection(Ui.SURFACE) : hovered ? Ui.SURFACE_HOVER : Ui.SURFACE;
        }
    }

    private Color outline() {
        switch (dropState) {
            case ALLOWED:
                return ColorScheme.BRAND_ORANGE;
            case REFUSED:
                return Ui.DANGER;
            default:
                return selected ? ColorScheme.BRAND_ORANGE
                        : hovered ? ColorScheme.LIGHT_GRAY_COLOR
                        : item != null ? Ui.OUTLINE : ColorScheme.BORDER_COLOR;
        }
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        if (glyph == null || item != null || shadow != null) {
            return;
        }
        Graphics2D g2 = (Graphics2D) g.create();
        try {
            g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, GLYPH_OPACITY));
            double scale = Math.min(1.0, (double) ICON_SIZE / Math.max(glyph.getWidth(), glyph.getHeight()));
            int width = (int) Math.round(glyph.getWidth() * scale);
            int height = (int) Math.round(glyph.getHeight() * scale);
            g2.drawImage(glyph, (getWidth() - width) / 2, (getHeight() - height) / 2, width, height, null);
        } finally {
            g2.dispose();
        }
    }

    @Override
    protected void paintChildren(Graphics g) {
        super.paintChildren(g);
        if (item != null && item.noted()) {
            g.setFont(FontManager.getRunescapeSmallFont());
            int x = getWidth() - g.getFontMetrics().stringWidth("N") - QUANTITY_INSET;
            g.setColor(Color.BLACK);
            g.drawString("N", x + 1, QUANTITY_INSET + g.getFontMetrics().getAscent() + 1);
            g.setColor(NOTE_BADGE);
            g.drawString("N", x, QUANTITY_INSET + g.getFontMetrics().getAscent());
        }
        if (item == null || !item.showsQuantity()) {
            return;
        }
        {
            g.setFont(FontManager.getRunescapeSmallFont());
            int amount = item.quantity().orElseThrow();
            String text = ItemQuantityFormat.text(amount);
            g.setColor(Color.BLACK);
            g.drawString(text, QUANTITY_INSET + 1, QUANTITY_INSET + g.getFontMetrics().getAscent() + 1);
            g.setColor(ItemQuantityFormat.color(amount));
            g.drawString(text, QUANTITY_INSET, QUANTITY_INSET + g.getFontMetrics().getAscent());
        }
    }
}

