    }
}

package dev.dutchy.runelite.gear.ui;

import javax.swing.*;
import java.awt.*;
import java.util.Objects;
import java.util.Optional;

/** Dialogs over the sidebar, with the status line underneath it. */
final class SwingPrompts implements Prompts {

    private final GearSetupPanel panel;

    private SwingPrompts(GearSetupPanel panel) {
        this.panel = Objects.requireNonNull(panel, "panel");
    }

    static Prompts over(GearSetupPanel panel) {
        return new SwingPrompts(panel);
    }

    @Override
    public boolean confirm(String question, String title) {
        if (GraphicsEnvironment.isHeadless()) {
            return false;
        }
        return JOptionPane.showConfirmDialog(panel, question, title, JOptionPane.YES_NO_OPTION) == JOptionPane.YES_OPTION;
    }

    @Override
    public Optional<String> askForName(String question, String initial) {
        if (GraphicsEnvironment.isHeadless()) {
            return Optional.empty();
        }
        return Optional.ofNullable(JOptionPane.showInputDialog(panel, question, initial));
    }

    @Override
    public void say(String message) {
        panel.say(message);
    }

    @Override
    public void announce(String message) {
        panel.announce(message);
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.SetupMeta;

import javax.swing.*;
import java.awt.*;
import java.util.LinkedHashSet;
import java.util.Objects;
import java.util.Set;
import java.util.TreeSet;

/** Tag chips with a remove cross, plus a field that adds one on Enter. */
final class TagEditor extends JPanel {

    private final Set<String> tags = new TreeSet<>();
    private final JPanel chips = Ui.panel(new FlowLayout(FlowLayout.LEFT, 4, 2));
    private final TextInput field = new TextInput();

    TagEditor(Set<String> initial) {
        Objects.requireNonNull(initial, "initial");
        tags.addAll(SetupMeta.normalizeTags(initial));
        setLayout(new BorderLayout(0, Ui.SMALL_GAP));
        setOpaque(false);
        field.setToolTipText("Type a tag and press Enter");
        field.addActionListener(e -> addFromField());
        add(chips, BorderLayout.NORTH);
        add(field, BorderLayout.CENTER);
        refresh();
    }

    Set<String> tags() {
        return Set.copyOf(tags);
    }

    boolean add(String tag) {
        Set<String> candidate = new LinkedHashSet<>(tags);
        candidate.add(tag);
        try {
            Set<String> normalized = SetupMeta.normalizeTags(candidate);
            if (normalized.size() == tags.size()) {
                return false;
            }
            tags.clear();
            tags.addAll(normalized);
        } catch (IllegalArgumentException e) {
            return false;
        }
        refresh();
        return true;
    }

    void remove(String tag) {
        if (tags.remove(tag)) {
            refresh();
        }
    }

    @SuppressWarnings("SameParameterValue")
    void setFieldText(String text) {
        field.setText(text);
    }

    void addFromField() {
        if (add(field.getText())) {
            field.setText("");
        }
    }

    private void refresh() {
        chips.removeAll();
        for (String tag : tags) {
            chips.add(new FlatButton(ActionIcon.DELETE, tag, "Remove " + tag, () -> remove(tag)));
        }
        chips.setVisible(!tags.isEmpty());
        field.setEnabled(tags.size() < SetupMeta.MAX_TAGS);
        chips.revalidate();
        chips.repaint();
        revalidate();
    }
}

package dev.dutchy.runelite.gear.ui;

import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import java.awt.*;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;

/** A few lines of wrapped text drawn as a rounded card, like {@link TextInput}. */
final class TextArea extends JTextArea {

    TextArea(int rows) {
        super(rows, 10);
        setOpaque(false);
        setLineWrap(true);
        setWrapStyleWord(true);
        setBackground(Ui.SURFACE);
        setForeground(ColorScheme.TEXT_COLOR);
        setCaretColor(ColorScheme.TEXT_COLOR);
        setSelectionColor(Highlights.selection(Ui.SURFACE));
        setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
        addFocusListener(new FocusAdapter() {
            @Override
            public void focusGained(FocusEvent e) {
                repaint();
            }

            @Override
            public void focusLost(FocusEvent e) {
                repaint();
            }
        });
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        try {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(getBackground());
            g2.fillRoundRect(0, 0, getWidth(), getHeight(), Ui.RADIUS, Ui.RADIUS);
            g2.setColor(outline());
            g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, Ui.RADIUS, Ui.RADIUS);
        } finally {
            g2.dispose();
        }
        super.paintComponent(g);
    }

    private Color outline() {
        return hasFocus() ? ColorScheme.BRAND_ORANGE : Ui.OUTLINE;
    }
}

