package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.*;
import dev.dutchy.runelite.gear.persistence.Backup;
import dev.dutchy.runelite.gear.persistence.BookFormatException;
import dev.dutchy.runelite.gear.persistence.BookMerger;
import dev.dutchy.runelite.gear.transfer.BookTransfer;
import dev.dutchy.runelite.gear.transfer.FileDialogs;

import javax.inject.Inject;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.util.List;
import java.util.Objects;

/**
 * Setups coming in and going out: files and backups. Every failure is reported rather
 * than thrown, because there is nowhere above here for it to go.
 */
public final class Transfer {

    static final String EXPORT_FILE_NAME = "gear-composer-setups.json";

    /** The pages this module needs put on screen. */
    interface Pages {

        /** What was read, to be added or to replace everything. */
        void showImport(String source, List<GearSection> imported);

        void showBackups(List<Backup> backups);

        void backToList();
    }

    private final GearSetupBook book;
    private final BookTransfer books;
    private final FileDialogs dialogs;

    private Prompts prompts = SilentPrompts.INSTANCE;
    private Pages pages = new Pages() {
        @Override
        public void showImport(String source, List<GearSection> imported) {
        }

        @Override
        public void showBackups(List<Backup> backups) {
        }

        @Override
        public void backToList() {
        }
    };

    @Inject
    public Transfer(GearSetupBook book, BookTransfer books, FileDialogs dialogs) {
        this.book = Objects.requireNonNull(book, "book");
        this.books = Objects.requireNonNull(books, "books");
        this.dialogs = Objects.requireNonNull(dialogs, "dialogs");
    }

    /** Wired by the sidebar, which owns the dialogs, the pages and whose list is on show. */
    void shownBy(Prompts newPrompts, Pages newPages) {
        this.prompts = Objects.requireNonNull(newPrompts, "newPrompts");
        this.pages = Objects.requireNonNull(newPages, "newPages");
    }

    public void importFile() {
        dialogs.chooseFileToOpen().ifPresent(file -> {
            try {
                offerImport(file.getFileName().toString(), books.importFrom(file));
            } catch (IOException | BookFormatException e) {
                prompts.say("Could not read " + file.getFileName() + ": " + e.getMessage());
            }
        });
    }

    public void exportAll() {
        exportSections(EXPORT_FILE_NAME, book.sections());
    }

    /** A section and everything nested under it, named after the section. */
    public void exportSection(SectionId sectionId) {
        book.section(sectionId).ifPresent(section ->
                exportSections(section.name().replaceAll("[^A-Za-z0-9-]+", "-").toLowerCase() + ".json",
                        SectionTree.familyOf(book.sections(), sectionId)));
    }

    private void exportSections(String suggestedName, List<GearSection> sections) {
        dialogs.chooseFileToSave(suggestedName).ifPresent(file -> {
            try {
                books.exportTo(file, sections);
                prompts.say("Exported to " + file.getFileName());
            } catch (IOException e) {
                prompts.say("Could not write " + file.getFileName() + ": " + e.getMessage());
            }
        });
    }

    /** Shows what was read, so nothing is merged before the player has seen it. */
    public void offerImport(String source, List<GearSection> imported) {
        pages.showImport(source, List.copyOf(imported));
    }

    /** Keeps what is there and folds the import into it. */
    public void addImported(List<GearSection> imported) {
        book.replaceSections(BookMerger.merge(book.sections(), imported));
        pages.backToList();
        prompts.announce("Added " + imported.stream().mapToInt(GearSection::size).sum() + " setup(s)");
    }

    public void replaceWithImported(String source, List<GearSection> imported) {
        book.replaceSections(imported);
        pages.backToList();
        prompts.announce("Replaced everything from " + source);
    }

    public void showBackups() {
        pages.showBackups(books.backups());
    }

    public void restoreBackup(Backup backup) {
        try {
            book.replaceSections(books.readBackup(backup));
            pages.backToList();
            prompts.announce("Restored the backup");
        } catch (BookFormatException | UncheckedIOException e) {
            prompts.say("That backup could not be read: " + e.getMessage());
        }
    }
}

package dev.dutchy.runelite.gear.ui;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;

/** Spacing, colours, and small helpers shared by every page of the panel. */
final class Ui {

    static final int GAP = 10;
    static final int SMALL_GAP = 4;
    static final int RADIUS = 6;
    static final int FIELD_HEIGHT = 30;
    static final Color OUTLINE = new Color(52, 52, 52);
    static final Color DANGER = new Color(220, 62, 48);
    static final Color SURFACE = ColorScheme.DARKER_GRAY_COLOR;
    static final Color SURFACE_HOVER = ColorScheme.DARKER_GRAY_HOVER_COLOR;

    private Ui() {
    }

    static JPanel panel(LayoutManager layout) {
        JPanel panel = new JPanel(layout);
        panel.setOpaque(false);
        return panel;
    }

    /** Stacks children top to bottom at full width, separated by {@code gap} pixels. */
    static JPanel column(int gap, Component... children) {
        JPanel column = new JPanel();
        column.setLayout(new BoxLayout(column, BoxLayout.Y_AXIS));
        column.setOpaque(false);
        for (int i = 0; i < children.length; i++) {
            if (i > 0 && gap > 0) {
                column.add(Box.createVerticalStrut(gap));
            }
            if (children[i] instanceof JComponent) {
                ((JComponent) children[i]).setAlignmentX(Component.LEFT_ALIGNMENT);
            }
            column.add(children[i]);
        }
        return column;
    }

    /** A caption above a field, the way every form on the panel labels its inputs. */
    static JPanel labelled(String caption, JComponent field) {
        return labelled(caption, null, field);
    }

    static JPanel labelled(String caption, String trailingHint, JComponent field) {
        JPanel row = panel(new BorderLayout());
        row.add(caption(caption), BorderLayout.WEST);
        if (trailingHint != null) {
            row.add(hint(trailingHint), BorderLayout.EAST);
        }
        row.setBorder(BorderFactory.createEmptyBorder(0, 1, 3, 1));

        JPanel block = panel(new BorderLayout());
        block.add(row, BorderLayout.NORTH);
        block.add(field, BorderLayout.CENTER);
        return block;
    }

    static JLabel caption(String text) {
        JLabel label = new JLabel(text);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        return label;
    }

    static JLabel body(String text) {
        JLabel label = new JLabel(text);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(ColorScheme.TEXT_COLOR);
        return label;
    }

    /** Explanatory text in the body colour; wraps rather than truncates. */
    static WrappedText paragraph(String text) {
        return new WrappedText(text, FontManager.getRunescapeSmallFont(), ColorScheme.TEXT_COLOR);
    }

    /** Explanatory text in the hint colour; wraps rather than truncates. */
    static WrappedText note(String text) {
        return new WrappedText(text, FontManager.getRunescapeSmallFont(), ColorScheme.MEDIUM_GRAY_COLOR);
    }

    static JLabel hint(String text) {
        JLabel label = new JLabel(text);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
        return label;
    }
}

package dev.dutchy.runelite.gear.ui;

/** What a view of the open setup's variants can ask of its host. Indexes are positions in the setup's variant list. */
interface VariantActions {

    /** Makes the variant the setup's chosen one, so the bank shows it; the page stays on what it edits. */
    void selectVariant(int index);

    /** Opens the variant on the page for editing, leaving the bank's choice alone. */
    void editVariant(int index);

    /** Asks for a name and adds a variant holding the chosen start, then opens it for editing. */
    void addVariant(NewVariant start);

    void renameVariant(int index);

    /** Inserts a copy right after the variant. */
    void duplicateVariant(int index);

    void deleteVariant(int index);

    /** Moves the variant one place up or down the list. */
    void moveVariant(int index, int to);
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.GearSetup;
import dev.dutchy.runelite.gear.content.SetupContentEditor;
import dev.dutchy.runelite.gear.content.SetupVariant;
import dev.dutchy.runelite.libs.ui.icon.ItemIconFactory;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Objects;

/** One variant in the list: a preview, its name and totals, lit when the page edits it and badged when the bank shows it; click to edit, right-click for more. */
final class VariantCard extends Card {

    static final String SHOW = "Show";
    static final String RENAME = "Rename…";
    static final String DUPLICATE = "Duplicate";
    static final String MOVE_UP = "Move up";
    static final String MOVE_DOWN = "Move down";
    static final String DELETE = "Delete";
    static final String SHOWN = "Shown";
    static final int CELL = 12;

    private final SetupVariant variant;
    private final int index;
    private final int count;
    private final boolean chosen;
    private final boolean shown;
    private final VariantActions actions;
    private final JLabel totals = Ui.hint("");
    private final FlatButton more;
    private boolean hovered;

    VariantCard(SetupVariant variant, int index, int count, boolean chosen, boolean shown, ItemIconFactory icons,
                VariantActions actions) {
        this.variant = Objects.requireNonNull(variant, "variant");
        this.index = index;
        this.count = count;
        this.chosen = chosen;
        this.shown = shown;
        this.actions = Objects.requireNonNull(actions, "actions");
        Objects.requireNonNull(icons, "icons");
        setLayout(new BorderLayout(Ui.SMALL_GAP, 0));
        setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 4));
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        setToolTipText(chosen ? "Editing " + variant.name() + "; right-click for more" : "Click to edit " + variant.name() + "; right-click for more");

        JLabel name = new JLabel(variant.name());
        name.setFont(FontManager.getRunescapeBoldFont());
        name.setForeground(chosen ? ColorScheme.BRAND_ORANGE : ColorScheme.TEXT_COLOR);
        JPanel text = Ui.column(2, name, totals);
        if (shown) {
            JLabel badge = Ui.hint(SHOWN);
            badge.setForeground(ColorScheme.BRAND_ORANGE);
            text.add(badge);
        }

        more = new FlatButton(ActionIcon.MORE, "Rename, duplicate, move or delete this variant", this::showMenu);
        more.setPreferredSize(new Dimension(20, 20));

        add(new MiniLayoutView(variant.content(), icons, CELL), BorderLayout.WEST);
        add(text, BorderLayout.CENTER);
        add(more, BorderLayout.EAST);
        installMouseHandling();
        refresh();
    }

    SetupVariant variant() {
        return variant;
    }

    /** Whether the page edits this variant. */
    boolean isChosen() {
        return chosen;
    }

    /** Whether the bank shows this variant. */
    boolean isShown() {
        return shown;
    }

    String totals() {
        return totals.getText();
    }

    void refresh() {
        int items = SetupContentEditor.allItems(variant.content()).size();
        totals.setText(items == 1 ? "1 item" : items + " items");
        refreshBackground();
    }

    ContextMenu contextMenu() {
        ContextMenu menu = new ContextMenu();
        if (!shown) {
            menu.item(ActionIcon.CHECK, SHOW, () -> actions.selectVariant(index));
        }
        menu.item(ActionIcon.RENAME, RENAME, () -> actions.renameVariant(index));
        if (count < GearSetup.MAX_VARIANTS) {
            menu.item(ActionIcon.COPY, DUPLICATE, () -> actions.duplicateVariant(index));
        }
        if (index > 0) {
            menu.item(ActionIcon.MOVE_UP, MOVE_UP, () -> actions.moveVariant(index, index - 1));
        }
        if (index < count - 1) {
            menu.item(ActionIcon.MOVE_DOWN, MOVE_DOWN, () -> actions.moveVariant(index, index + 1));
        }
        if (count > 1) {
            menu.divider().danger(DELETE, () -> actions.deleteVariant(index));
        }
        return menu;
    }

    private void installMouseHandling() {
        addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                hovered = true;
                refreshBackground();
            }

            @Override
            public void mouseExited(MouseEvent e) {
                hovered = false;
                refreshBackground();
            }

            @Override
            public void mousePressed(MouseEvent e) {
                maybeShowMenu(e);
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                maybeShowMenu(e);
            }

            @Override
            public void mouseClicked(MouseEvent e) {
                if (SwingUtilities.isLeftMouseButton(e) && !chosen) {
                    actions.editVariant(index);
                }
            }
        });
    }

    private void showMenu() {
        contextMenu().show(more, 0, more.getHeight());
    }

    private void maybeShowMenu(MouseEvent e) {
        if (e.isPopupTrigger()) {
            contextMenu().show(this, e.getX(), e.getY());
        }
    }

    private void refreshBackground() {
        setOutline(chosen ? ColorScheme.BRAND_ORANGE : Ui.OUTLINE);
        setBackground(chosen ? Highlights.selection(Ui.SURFACE) : hovered ? Ui.SURFACE_HOVER : Ui.SURFACE);
        repaint();
    }
}

package dev.dutchy.runelite.gear.ui;

import dev.dutchy.runelite.gear.GearSetup;
import dev.dutchy.runelite.gear.content.SetupVariant;
import dev.dutchy.runelite.gear.guide.HelpTopic;
import dev.dutchy.runelite.libs.ui.icon.ItemIconFactory;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;

/** The collapsible list of a setup's variants, with a card per variant, the edited one lit, and a menu to start a new one. */
final class VariantsPanel extends JPanel {

    static final String TITLE = "Variants";
    static final String NEW_VARIANT = "New variant";

    private final GearSetup setup;
    private final int editing;
    private final VariantActions actions;
    private final List<VariantCard> cards = new ArrayList<>();
    private final JPanel body = Ui.column(Ui.SMALL_GAP);
    private final JLabel summary = Ui.hint("");
    private final FlatButton toggle;
    private final FlatButton add;
    private boolean open;

    VariantsPanel(GearSetup setup, int editing, ItemIconFactory icons, VariantActions actions, boolean open) {
        this.setup = Objects.requireNonNull(setup, "setup");
        this.editing = editing;
        this.actions = Objects.requireNonNull(actions, "actions");
        this.open = open;
        this.toggle = new FlatButton(open ? ActionIcon.EXPANDED : ActionIcon.COLLAPSED, "Show or hide the variants", this::toggleOpen);
        this.add = new FlatButton(ActionIcon.ADD, NEW_VARIANT, "Start another variant of this setup", this::showNewVariantMenu);
        add.setEnabled(setup.variants().size() < GearSetup.MAX_VARIANTS);
        Help.anchor(this, HelpTopic.VARIANTS);

        setLayout(new BorderLayout(0, Ui.SMALL_GAP));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel header = Ui.panel(new BorderLayout(Ui.SMALL_GAP, 0));
        header.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 0));
        JPanel titles = Ui.panel(new FlowLayout(FlowLayout.LEFT, Ui.SMALL_GAP, 0));
        titles.add(Ui.caption(TITLE));
        titles.add(summary);
        JPanel tools = Help.anchor(Ui.panel(new FlowLayout(FlowLayout.RIGHT, 2, 0)), HelpTopic.VARIANT_TOOLS);
        tools.add(add);
        tools.add(toggle);
        header.add(titles, BorderLayout.CENTER);
        header.add(tools, BorderLayout.EAST);

        List<SetupVariant> variants = setup.variants();
        for (int i = 0; i < variants.size(); i++) {
            VariantCard card = new VariantCard(variants.get(i), i, variants.size(), i == editing, i == setup.selectedIndex(), icons, actions);
            cards.add(card);
            body.add(card);
        }
        add(header, BorderLayout.NORTH);
        add(body, BorderLayout.CENTER);
        setOpen(open);
    }

    List<VariantCard> cards() {
        return List.copyOf(cards);
    }

    List<String> names() {
        return cards.stream().map(card -> card.variant().name()).collect(Collectors.toList());
    }

    /** The name on the lit card, the one the page edits. */
    String chosen() {
        return cards.stream().filter(VariantCard::isChosen).map(card -> card.variant().name()).findFirst().orElseThrow();
    }

    /** The name on the badged card, the one the bank shows. */
    String shown() {
        return cards.stream().filter(VariantCard::isShown).map(card -> card.variant().name()).findFirst().orElseThrow();
    }

    boolean isOpen() {
        return open;
    }

    boolean canAdd() {
        return add.isEnabled();
    }

    void setOpen(boolean shouldOpen) {
        open = shouldOpen;
        toggle.setIcon(open ? ActionIcon.EXPANDED : ActionIcon.COLLAPSED);
        body.setVisible(open);
        int count = setup.variants().size();
        summary.setText(open ? "· " + count : "· " + count + " · editing " + editedName());
        revalidate();
        repaint();
    }

    private String editedName() {
        return setup.variantAt(editing).map(SetupVariant::name).orElse(setup.variant().name());
    }

    ContextMenu newVariantMenu() {
        ContextMenu menu = new ContextMenu();
        for (NewVariant start : NewVariant.values()) {
            if (start.offeredFor(setup.variantAt(editing).map(SetupVariant::content).orElse(setup.content()))) {
                menu.item(start == NewVariant.FROM_GAME ? ActionIcon.SYNC : ActionIcon.ADD, start.label(), () -> actions.addVariant(start));
            }
        }
        return menu;
    }

    private void showNewVariantMenu() {
        newVariantMenu().show(add, 0, add.getHeight());
    }

    private void toggleOpen() {
        setOpen(!open);
    }
}

package dev.dutchy.runelite.gear.ui;

import javax.swing.*;
import javax.swing.text.DefaultCaret;
import java.awt.*;

/** Read-only text that wraps to the width it is given instead of trailing off in an ellipsis. */
final class WrappedText extends JTextArea {

    private static final int FALLBACK_WIDTH = 200;

    WrappedText(String text, Font font, Color colour) {
        super(text);
        setFont(font);
        setForeground(colour);
        setLineWrap(true);
        setWrapStyleWord(true);
        setEditable(false);
        setFocusable(false);
        setOpaque(false);
        setBorder(null);
        setMargin(new Insets(0, 0, 0, 0));
        setAlignmentX(LEFT_ALIGNMENT);
        ((DefaultCaret) getCaret()).setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
    }

    /** A change of text must never drag the sidebar around to show this component. */
    @Override
    public void scrollRectToVisible(Rectangle rectangle) {
    }

    /** Wraps at the parent's width, so the height is right the moment the parent has been laid out. */
    @Override
    public Dimension getPreferredSize() {
        int width = getParent() != null && getParent().getWidth() > 0
                ? getParent().getWidth() - getParent().getInsets().left - getParent().getInsets().right
                : getWidth() > 0 ? getWidth() : FALLBACK_WIDTH;
        setSize(new Dimension(Math.max(1, width), Short.MAX_VALUE));
        Dimension preferred = super.getPreferredSize();
        return new Dimension(width, preferred.height);
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }

    @Override
    public Dimension getMinimumSize() {
        return new Dimension(1, getPreferredSize().height);
    }
}

