import dev.dutchy.runelite.libs.ui.style.ItemButtonStyle;
import dev.dutchy.runelite.libs.ui.swing.EdtDispatch;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.IconTextField;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.swing.*;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import java.awt.*;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.CopyOnWriteArrayList;

/** All methods must be called on the EDT. */
public final class ItemSelector extends JPanel {

    private static final Logger log = LoggerFactory.getLogger(ItemSelector.class);
    private static final int DEFAULT_FIELD_HEIGHT = 30;

    private final ItemSearch search;
    private final ItemButtonFactory buttons;
    private final ItemButtonStyle rowSpriteStyle;
    private final int limit;
    private final ItemRowDragListener rowDrag;
    private final boolean keepResultsOnSelect;
    private final List<ItemSelectionListener> listeners = new CopyOnWriteArrayList<>();
    private final List<Runnable> clearListeners = new CopyOnWriteArrayList<>();

    private final IconTextField input = new IconTextField();
    private final JPanel fieldRow = new JPanel(new BorderLayout(4, 0));
    private final JLabel status = new JLabel();
    private final JPanel results = new JPanel();
    private final Timer debounce;
    private final List<ItemSearchResultRow> rows = new ArrayList<>();

    private JComponent leading;

    private int highlighted = -1;
    private int generation;
    private boolean suppressSearch;
    private ResolvedItem selected;

    ItemSelector(ItemSearch search, ItemButtonFactory buttons, ItemButtonStyle rowSpriteStyle, int limit, int debounceMillis,
                 ItemRowDragListener rowDrag, boolean keepResultsOnSelect) {
        this.rowDrag = rowDrag;
        this.keepResultsOnSelect = keepResultsOnSelect;
        this.search = Objects.requireNonNull(search, "search");
        this.buttons = Objects.requireNonNull(buttons, "buttons");
        this.rowSpriteStyle = Objects.requireNonNull(rowSpriteStyle, "rowSpriteStyle");
        this.limit = limit;
        this.debounce = new Timer(debounceMillis, e -> runSearch());
        this.debounce.setRepeats(false);
        buildLayout();
        installInputHandling();
        showStatus("Type an item name or id");
    }

    public Optional<ResolvedItem> selectedItem() {
        return Optional.ofNullable(selected);
    }

    public void addSelectionListener(ItemSelectionListener listener) {
        listeners.add(Objects.requireNonNull(listener, "listener"));
    }

    /** Runs whenever the query and selection are wiped, whether by the clear button, Escape, or {@link #clear()}. */
    public void addClearListener(Runnable listener) {
        clearListeners.add(Objects.requireNonNull(listener, "listener"));
    }

    /** Places a component to the left of the search field; the field grows to match its height. */
    public void setLeadingComponent(JComponent component) {
        EdtDispatch.requireEdt();
        if (leading != null) {
            fieldRow.remove(leading);
        }
        leading = component;
        int height = component == null ? DEFAULT_FIELD_HEIGHT : component.getPreferredSize().height;
        if (component != null) {
            fieldRow.add(component, BorderLayout.WEST);
        }
        input.setPreferredSize(new Dimension(100, height));
        fieldRow.revalidate();
        fieldRow.repaint();
    }

    /** The whole selector, search field included, paints on this colour. */
    @Override
    public void setBackground(Color color) {
        super.setBackground(color);
        if (input != null) {
            input.setBackground(color);
            input.setHoverBackgroundColor(color);
        }
    }

    public void setQuery(String query) {
        EdtDispatch.requireEdt();
        setInputText(Objects.requireNonNull(query, "query"));
        debounce.stop();
        runSearch();
    }

    public String query() {
        return input.getText();
    }

    public void clear() {
        EdtDispatch.requireEdt();
        debounce.stop();
        generation++;
        selected = null;
        setInputText("");
        clearResults();
        showStatus("Type an item name or id");
        clearListeners.forEach(Runnable::run);
    }

    public void highlightNext() {
        EdtDispatch.requireEdt();
        moveHighlight(1);
    }

    public void highlightPrevious() {
        EdtDispatch.requireEdt();
        moveHighlight(-1);
    }

    public void selectHighlighted() {
        EdtDispatch.requireEdt();
        if (rows.isEmpty()) {
            return;
        }
        int index = Math.max(highlighted, 0);
        select(rows.get(index).item());
    }

    public void select(ResolvedItem item) {
        EdtDispatch.requireEdt();
        Objects.requireNonNull(item, "item");
        debounce.stop();
        generation++;
        selected = item;
        if (keepResultsOnSelect) {
            highlightRowOf(item);
        } else {
            setInputText(item.name());
            clearResults();
        }
        showStatus("Selected " + item.name() + " " + item.id());
        for (ItemSelectionListener listener : listeners) {
            listener.onItemSelected(item);
        }
    }

    @Override
    public boolean requestFocusInWindow() {
        return input.requestFocusInWindow();
    }

    public int resultCount() {
        return rows.size();
    }

    List<ItemSearchResultRow> rows() {
        return List.copyOf(rows);
    }

    private void runSearch() {
        String query = input.getText().strip();
        int myGeneration = ++generation;
        if (query.isEmpty()) {
            clearResults();
            showStatus("Type an item name or id");
            return;
        }
        input.setIcon(IconTextField.Icon.LOADING);
        showStatus("Searching…");
        search.search(query, limit).whenComplete((hits, error) ->
                EdtDispatch.onEdt(() -> onSearchComplete(myGeneration, hits, error)));
    }

    private void onSearchComplete(int myGeneration, List<ResolvedItem> hits, Throwable error) {
        if (myGeneration != generation) {
            return;
        }
        input.setIcon(IconTextField.Icon.SEARCH);
        if (error != null) {
            log.warn("Item search failed", error);
            clearResults();
            showStatus("Search failed");
            return;
        }
        showResults(hits);
    }

    private void showResults(List<ResolvedItem> hits) {
        clearResults();
        for (ResolvedItem hit : hits) {
            ItemSearchResultRow row = new ItemSearchResultRow(hit, buttons, rowSpriteStyle, this::select, rowDrag);
            rows.add(row);
            results.add(row);
        }
        if (rows.isEmpty()) {
            showStatus("No items match");
        } else {
            showStatus(rows.size() + (rows.size() == limit ? "+ results" : " results"));
            setHighlight(0);
        }
        results.revalidate();
        results.repaint();
    }

    private void clearResults() {
        rows.clear();
        results.removeAll();
        highlighted = -1;
        results.revalidate();
        results.repaint();
    }

    private void highlightRowOf(ResolvedItem item) {
        for (int i = 0; i < rows.size(); i++) {
            if (rows.get(i).item().equals(item)) {
                setHighlight(i);
                return;
            }
        }
    }

    private void moveHighlight(int delta) {
        if (rows.isEmpty()) {
            return;
        }
        int next = highlighted < 0 ? (delta > 0 ? 0 : rows.size() - 1) : Math.floorMod(highlighted + delta, rows.size());
        setHighlight(next);
    }

    private void setHighlight(int index) {
        if (highlighted >= 0 && highlighted < rows.size()) {
            rows.get(highlighted).setHighlighted(false);
        }
        highlighted = index;
        if (highlighted >= 0 && highlighted < rows.size()) {
            rows.get(highlighted).setHighlighted(true);
        }
    }

    private void setInputText(String text) {
        suppressSearch = true;
        try {
            input.setText(text);
        } finally {
            suppressSearch = false;
        }
    }

    private void showStatus(String text) {
        status.setText(text);
    }

    private void buildLayout() {
        setLayout(new BorderLayout(0, 4));

        input.setIcon(IconTextField.Icon.SEARCH);
        input.setPreferredSize(new Dimension(100, DEFAULT_FIELD_HEIGHT));
        setBackground(ColorScheme.DARKER_GRAY_COLOR);

        fieldRow.setOpaque(false);
        fieldRow.add(input, BorderLayout.CENTER);

        status.setFont(FontManager.getRunescapeSmallFont());
        status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        status.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 2));

        results.setLayout(new BoxLayout(results, BoxLayout.Y_AXIS));
        results.setOpaque(false);

        JPanel header = new JPanel(new BorderLayout(0, 2));
        header.setOpaque(false);
        header.add(fieldRow, BorderLayout.NORTH);
        header.add(status, BorderLayout.SOUTH);

        add(header, BorderLayout.NORTH);
        add(results, BorderLayout.CENTER);
    }

    private void installInputHandling() {
        input.getDocument().addDocumentListener(new DocumentListener() {
            @Override
            public void insertUpdate(DocumentEvent e) {
                onTextChanged();
            }

            @Override
            public void removeUpdate(DocumentEvent e) {
                onTextChanged();
            }

            @Override
            public void changedUpdate(DocumentEvent e) {
                onTextChanged();
            }
        });
        input.addClearListener(this::clear);
        input.addActionListener(e -> selectHighlighted());
        input.addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                switch (e.getKeyCode()) {
                    case KeyEvent.VK_DOWN:
                        highlightNext();
                        e.consume();
                        break;
                    case KeyEvent.VK_UP:
                        highlightPrevious();
                        e.consume();
                        break;
                    case KeyEvent.VK_ESCAPE:
                        clear();
                        e.consume();
                        break;
                    default:
                        break;
                }
            }
        });
    }

    private void onTextChanged() {
        if (suppressSearch) {
            return;
        }
        selected = null;
        debounce.restart();
    }
}

package dev.dutchy.runelite.libs.ui.selector;

import dev.dutchy.runelite.libs.ui.button.ItemButtonFactory;
import dev.dutchy.runelite.libs.ui.search.ItemSearch;
import dev.dutchy.runelite.libs.ui.style.ItemButtonStyle;
import dev.dutchy.runelite.libs.ui.swing.EdtDispatch;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

public final class ItemSelectorBuilder {

    public static final int DEFAULT_LIMIT = 8;
    public static final int DEFAULT_DEBOUNCE_MILLIS = 150;

    private final ItemSearch search;
    private final ItemButtonFactory buttons;
    private final List<ItemSelectionListener> listeners = new ArrayList<>();

    private int limit = DEFAULT_LIMIT;

    private ItemRowDragListener rowDrag;
    private boolean keepResultsOnSelect;

    ItemSelectorBuilder(ItemSearch search, ItemButtonFactory buttons) {
        this.search = Objects.requireNonNull(search, "search");
        this.buttons = Objects.requireNonNull(buttons, "buttons");
    }

    public ItemSelectorBuilder limit(int maxResults) {
        if (maxResults <= 0) {
            throw new IllegalArgumentException("Limit must be positive, got " + maxResults);
        }
        this.limit = maxResults;
        return this;
    }

    /** Lets result rows be dragged; the host decides what a drop means. */
    public ItemSelectorBuilder onRowDrag(ItemRowDragListener listener) {
        this.rowDrag = Objects.requireNonNull(listener, "listener");
        return this;
    }

    /** Selecting leaves the result list in place, so rows stay there to be dragged or picked again. */
    public ItemSelectorBuilder keepResultsOnSelect() {
        this.keepResultsOnSelect = true;
        return this;
    }

    public ItemSelectorBuilder onSelect(ItemSelectionListener listener) {
        listeners.add(Objects.requireNonNull(listener, "listener"));
        return this;
    }

    public ItemSelector build() {
        EdtDispatch.requireEdt();
        ItemSelector selector = new ItemSelector(search, buttons, ItemButtonStyle.compact(), limit,
                DEFAULT_DEBOUNCE_MILLIS, rowDrag, keepResultsOnSelect);
        listeners.forEach(selector::addSelectionListener);
        return selector;
    }
}

package dev.dutchy.runelite.libs.ui.selector;

import dev.dutchy.runelite.libs.ui.button.ItemButtonFactory;
import dev.dutchy.runelite.libs.ui.item.ItemResolver;
import dev.dutchy.runelite.libs.ui.search.ItemResolvers;
import dev.dutchy.runelite.libs.ui.search.ItemSearch;
import dev.dutchy.runelite.libs.ui.search.ItemSearches;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Objects;
import java.util.concurrent.Executor;

/**
 * Entry point for creating {@link ItemSelector}s. Inject it after installing
 * {@link dev.dutchy.runelite.libs.ui.ItemUiModule}, or compose one with {@link #forRuneLite}.
 */
@Singleton
public final class ItemSelectorFactory {

    private final ItemSearch search;
    private final ItemButtonFactory buttons;

    @Inject
    public ItemSelectorFactory(ItemSearch search, ItemButtonFactory buttons) {
        this.search = Objects.requireNonNull(search, "search");
        this.buttons = Objects.requireNonNull(buttons, "buttons");
    }

    /**
     * The library composed by hand, for a plugin that does not install {@link dev.dutchy.runelite.libs.ui.ItemUiModule}.
     *
     * @param executor where catalogue ranking runs; must not be the EDT or the client thread
     */
    @SuppressWarnings("unused")
    public static ItemSelectorFactory forRuneLite(Client client, ClientThread clientThread, ItemManager itemManager, Executor executor) {
        ItemResolver resolver = ItemResolvers.forRuneLite(client, clientThread);
        return new ItemSelectorFactory(
                ItemSearches.forRuneLite(client, clientThread, resolver, executor),
                ItemButtonFactory.forRuneLite(client, clientThread, itemManager));
    }

    public ItemSelectorBuilder selector() {
        return new ItemSelectorBuilder(search, buttons);
    }
}

package dev.dutchy.runelite.libs.ui.style;

import lombok.Value;
import net.runelite.client.ui.ColorScheme;

import java.awt.*;
import java.util.Objects;

@Value
public class ItemButtonStyle {
    Dimension size;
    Insets padding;
    Color background;
    Color hoverBackground;
    Color pressedBackground;
    Color border;
    Color selectedBorder;
    int borderThickness;
    int cornerRadius;
    Color placeholder;

    public ItemButtonStyle(Dimension size, Insets padding, Color background, Color hoverBackground, Color pressedBackground, Color border, Color selectedBorder, int borderThickness, int cornerRadius, Color placeholder) {
        Objects.requireNonNull(size, "size");
        Objects.requireNonNull(padding, "padding");
        Objects.requireNonNull(background, "background");
        Objects.requireNonNull(hoverBackground, "hoverBackground");
        Objects.requireNonNull(pressedBackground, "pressedBackground");
        Objects.requireNonNull(selectedBorder, "selectedBorder");
        Objects.requireNonNull(placeholder, "placeholder");
        if (size.width <= 0 || size.height <= 0) {
            throw new IllegalArgumentException("Size must be positive, got " + size);
        }
        if (borderThickness < 0) {
            throw new IllegalArgumentException("Border thickness must be non-negative, got " + borderThickness);
        }
        if (cornerRadius < 0) {
            throw new IllegalArgumentException("Corner radius must be non-negative, got " + cornerRadius);
        }
        size = new Dimension(size);
        padding = (Insets) padding.clone();
        this.size = size;
        this.padding = padding;
        this.background = background;
        this.hoverBackground = hoverBackground;
        this.pressedBackground = pressedBackground;
        this.border = border;
        this.selectedBorder = selectedBorder;
        this.borderThickness = borderThickness;
        this.cornerRadius = cornerRadius;
        this.placeholder = placeholder;
    }

    public static ItemButtonStyle runeLite() {
        return builder().build();
    }

    public static ItemButtonStyle compact() {
        return builder().size(26, 26).padding(1).build();
    }

    public static Builder builder() {
        return new Builder();
    }

    public Builder toBuilder() {
        return new Builder(this);
    }

    /** Area left for the sprite once padding and border are removed. */
    public Dimension contentSize() {
        int horizontal = padding.left + padding.right + 2 * borderThickness;
        int vertical = padding.top + padding.bottom + 2 * borderThickness;
        return new Dimension(Math.max(1, size.width - horizontal), Math.max(1, size.height - vertical));
    }

    public Dimension size() {
        return new Dimension(size);
    }

    public Insets padding() {
        return (Insets) padding.clone();
    }

    public static final class Builder {

        private Dimension size = new Dimension(40, 36);
        private Insets padding = new Insets(2, 2, 2, 2);
        private Color background = ColorScheme.DARKER_GRAY_COLOR;
        private Color hoverBackground = ColorScheme.DARKER_GRAY_HOVER_COLOR;
        private Color pressedBackground = ColorScheme.MEDIUM_GRAY_COLOR;
        private Color border = ColorScheme.BORDER_COLOR;
        private Color selectedBorder = ColorScheme.BRAND_ORANGE;
        private int borderThickness = 1;
        private int cornerRadius = 4;
        private Color placeholder = ColorScheme.LIGHT_GRAY_COLOR;

        private Builder() {
        }

        private Builder(ItemButtonStyle style) {
            size = style.size();
            padding = style.padding();
            background = style.background;
            hoverBackground = style.hoverBackground;
            pressedBackground = style.pressedBackground;
            border = style.border;
            selectedBorder = style.selectedBorder;
            borderThickness = style.borderThickness;
            cornerRadius = style.cornerRadius;
            placeholder = style.placeholder;
        }

        public Builder size(int width, int height) {
            this.size = new Dimension(width, height);
            return this;
        }

        public Builder padding(int all) {
            this.padding = new Insets(all, all, all, all);
            return this;
        }

        public Builder background(Color background) {
            this.background = background;
            return this;
        }

        public Builder selectedBorder(Color selectedBorder) {
            this.selectedBorder = selectedBorder;
            return this;
        }

        public Builder borderThickness(int borderThickness) {
            this.borderThickness = borderThickness;
            return this;
        }

        public Builder placeholder(Color placeholder) {
            this.placeholder = placeholder;
            return this;
        }

        public ItemButtonStyle build() {
            return new ItemButtonStyle(size, padding, background, hoverBackground, pressedBackground,
                    border, selectedBorder, borderThickness, cornerRadius, placeholder);
        }
    }
}

package dev.dutchy.runelite.libs.ui.swing;

import javax.swing.*;
import java.util.Objects;

/** Where Swing work belongs: the event dispatch thread. */
public final class EdtDispatch {

    private EdtDispatch() {
    }

    /** Runs the task on the EDT, inline when already there. */
    public static void onEdt(Runnable task) {
        Objects.requireNonNull(task, "task");
        if (SwingUtilities.isEventDispatchThread()) {
            task.run();
        } else {
            SwingUtilities.invokeLater(task);
        }
    }

    public static void requireEdt() {
        if (!SwingUtilities.isEventDispatchThread()) {
            throw new IllegalStateException("Must be called on the Swing event dispatch thread");
        }
    }
}

